    fn init_repo() -> (tempfile::TempDir, PathBuf) {
        let dir = tempfile::tempdir().unwrap();
        let repo = init_repo_named(dir.path(), "repo");
        (dir, repo)
    }

    /// A repository under `parent`, named. A project is named after its
    /// repository directory, so a test about telling two projects apart needs
    /// to say what each one is called.
    fn init_repo_named(parent: &std::path::Path, name: &str) -> PathBuf {
        let repo = parent.join(name);
        std::fs::create_dir(&repo).unwrap();
        let git = |args: &[&str]| {
            assert!(Command::new("git")
                .args(args)
                .current_dir(&repo)
                .status()
                .unwrap()
                .success());
        };
        git(&["init", "-b", "main"]);
        git(&["config", "user.email", "t@build.ing"]);
        git(&["config", "user.name", "T"]);
        std::fs::write(repo.join("README.md"), "# project\n").unwrap();
        git(&["add", "."]);
        git(&["commit", "-m", "initial"]);
        repo
    }

    #[test]
    fn resolve_term_shell_yields_an_absolute_shell_path() {
        // Whatever the source (override, $SHELL, passwd, fallback), the result
        // must be an executable path, never empty.
        let shell = resolve_term_shell();
        assert!(shell.starts_with('/'), "{shell}");
    }

    #[test]
    fn capture_login_path_returns_the_shells_path() {
        let path = capture_login_path("/bin/bash", Duration::from_secs(10))
            .expect("bash must yield a PATH");
        assert!(path.contains('/'), "{path}");
        assert!(path.contains("bin"), "{path}");
    }

    #[test]
    fn capture_login_path_rejects_a_bare_launchd_path() {
        // A shell whose rc files never widen PATH leaves us with launchd's bare
        // default. Adopting it is worse than useless: it *looks* like the fix
        // worked while `claude` still can't be found. Reject it so the daemon
        // logs the truth and keeps whatever it inherited.
        let shell = tempfile::NamedTempFile::new().unwrap();
        std::fs::write(
            shell.path(),
            "#!/bin/sh\nprintf %s /usr/bin:/bin:/usr/sbin:/sbin\n",
        )
        .unwrap();
        std::fs::set_permissions(
            shell.path(),
            std::os::unix::fs::PermissionsExt::from_mode(0o755),
        )
        .unwrap();

        assert_eq!(
            capture_login_path(&shell.path().to_string_lossy(), Duration::from_secs(5)),
            None
        );
    }

    #[test]
    fn capture_login_path_survives_a_missing_shell() {
        assert_eq!(
            capture_login_path("/nonexistent-shell-for-test", Duration::from_secs(5)),
            None
        );
    }

    /// The grid a tab's terminal paints into. Every tab a test spawns has one:
    /// only a hand-built terminal-free session does not, and no test that
    /// speaks about a screen owns one of those.
    fn screen_of(tab: &Tab) -> &ScreenHandle {
        tab.screen
            .as_ref()
            .expect("a tab spawned in a PTY has a screen")
    }

    fn req(method: &str, params: Value) -> Frame {
        Frame {
            session_id: "s".into(),
            message_id: "m".into(),
            frame_type: "data".into(),
            sender: "client".into(),
            created_at: "t".into(),
            payload: json!({ "method": method, "id": "1", "params": params }),
        }
    }

    #[test]
    fn project_add_validates_and_dedupes() {
        let (dir_a, repo_a) = init_repo();
        let mut state = AppState::new(
            repo_a.clone(),
            dir_a.path().join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        );
        // A non-repo path is rejected.
        let bad = state.handle(req(
            "project.add",
            json!({ "path": "/definitely/not/a/repo" }),
        ));
        assert_eq!(bad["ok"], false);
        // A real repo is added and listed.
        let (_dir_c, repo_c) = init_repo();
        let ok = state.handle(req(
            "project.add",
            json!({ "path": repo_c.to_str().unwrap() }),
        ));
        assert_eq!(ok["ok"], true, "{ok:?}");
        assert_eq!(
            state.handle(req("project.list", json!({})))["result"]["projects"]
                .as_array()
                .unwrap()
                .len(),
            2
        );
        // Adding the same repo again is idempotent (deduped by canonical path).
        state.handle(req(
            "project.add",
            json!({ "path": repo_c.to_str().unwrap() }),
        ));
        assert_eq!(
            state.handle(req("project.list", json!({})))["result"]["projects"]
                .as_array()
                .unwrap()
                .len(),
            2
        );
    }

    #[test]
    fn fs_list_browses_dirs_and_flags_git_repos() {
        let (dir_a, repo_a) = init_repo();
        let mut state = AppState::new(
            repo_a,
            dir_a.path().join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        );
        // A browse root with a plain folder, a git repo, and a hidden folder.
        let root = dir_a.path().join("browse");
        std::fs::create_dir(&root).unwrap();
        std::fs::create_dir(root.join("plain")).unwrap();
        std::fs::create_dir(root.join(".hidden")).unwrap();
        let repo_dir = root.join("myrepo");
        std::fs::create_dir(&repo_dir).unwrap();
        std::fs::create_dir(repo_dir.join(".git")).unwrap();

        let res = state.handle(req("fs.list", json!({ "path": root.to_str().unwrap() })));
        assert_eq!(res["ok"], true, "{res:?}");
        assert!(res["result"]["parent"].is_string());
        let entries = res["result"]["entries"].as_array().unwrap();
        assert_eq!(
            entries.iter().find(|e| e["name"] == "myrepo").unwrap()["is_git"],
            true
        );
        assert_eq!(
            entries.iter().find(|e| e["name"] == "plain").unwrap()["is_git"],
            false
        );
        // Hidden dirs are still returned, flagged so the client can toggle them.
        let hidden = entries.iter().find(|e| e["name"] == ".hidden").unwrap();
        assert_eq!(hidden["is_hidden"], true);
        assert_eq!(
            entries.iter().find(|e| e["name"] == "plain").unwrap()["is_hidden"],
            false
        );
    }

    #[test]
    fn settings_set_then_clone_registers_project() {
        let (dir_src, repo_src) = init_repo();
        let (dir_a, repo_a) = init_repo();
        let mut state = AppState::new(
            repo_a,
            dir_a.path().join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        );
        // Point the projects folder at a temp location.
        let projects_dir = dir_src.path().join("projects");
        let set = state.handle(req(
            "settings.set",
            json!({ "projects_dir": projects_dir.to_str().unwrap() }),
        ));
        assert_eq!(set["ok"], true, "{set:?}");
        assert!(
            state.handle(req("settings.get", json!({})))["result"]["projects_dir"]
                .as_str()
                .unwrap()
                .contains("projects")
        );

        // Clone the source repo into the projects folder and register it.
        let cloned = state.handle(req(
            "project.clone",
            json!({ "url": repo_src.to_str().unwrap() }),
        ));
        assert_eq!(cloned["ok"], true, "{cloned:?}");
        let clone_path = cloned["result"]["path"].as_str().unwrap().to_string();
        assert!(std::path::Path::new(&clone_path).join("README.md").exists());
        assert_eq!(
            state.handle(req("project.list", json!({})))["result"]["projects"]
                .as_array()
                .unwrap()
                .len(),
            2
        );

        // Cloning the same repo again registers the existing checkout — no error, no
        // duplicate, same path (not a second clone).
        let again = state.handle(req(
            "project.clone",
            json!({ "url": repo_src.to_str().unwrap() }),
        ));
        assert_eq!(again["ok"], true, "{again:?}");
        assert_eq!(again["result"]["path"].as_str().unwrap(), clone_path);
        assert_eq!(
            state.handle(req("project.list", json!({})))["result"]["projects"]
                .as_array()
                .unwrap()
                .len(),
            2
        );
    }

    #[test]
    fn config_persists_projects_and_dir_across_reload() {
        let tmp = tempfile::tempdir().unwrap();
        let (_dir_a, repo_a) = init_repo();
        let (_dir_b, repo_b) = init_repo();
        let cfg = tmp.path().join("config.json");
        {
            let mut state = AppState::new(
                repo_a.clone(),
                tmp.path().join("wt"),
                "main",
                true,
                "/tmp/test-mcp.sock",
            )
            .with_config(&cfg);
            state.handle(req(
                "project.add",
                json!({ "path": repo_b.to_str().unwrap() }),
            ));
            state.handle(req(
                "settings.set",
                json!({ "projects_dir": tmp.path().join("myprojects").to_str().unwrap() }),
            ));
        }
        // A fresh instance restores the added project and the chosen dir from disk.
        let mut reloaded = AppState::new(
            repo_a,
            tmp.path().join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        )
        .with_config(&cfg);
        assert_eq!(
            reloaded.handle(req("project.list", json!({})))["result"]["projects"]
                .as_array()
                .unwrap()
                .len(),
            2
        );
        assert!(
            reloaded.handle(req("settings.get", json!({})))["result"]["projects_dir"]
                .as_str()
                .unwrap()
                .contains("myprojects")
        );
    }

    /// The account's answer to "which harness does a new agent open on" is a
    /// bridge setting, so every device gets the same answer. A bridge nobody
    /// has configured answers with the default, and still answers the older
    /// keys a step-13 client reads.
    #[test]
    fn settings_report_the_default_harness_and_the_compat_modes() {
        let (dir, repo) = init_repo();
        let mut state = AppState::new(
            repo,
            dir.path().join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        );
        let settings = state.handle(req("settings.get", json!({})))["result"].clone();
        assert_eq!(settings["default_harness"], "claude_adk");
        assert_eq!(settings["claude_mode"], "headless");
        assert_eq!(settings["codex_mode"], "tui");
    }

    /// The default outlives the process it was chosen in — it is an account
    /// setting, not a session's mood — and choosing it moves nothing else.
    #[test]
    fn a_chosen_default_harness_survives_a_reload_and_leaves_the_projects_dir_alone() {
        let tmp = tempfile::tempdir().unwrap();
        let (_dir, repo) = init_repo();
        let cfg = tmp.path().join("config.json");
        {
            let mut state = AppState::new(
                repo.clone(),
                tmp.path().join("wt"),
                "main",
                true,
                "/tmp/test-mcp.sock",
            )
            .with_config(&cfg);
            state.handle(req(
                "settings.set",
                json!({ "projects_dir": tmp.path().join("myprojects").to_str().unwrap() }),
            ));
            let set = state.handle(req("settings.set", json!({ "default_harness": "claude" })));
            assert_eq!(set["ok"], true, "{set:?}");
            assert_eq!(set["result"]["default_harness"], "claude");
            assert_eq!(set["result"]["claude_mode"], "tui");
        }
        let mut reloaded = AppState::new(
            repo,
            tmp.path().join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        )
        .with_config(&cfg);
        let settings = reloaded.handle(req("settings.get", json!({})))["result"].clone();
        assert_eq!(settings["default_harness"], "claude");
        assert_eq!(settings["claude_mode"], "tui");
        assert!(
            settings["projects_dir"]
                .as_str()
                .unwrap()
                .contains("myprojects"),
            "setting one field moves no other: {settings:?}"
        );
    }

    /// A harness the bridge cannot run is refused, and a refusal applies
    /// nothing: the settings are exactly what they were.
    #[test]
    fn an_unknown_default_harness_is_refused_and_changes_nothing() {
        let tmp = tempfile::tempdir().unwrap();
        let (_dir, repo) = init_repo();
        let mut state = AppState::new(
            repo,
            tmp.path().join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        );
        let before = state.handle(req("settings.get", json!({})))["result"].clone();
        let refused = state.handle(req(
            "settings.set",
            json!({
                "projects_dir": tmp.path().join("elsewhere").to_str().unwrap(),
                "default_harness": "telepathy",
            }),
        ));
        assert_eq!(refused["ok"], false, "{refused:?}");
        assert_eq!(
            refused["error"].as_str().unwrap(),
            "unknown default_harness \"telepathy\" (expected \"claude_adk\", \"claude\" or \
             \"codex\")"
        );
        assert_eq!(
            state.handle(req("settings.get", json!({})))["result"],
            before,
            "a refused set leaves every field where it was"
        );
    }

    /// Step 13's `claude_mode` said the same thing in an older vocabulary, so
    /// a client that still speaks it still lands — and a refusal it would have
    /// got, it still gets.
    #[test]
    fn a_step_13_client_still_sets_the_default_harness_through_claude_mode() {
        let (dir, repo) = init_repo();
        let mut state = AppState::new(
            repo,
            dir.path().join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        );
        let set = state.handle(req("settings.set", json!({ "claude_mode": "tui" })));
        assert_eq!(set["ok"], true, "{set:?}");
        assert_eq!(set["result"]["default_harness"], "claude");
        assert_eq!(state.default_harness, AgentProvider::Claude);

        let back = state.handle(req("settings.set", json!({ "claude_mode": "headless" })));
        assert_eq!(back["result"]["default_harness"], "claude_adk");

        let refused = state.handle(req("settings.set", json!({ "claude_mode": "telepathy" })));
        assert_eq!(refused["ok"], false, "{refused:?}");
        assert!(
            refused["error"]
                .as_str()
                .unwrap()
                .contains("unknown claude_mode"),
            "{refused:?}"
        );
    }

    /// A bridge upgraded in place keeps the carrier its human chose, with no
    /// migration step: the old key is read when the new one is absent, and
    /// never written again.
    #[test]
    fn a_config_holding_only_the_old_key_loads_the_harness_it_named() {
        let tmp = tempfile::tempdir().unwrap();
        let (_dir, repo) = init_repo();
        let load = |cfg: &std::path::Path| {
            let mut state = AppState::new(
                repo.clone(),
                tmp.path().join("wt"),
                "main",
                true,
                "/tmp/test-mcp.sock",
            )
            .with_config(cfg);
            state.handle(req("settings.get", json!({})))["result"].clone()
        };

        let old = tmp.path().join("old.json");
        std::fs::write(&old, json!({ "claude_mode": "tui" }).to_string()).unwrap();
        assert_eq!(load(&old)["default_harness"], "claude");

        let both = tmp.path().join("both.json");
        std::fs::write(
            &both,
            json!({ "claude_mode": "tui", "default_harness": "codex" }).to_string(),
        )
        .unwrap();
        assert_eq!(
            load(&both)["default_harness"],
            "codex",
            "the new key is the one that is written, so it is the one believed"
        );
    }

    /// Codex has one mode, so the field exists and accepts exactly it — the
    /// day a second one exists the lock comes off and nothing has to migrate.
    #[test]
    fn codex_mode_accepts_only_tui() {
        let (dir, repo) = init_repo();
        let mut state = AppState::new(
            repo,
            dir.path().join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        );
        let accepted = state.handle(req("settings.set", json!({ "codex_mode": "tui" })));
        assert_eq!(accepted["ok"], true, "{accepted:?}");
        assert_eq!(accepted["result"]["codex_mode"], "tui");

        let refused = state.handle(req("settings.set", json!({ "codex_mode": "headless" })));
        assert_eq!(refused["ok"], false, "{refused:?}");
        assert_eq!(
            refused["error"].as_str().unwrap(),
            "codex_mode accepts only \"tui\" — Codex has no other mode yet"
        );
    }

    /// The fields are additive: a client written before the modes existed
    /// still sets the projects folder the way it always has. A set that names
    /// nothing the bridge knows is a no-op dressed as a mutation, and says so.
    #[test]
    fn settings_set_stays_field_wise_for_an_old_client_and_refuses_an_empty_set() {
        let tmp = tempfile::tempdir().unwrap();
        let (_dir, repo) = init_repo();
        let mut state = AppState::new(
            repo,
            tmp.path().join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        );
        let old_client = state.handle(req(
            "settings.set",
            json!({ "projects_dir": tmp.path().join("projects").to_str().unwrap() }),
        ));
        assert_eq!(old_client["ok"], true, "{old_client:?}");
        assert!(old_client["result"]["projects_dir"]
            .as_str()
            .unwrap()
            .contains("projects"));
        assert_eq!(
            old_client["result"]["claude_mode"], "headless",
            "an old client's set leaves the mode at the account's answer"
        );

        let empty = state.handle(req("settings.set", json!({})));
        assert_eq!(empty["ok"], false, "{empty:?}");
        assert_eq!(
            empty["error"].as_str().unwrap(),
            "settings.set: nothing to set"
        );
    }

    /// Naming no provider means "the account's default harness"; naming one
    /// means that harness, concretely, whatever the account prefers. `"claude"`
    /// is the terminal carrier and nothing else — an agent is locked to what it
    /// was created on, so no token is left to be re-read later.
    #[test]
    fn silence_follows_the_default_harness_and_every_token_is_concrete() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let carrier_of = |state: &mut AppState, params: Value| {
            let filed = state.handle(req("plan.create", params));
            assert_eq!(filed["ok"], true, "{filed:?}");
            state.plans[&plan_id_of(&filed)].model_choice.provider
        };

        assert_eq!(
            carrier_of(
                &mut state,
                json!({ "goal": "silence takes the default", "dispatch": false })
            ),
            AgentProvider::ClaudeAdk
        );

        let set = state.handle(req("settings.set", json!({ "default_harness": "codex" })));
        assert_eq!(set["ok"], true, "{set:?}");
        assert_eq!(
            carrier_of(
                &mut state,
                json!({ "goal": "and follows it when it moves", "dispatch": false })
            ),
            AgentProvider::Codex
        );

        for (token, provider) in [
            ("claude", AgentProvider::Claude),
            ("claude_adk", AgentProvider::ClaudeAdk),
            ("codex", AgentProvider::Codex),
        ] {
            assert_eq!(
                carrier_of(
                    &mut state,
                    json!({ "goal": format!("named {token}"), "dispatch": false, "provider": token })
                ),
                provider,
                "{token} names one harness"
            );
        }
    }

    /// A client that names a concrete carrier gets that carrier. The setting
    /// answers the generic question only — it is not a veto over a caller who
    /// already knows what it wants.
    #[test]
    fn a_concretely_named_provider_is_honored_whatever_the_setting_says() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let carrier_of = |state: &mut AppState, goal: &str, provider: &str| {
            let filed = state.handle(req(
                "plan.create",
                json!({ "goal": goal, "dispatch": false, "provider": provider }),
            ));
            assert_eq!(filed["ok"], true, "{filed:?}");
            state.plans[&plan_id_of(&filed)].model_choice.provider
        };

        for default in ["claude_adk", "claude", "codex"] {
            let set = state.handle(req("settings.set", json!({ "default_harness": default })));
            assert_eq!(set["ok"], true, "{set:?}");
            assert_eq!(
                carrier_of(&mut state, &format!("adk under {default}"), "claude_adk"),
                AgentProvider::ClaudeAdk
            );
            assert_eq!(
                carrier_of(&mut state, &format!("codex under {default}"), "codex"),
                AgentProvider::Codex
            );
        }
    }

    /// Resolution happens when a choice is minted and never again, so changing
    /// the account setting moves no work that already exists: every entity
    /// keeps the concrete carrier its record names.
    #[test]
    fn changing_the_setting_migrates_no_entity_that_already_exists() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let filed = state.handle(req(
            "plan.create",
            json!({ "goal": "filed under the old default", "dispatch": false }),
        ));
        let plan_id = plan_id_of(&filed);
        let before = state.entity_model_choice(&plan_id).unwrap();
        assert_eq!(before.provider, AgentProvider::ClaudeAdk);

        let set = state.handle(req("settings.set", json!({ "default_harness": "claude" })));
        assert_eq!(set["ok"], true, "{set:?}");

        assert_eq!(
            state.entity_model_choice(&plan_id).unwrap(),
            before,
            "the choice a later start and every resume read is untouched"
        );
    }

    /// Routing is a headless-shaped job — one decision long, no terminal for
    /// anyone to watch — and there is exactly one headless carrier. So it pins
    /// that one: a human who makes Codex their default must not strand every
    /// capture on a harness the router cannot drive.
    #[test]
    fn the_router_pins_the_headless_carrier_under_every_default() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        assert_eq!(state.default_agent_provider(), AgentProvider::ClaudeAdk);
        for default in ["claude", "codex", "claude_adk"] {
            state.handle(req("settings.set", json!({ "default_harness": default })));
            assert_eq!(
                state.default_agent_provider(),
                AgentProvider::ClaudeAdk,
                "the router does not follow a default of {default}"
            );
        }
    }

    #[tokio::test]
    async fn stream_resume_reconstructs_full_output() {
        let (dir, repo) = init_repo();
        let handler = AppState::new(
            repo,
            dir.path().join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        )
        .into_handler();
        let call = |method: &str, params: Value| {
            handler.call(SessionSender::detached("s"), req(method, params))
        };

        let started = call("stream.start", json!({ "count": 50, "interval_ms": 0 }));
        let stream_id = started["result"]["stream_id"].as_str().unwrap().to_string();

        // Wait for the producer to finish.
        loop {
            let st = call("stream.state", json!({ "stream_id": stream_id }));
            if st["result"]["complete"] == true {
                break;
            }
            tokio::time::sleep(Duration::from_millis(5)).await;
        }

        // Resume in bounded batches from seq 0 — exactly how a reconnecting client
        // catches up. Collect the output text in order.
        let mut since = 0u64;
        let mut texts = Vec::new();
        loop {
            let ev = call(
                "stream.events",
                json!({ "stream_id": stream_id, "since": since, "limit": 7 }),
            );
            for e in ev["result"]["events"].as_array().unwrap() {
                if e["kind"] == "output" {
                    texts.push(e["data"]["text"].as_str().unwrap().to_string());
                }
                // seqs are contiguous and strictly increasing.
            }
            let next = ev["result"]["next"].as_u64().unwrap();
            let head = ev["result"]["head"].as_u64().unwrap();
            let complete = ev["result"]["complete"].as_bool().unwrap();
            since = next;
            if complete && since >= head {
                break;
            }
        }

        // All 50 deterministic chunks, in order.
        assert_eq!(texts.len(), 50);
        assert_eq!(texts[0], "chunk-000000");
        assert_eq!(texts[49], "chunk-000049");

        // The client's reconstruction matches the bridge's authoritative checksum.
        let reconstructed = texts.join("\n");
        let st = call("stream.state", json!({ "stream_id": stream_id }));
        assert_eq!(
            st["result"]["checksum"].as_str().unwrap(),
            sha256_hex(reconstructed.as_bytes())
        );
    }

    /// Shared state + handler for the keyed-terminal tests: the handler drives
    /// the RPC surface while the state handle lets tests inspect internals.
    /// Point a fixture's account at the carrier with a terminal. A test that
    /// reaches for an agent's pid, or spawns the warm TUI spec, is a test about
    /// a PTY session — so it says which carrier it means instead of riding
    /// whatever the account's Claude Code mode happens to be.
    fn on_the_terminal_carrier(state: &Arc<Mutex<AppState>>) {
        state.lock().unwrap().default_harness = AgentProvider::Claude;
    }

    fn shared_state_and_handler(
        repo: &std::path::Path,
        dir: &std::path::Path,
    ) -> (Arc<Mutex<AppState>>, FrameHandler) {
        state_and_handler_timed_by(FrameClock::new(), repo, dir)
    }

    /// The same, on a clock the test chose — the one whose slow-frame lines it
    /// means to read back.
    fn state_and_handler_timed_by(
        clock: Arc<FrameClock>,
        repo: &std::path::Path,
        dir: &std::path::Path,
    ) -> (Arc<Mutex<AppState>>, FrameHandler) {
        let mut app = AppState::new(
            repo.to_path_buf(),
            dir.join("wt"),
            "main",
            true,
            "/tmp/test-mcp.sock",
        );
        // Deterministic terminals for tests: plain bash regardless of the dev
        // machine's login shell (production resolves the user's own shell).
        app.term_shell = "/bin/bash".into();
        app.frame_clock = clock;
        let state = app.shared();
        let handler = AppState::handler(Arc::clone(&state));
        (state, handler)
    }

    /// The verb that says what the daemon is doing must not wait on the daemon
    /// doing it. `bridge.stats` reads the frame clock and never the state, so
    /// the moment it is needed — a frame parked on the app mutex — is the
    /// moment it still answers, naming the method that is holding it.
    #[test]
    fn bridge_stats_answers_while_another_frame_holds_the_app_mutex() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let clock = Arc::clone(&state.lock().unwrap().frame_clock);

        let (held, is_held) = std::sync::mpsc::channel();
        let (release, released) = std::sync::mpsc::channel();
        let holder = std::thread::spawn(move || {
            let timer = clock.frame("board.list");
            let _guard = timer.lock(&state);
            held.send(()).expect("the test is watching");
            released.recv().expect("the test releases the lock");
        });
        is_held
            .recv_timeout(Duration::from_secs(5))
            .expect("the frame took the app mutex");

        let (answered, answers) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let stats = handler.call(
                SessionSender::detached("s-stats"),
                req("bridge.stats", json!({})),
            );
            let _ = answered.send(stats);
        });
        let stats = answers
            .recv_timeout(Duration::from_secs(5))
            .expect("bridge.stats answers with the app mutex held by another frame");

        assert_eq!(stats["ok"], true, "{stats:?}");
        assert_eq!(
            stats["result"]["lock_holder"], "board.list",
            "the stats name the frame that is holding the lock: {stats:?}"
        );
        release.send(()).expect("the holder is still waiting");
        holder.join().expect("the holding frame ends");
    }

    /// Frames are counted under the method they answered, so the stats say which
    /// verb is slow rather than only that something is.
    #[test]
    fn bridge_stats_count_every_frame_under_its_own_method() {
        let (dir, repo) = init_repo();
        let (_state, handler) = shared_state_and_handler(&repo, dir.path());
        let sender = SessionSender::detached("s-counting");
        handler.call(sender.clone(), req("project.list", json!({})));
        handler.call(sender.clone(), req("board.list", json!({})));
        handler.call(sender.clone(), req("board.list", json!({})));

        let stats = handler.call(sender, req("bridge.stats", json!({})))["result"].clone();
        assert_eq!(stats["methods"]["board.list"]["served"], 2, "{stats:?}");
        assert_eq!(stats["methods"]["project.list"]["served"], 1, "{stats:?}");
        assert_eq!(stats["queue_depth"], 0);
        assert_eq!(stats["lock_holder"], Value::Null);
        // Three, not four: a frame is published when it ends, and the frame
        // asking is still running.
        assert_eq!(stats["frames_served"], 3, "{stats:?}");
    }

    /// One of the four durations a slow-frame line reports, in milliseconds.
    fn slow_frame_millis(line: &str, field: &str) -> f64 {
        line.split_whitespace()
            .find_map(|entry| entry.strip_prefix(field))
            .and_then(|duration| duration.strip_suffix("ms"))
            .and_then(|duration| duration.parse().ok())
            .unwrap_or_else(|| panic!("no {field} in {line}"))
    }

    /// A delivery is not the frame that asked for it.
    ///
    /// Its spawn probes a transcript tree and waits out a harness's readiness,
    /// and charging that to `agent.start` would make every verb that speaks to
    /// an agent read as the daemon's slowest while saying nothing about where
    /// the time actually went. The delivery is timed under a method of its own,
    /// and the frame that queued it answers before any of it has happened.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_delivery_is_timed_under_its_own_method_and_never_the_frames() {
        let (dir, repo) = init_repo();
        let (clock, lines) = recording_clock();
        let (state, handler) = state_and_handler_timed_by(Arc::clone(&clock), &repo, dir.path());
        insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-timed");

        // The spawn's session locator runs with the app mutex released, so a
        // factory that takes its time is time the delivery spends and the frame
        // that queued it does not.
        state.lock().unwrap().session_locator_factory = Arc::new(move |_, _| {
            std::thread::sleep(SLOW_FRAME + Duration::from_millis(50));
            None
        });

        let started = call(&handler, "agent.start", json!({ "id": "run-timed" }));
        assert_eq!(started["ok"], true, "{started:?}");

        let line = wait_for(Duration::from_secs(20), || {
            lines
                .lock()
                .unwrap()
                .iter()
                .find(|line| line.starts_with("slow frame agent.deliver "))
                .cloned()
        })
        .await
        .unwrap_or_else(|| {
            panic!(
                "the delivery logged no slow frame of its own: {:?}",
                lines.lock().unwrap()
            )
        });
        assert!(
            slow_frame_millis(&line, "total=") >= SLOW_FRAME.as_secs_f64() * 1000.0,
            "the spawn's seconds are the delivery's own: {line}"
        );
        let lines = lines.lock().unwrap();
        assert!(
            !lines
                .iter()
                .any(|line| line.starts_with("slow frame agent.start ")),
            "the start answered before the harness it asked for was up: {lines:?}"
        );
    }

    /// A session locator that stops where the test says. It is the first thing
    /// a spawn's lock-free phase does, so a spawn parked here is a delivery in
    /// flight and nothing else about the daemon is holding still.
    fn spawns_parked_at(state: &Arc<Mutex<AppState>>) -> OffLockGateHandle {
        let (gate, handle) = OffLockGate::new();
        state.lock().unwrap().session_locator_factory = Arc::new(move |_, _| {
            gate.arrive();
            None
        });
        handle
    }

    /// The whole of spec step 2, in one frame: a message is answered when the
    /// message is durable, and never when the agent is up.
    ///
    /// A cold spawn waits on the harness's readiness for up to
    /// `HARNESS_READY_GRACE` and the browser gives up at twelve seconds, so a
    /// reply that waited for the spawn was the reply the human never saw. The
    /// rest of the daemon is free while it happens.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_message_is_answered_before_its_agent_has_spawned() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let root = insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-answered");
        let spawning = spawns_parked_at(&state);

        let asked_at = std::time::Instant::now();
        let posted = call(
            &handler,
            "thread.post",
            json!({ "entity_id": "run-answered", "body": "start on this" }),
        );
        let answered_in = asked_at.elapsed();
        assert_eq!(posted["ok"], true, "{posted:?}");
        assert!(
            answered_in < Duration::from_millis(100),
            "the post waited for the spawn it triggered: {answered_in:?}"
        );

        spawning.wait_for_arrival();
        let board = call(&handler, "board.list", json!({}));
        assert_eq!(
            board["ok"], true,
            "the daemon reads while a cold spawn is in flight: {board:?}"
        );
        spawning.release();

        wait_for_agent_tab(&state, &derived_agent_key(&root, "run-answered")).await;
    }

    /// The same rule for the verb that exists only to open an agent. Its reply
    /// carries the tab id the agent's own identity mints — reserved under the
    /// lock, addressable before the harness behind it exists.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn agent_start_answers_with_the_reserved_tab_before_the_harness_is_up() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let root = insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-reserved");
        let spawning = spawns_parked_at(&state);

        let asked_at = std::time::Instant::now();
        let started = call(&handler, "agent.start", json!({ "id": "run-reserved" }));
        let answered_in = asked_at.elapsed();
        assert_eq!(started["ok"], true, "{started:?}");
        assert!(
            answered_in < Duration::from_millis(100),
            "the start waited for its harness: {answered_in:?}"
        );
        let key = derived_agent_key(&root, "run-reserved");
        assert_eq!(
            started["result"]["term_id"], key.tab_id,
            "the reply addresses the tab the spawn is about to fill: {started:?}"
        );
        assert!(
            !state.lock().unwrap().tabs.contains_key(&key),
            "and it answered before that tab existed"
        );

        spawning.wait_for_arrival();
        spawning.release();
        wait_for_agent_tab(&state, &key).await;
    }

    /// A delivery that never reached an agent is made on a thread of its own,
    /// so the reply cannot carry the failure. It reaches the browser the way
    /// every background outcome does: written onto the entity, and announced.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_delivery_that_fails_in_the_background_lands_on_its_entity() {
        let (dir, repo) = init_repo();
        let (state, handler, _sender, mut rx, key) = greeted_push_session(&repo, dir.path());
        insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-unreachable");
        {
            // The checkout its agent would work in is not a directory, so the
            // scaffold every spawn makes fails and no agent can be reached.
            let mut s = state.lock().unwrap();
            s.runs
                .get_mut("run-unreachable")
                .expect("the run")
                .worktree
                .path = std::path::PathBuf::from("/dev/null/there-is-no-worktree-here");
        }
        settled_pushes(&mut rx, &key).await;

        let posted = call(
            &handler,
            "thread.post",
            json!({ "entity_id": "run-unreachable", "body": "are you there" }),
        );
        assert_eq!(
            posted["ok"], true,
            "the message is durable whatever the delivery does: {posted:?}"
        );
        wait_for_deliveries(&state).await;

        let got = call(&handler, "run.get", json!({ "run_id": "run-unreachable" }));
        assert!(
            got["result"]["last_error"]
                .as_str()
                .unwrap_or_default()
                .contains("could not reach the agent"),
            "the failure is legible on the run: {got:?}"
        );
        let events = change_events(&settled_pushes(&mut rx, &key).await);
        assert!(
            events.contains(&json!({ "type": "entity.changed", "id": "run-unreachable" })),
            "and the browser is told to look: {events:?}"
        );
    }

    /// A caller that lost the spawn race waits on the winner, and waits holding
    /// nothing.
    ///
    /// The winner needs the app mutex to publish its tab, so a loser that
    /// polled for it — the 25 ms sleep loop this replaces — was taking the
    /// mutex away from the spawn it was waiting for. One harness comes out of
    /// it either way; a daemon that answers meanwhile does not.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn two_callers_of_one_tab_spawn_one_harness_without_spinning() {
        let (dir, repo) = init_repo();
        let (state, handler, root) = agent_tab_fixture(&repo, dir.path(), "run-queued");
        let spawning = spawns_parked_at(&state);
        let asking = || {
            let state = Arc::clone(&state);
            let root = root.clone();
            tokio::task::spawn_blocking(move || {
                ensure_agent_tab(
                    &state,
                    &root,
                    "run-queued",
                    &crate::agent::derived_agent_id("run-queued"),
                    &ModelChoice::default(),
                )
            })
        };

        let winner = asking();
        spawning.wait_for_arrival();
        let loser = asking();
        // Long enough for the second caller to have reached the wait, so the
        // read below is answered from behind it and not in front of it.
        tokio::time::sleep(Duration::from_millis(50)).await;
        let board = call(&handler, "board.list", json!({}));
        assert_eq!(
            board["ok"], true,
            "the daemon reads while a caller waits out another's spawn: {board:?}"
        );
        spawning.release();

        let (won_id, won) = winner.await.unwrap().expect("the winner spawns");
        let (lost_id, lost) = loser.await.unwrap().expect("the loser gets the tab");
        assert_eq!(won, Spawned::Fresh);
        assert_eq!(
            lost,
            Spawned::Warm,
            "the loser is handed the winner's tab, never a second harness"
        );
        assert_eq!(won_id, lost_id, "both callers address one tab");
        let s = state.lock().unwrap();
        assert_eq!(s.tabs.len(), 1, "one worktree, one agent");
        assert!(s.agent_spawns_in_flight.is_empty(), "the claim went back");
    }

    /// A spawn that unwinds gives its claim back too.
    ///
    /// `agent_spawns_in_flight` is removed from in exactly two places — the
    /// settle a published tab makes and the settle an abandoned reservation
    /// makes — so a claim a panic walked past would be held for the life of the
    /// daemon: every later delivery to that tab waits out `AGENT_SPAWN_WAIT`
    /// and then fails, the entity reads as permanently starting, and
    /// `agent.remove` refuses the agent forever. `SpawnClaim`'s `Drop` is the
    /// only thing between a panicking probe and that.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_spawn_that_panics_gives_its_claim_back() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-panicking-spawn");
        let agent_id = crate::agent::derived_agent_id("run-panicking-spawn");
        let asking = || {
            let state = Arc::clone(&state);
            let root = root.clone();
            let agent_id = agent_id.clone();
            tokio::task::spawn_blocking(move || {
                std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    ensure_agent_tab(
                        &state,
                        &root,
                        "run-panicking-spawn",
                        &agent_id,
                        &ModelChoice::default(),
                    )
                }))
            })
        };

        // The first thing the lock-free phase touches, so the unwind happens
        // with the claim taken and the app mutex NOT held.
        state.lock().unwrap().session_locator_factory =
            Arc::new(|_, _| panic!("the transcript tree the spawn was reading blew up"));
        assert!(
            asking().await.unwrap().is_err(),
            "the probe's panic unwinds the spawn"
        );
        assert!(
            state.lock().unwrap().agent_spawns_in_flight.is_empty(),
            "the claim went back with the unwinding spawn"
        );

        // What a leak would actually cost: the next caller waits out
        // `AGENT_SPAWN_WAIT` behind a claim nobody holds and then fails.
        state.lock().unwrap().session_locator_factory = Arc::new(|_, _| None);
        let asked_at = std::time::Instant::now();
        let (_wire_id, spawned) = asking()
            .await
            .unwrap()
            .expect("the next spawn does not panic")
            .expect("it opens the tab the panicking one did not");
        assert_eq!(spawned, Spawned::Fresh);
        assert!(
            asked_at.elapsed() < AGENT_SPAWN_WAIT,
            "the spawn queued behind a leaked claim: {:?}",
            asked_at.elapsed()
        );
    }

    /// And it gives it back from inside the acquisition that publishes.
    ///
    /// `publish_agent_tab` holds the app mutex and the claim at once. The claim
    /// is declared outside the block the guard lives in and locals drop in
    /// reverse, so an unwind drops the guard first and `Drop` finds the mutex
    /// free. Get that order wrong and the daemon does not leak, it deadlocks on
    /// itself — which is why this is asserted against a deadline rather than by
    /// joining.
    #[test]
    fn a_claim_dropped_by_a_panic_under_the_app_mutex_does_not_deadlock() {
        let dir = tempfile::tempdir().unwrap();
        let state = AppState::new_unrooted(dir.path(), "main", true, "unused").shared();
        let (unwound, settled) = std::sync::mpsc::channel();
        let publishing = Arc::clone(&state);
        let published = derived_agent_key(dir.path(), "run-published");
        std::thread::spawn(move || {
            let died = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let _claim = SpawnClaim::take(&mut publishing.lock().unwrap(), &published);
                let _guard = publishing.lock().unwrap();
                panic!("the frame publishing the tab died holding the app mutex");
            }));
            let _ = unwound.send(died.is_err());
        });
        assert_eq!(
            settled.recv_timeout(Duration::from_secs(5)),
            Ok(true),
            "the claim's Drop re-entered the mutex it was unwinding out of"
        );

        let s = state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        assert!(
            s.agent_spawns_in_flight.is_empty(),
            "a panic under the publishing lock kept the claim"
        );
    }

    /// A frame that inserts a tab starts its pumps one statement after its own
    /// lock block releases, on the frame's thread. An acquisition there is the
    /// frame's — charged to nothing and named as nobody's if it is bare — so
    /// the pumps take what they need from the tab they are handed and touch no
    /// lock at all: they start while another frame holds it.
    #[tokio::test]
    async fn a_tabs_pumps_start_while_another_frame_holds_the_app_mutex() {
        let dir = tempfile::tempdir().unwrap();
        let state = AppState::new_unrooted(dir.path(), "main", true, "unused").shared();
        let key = derived_agent_key(dir.path(), "run-pumped");
        let (tab, output) = Tab::spawn(
            TabRole::Shell,
            &HarnessSpec::new("cat"),
            key.tab_id.clone(),
            dir.path().to_path_buf(),
            80,
            24,
            None,
        )
        .expect("the tab spawns");
        let pumps = tab.pumps(output);
        let held = state.lock().unwrap();

        let runtime = tokio::runtime::Handle::current();
        let starting = Arc::clone(&state);
        let (started, start) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let _in_runtime = runtime.enter();
            super::spawn_tab_pumps(&starting, key, pumps);
            let _ = started.send(());
        });
        start
            .recv_timeout(Duration::from_secs(2))
            .expect("the pumps started with the app mutex held by another frame");
        drop(held);
        tab.session.end();
    }

    /// The convoy this step exists to prevent, from the pump's side: an agent
    /// painting a full-speed TUI parses every chunk under its OWN screen lock,
    /// so a frame holding the app mutex — a board read, a commit, anything —
    /// does not stop the paint, and the paint does not stop it.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_streaming_pty_never_takes_the_app_mutex() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let key = TabKey {
            root: root.clone(),
            tab_id: "term-1".to_string(),
        };
        let (tab, output) = Tab::spawn(
            TabRole::Shell,
            &HarnessSpec::new("yes"),
            key.tab_id.clone(),
            root,
            80,
            24,
            None,
        )
        .expect("the flooding tab spawns");
        let screen = screen_of(&tab).clone();
        let session = Arc::clone(&tab.session);
        let pumps = tab.pumps(output);
        state.lock().unwrap().tabs.insert(key.clone(), tab);
        super::spawn_tab_pumps(&state, key, pumps);

        // The app mutex is held for the whole of this, the way a slow frame
        // holds it. The screen must keep filling underneath.
        let held = state.lock().unwrap();
        let painted = painted_bytes_within(&screen, Duration::from_secs(10));
        drop(held);

        assert!(
            painted > 0,
            "a flooding PTY painted nothing while a frame held the app mutex"
        );
        session.end();
    }

    /// How far a screen's cursor gets inside `budget`, polled without ever
    /// awaiting — the caller is holding a lock the runtime must not park.
    fn painted_bytes_within(screen: &ScreenHandle, budget: Duration) -> u64 {
        let deadline = std::time::Instant::now() + budget;
        while std::time::Instant::now() < deadline {
            let painted = screen.cursor();
            if painted > 0 {
                return painted;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        0
    }

    /// The other half of the same rule: a screen that is busy — parsing a
    /// flood, serializing a snapshot, pushing to a slow client — holds nothing
    /// but itself, so every other frame in the daemon answers straight through
    /// it.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_frame_answers_while_a_screen_lock_is_held() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let project_id = state.lock().unwrap().projects[0].id.clone();
        let created = handler.call(
            SessionSender::detached("s1"),
            req("term.create", json!({ "project_id": project_id })),
        );
        assert_eq!(created["ok"], true, "{created:?}");
        let key = state
            .lock()
            .unwrap()
            .tab_key_of_wire_id("term-1")
            .expect("the shell is registered");
        let screen = screen_of(&state.lock().unwrap().tabs[&key]).clone();

        let held = screen.hold();
        assert!(
            state.try_lock().is_ok(),
            "a screen lock is not the app mutex"
        );
        let read = frame_on_a_thread(&state, "s-read", "project.list", json!({}));
        let answered = read
            .recv_timeout(Duration::from_secs(5))
            .expect("an unrelated read is answered while a screen is busy");
        assert_eq!(answered["ok"], true, "{answered:?}");
        drop(held);

        state.lock().unwrap().tabs[&key].session.end();
    }

    /// A harness that has stopped draining its pty blocks the write to it for
    /// as long as it likes. Under the app mutex that one child wedged the whole
    /// daemon; off it, it costs one worker and nothing else.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn term_input_to_a_pty_that_is_not_draining_leaves_the_app_mutex_free() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let agent_id = "agent-wedged";
        let key = TabKey::agent(&root, agent_id);
        let (gate, gate_handle) = OffLockGate::new();
        state.lock().unwrap().tabs.insert(
            key.clone(),
            gated_tab(
                &root,
                gated_agent_role(agent_id),
                GatedHarness::new().refusing_input_until(gate),
            ),
        );

        let typed = frame_on_a_thread(
            &state,
            "s-typed",
            "term.input",
            json!({ "term_id": agent_tab_id(agent_id), "data": b64encode(b"ls\r") }),
        );
        gate_handle.wait_for_arrival();

        assert!(
            state.try_lock().is_ok(),
            "the pty write is holding the app mutex"
        );
        let read = frame_on_a_thread(&state, "s-read", "project.list", json!({}));
        let answered = read
            .recv_timeout(Duration::from_secs(5))
            .expect("an unrelated read is answered while a pty write is stuck");
        assert_eq!(answered["ok"], true, "{answered:?}");

        gate_handle.release();
        let typed = typed
            .recv_timeout(Duration::from_secs(5))
            .expect("the write answers once the child takes it");
        assert_eq!(typed["ok"], true, "{typed:?}");
    }

    /// A tab in `root` carrying `harness`, with a grid of its own — the shape
    /// a test needs to hold one step of a tab's life open and watch the rest of
    /// the daemon carry on.
    fn gated_tab(root: &std::path::Path, role: TabRole, harness: GatedHarness) -> Tab {
        let tab_id = match &role {
            TabRole::Agent { agent_id, .. } => agent_tab_id(agent_id),
            TabRole::Shell => "term-1".to_string(),
        };
        Tab {
            screen: Some(ScreenHandle::new(&tab_id, 80, 24)),
            tab_id,
            root: root.to_path_buf(),
            role,
            created_at: now_rfc3339(),
            session: Arc::new(harness),
            live: true,
            call_sequences: HashMap::new(),
            last_delivered_at: None,
        }
    }

    fn gated_agent_role(agent_id: &str) -> TabRole {
        TabRole::Agent {
            owner: "run-wedged".to_string(),
            agent_id: agent_id.to_string(),
            provider: AgentProvider::default(),
        }
    }

    /// A session with a terminal whose every blocking step the test decides
    /// when to release: the write to its pty, and its own death.
    struct GatedHarness {
        output: broadcast::Sender<Vec<u8>>,
        on_write: Option<OffLockGate>,
        on_resize: Option<OffLockGate>,
        on_end: Option<OffLockGate>,
        on_self_report: Option<OffLockGate>,
        named: Option<String>,
    }

    impl GatedHarness {
        fn new() -> GatedHarness {
            let (output, _) = broadcast::channel(4);
            GatedHarness {
                output,
                on_write: None,
                on_resize: None,
                on_end: None,
                on_self_report: None,
                named: None,
            }
        }

        /// A harness that has stopped draining its pty.
        fn refusing_input_until(mut self, gate: OffLockGate) -> GatedHarness {
            self.on_write = Some(gate);
            self
        }

        /// A harness that has stopped answering the window-change ioctl.
        fn refusing_resize_until(mut self, gate: OffLockGate) -> GatedHarness {
            self.on_resize = Some(gate);
            self
        }

        /// A harness wedged in uninterruptible I/O: SIGKILL lands, the reap
        /// does not return.
        fn refusing_to_die_until(mut self, gate: OffLockGate) -> GatedHarness {
            self.on_end = Some(gate);
            self
        }

        /// A harness that answers `named` when asked what conversation it is
        /// having — slowly, the way a locator listing a transcript tree does.
        fn naming_its_conversation_through(
            mut self,
            gate: OffLockGate,
            named: &str,
        ) -> GatedHarness {
            self.on_self_report = Some(gate);
            self.named = Some(named.to_string());
            self
        }
    }

    impl AgentSession for GatedHarness {
        fn send_turn(&self, _turn: &Turn) -> Result<(), HarnessError> {
            Ok(())
        }
        fn status(&self) -> AgentStatus {
            AgentStatus::Waiting
        }
        fn quiet_for(&self) -> Duration {
            Duration::ZERO
        }
        fn exited_within(&self, _timeout: Duration) -> bool {
            false
        }
        fn end(&self) {
            if let Some(gate) = &self.on_end {
                gate.arrive();
            }
        }
        fn backdate_last_output(&self, _ago: Duration) {}
        fn session_id(&self) -> Option<String> {
            if let Some(gate) = &self.on_self_report {
                gate.arrive();
            }
            self.named.clone()
        }
        fn terminal(&self) -> Option<&dyn crate::harness::TerminalView> {
            Some(self)
        }
    }

    impl crate::harness::TerminalView for GatedHarness {
        fn subscribe(&self) -> broadcast::Receiver<Vec<u8>> {
            self.output.subscribe()
        }
        fn write_input(&self, _bytes: &[u8]) -> Result<(), HarnessError> {
            if let Some(gate) = &self.on_write {
                gate.arrive();
            }
            Ok(())
        }
        fn resize(&self, _size: PtySize) -> Result<(), HarnessError> {
            if let Some(gate) = &self.on_resize {
                gate.arrive();
            }
            Ok(())
        }
        fn pid(&self) -> Option<u32> {
            None
        }
    }

    /// `AgentSession::end` is kill THEN reap, and SIGKILL does not land on a
    /// child wedged in uninterruptible I/O until that I/O returns. Every verb
    /// that closes a tab used to wait for that under the app mutex, so one
    /// stuck harness stopped the daemon. The wait goes to a thread of its own.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn killing_a_wedged_harness_never_holds_the_app_mutex() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let (gate, gate_handle) = OffLockGate::new();
        let key = TabKey {
            root: root.clone(),
            tab_id: "term-1".to_string(),
        };
        state.lock().unwrap().tabs.insert(
            key.clone(),
            gated_tab(
                &root,
                TabRole::Shell,
                GatedHarness::new().refusing_to_die_until(gate),
            ),
        );

        let closed = frame_on_a_thread(
            &state,
            "s-close",
            "term.close",
            json!({ "term_id": "term-1" }),
        );
        gate_handle.wait_for_arrival();
        let closed = closed
            .recv_timeout(Duration::from_secs(5))
            .expect("the close answers without waiting for the reap");
        assert_eq!(closed["ok"], true, "{closed:?}");

        assert!(
            state.try_lock().is_ok(),
            "the reap is holding the app mutex"
        );
        let read = frame_on_a_thread(&state, "s-read", "project.list", json!({}));
        let answered = read
            .recv_timeout(Duration::from_secs(5))
            .expect("an unrelated read is answered while a harness will not die");
        assert_eq!(answered["ok"], true, "{answered:?}");
        assert!(
            !state.lock().unwrap().tabs.contains_key(&key),
            "the tab is out of the registry the moment the verb answers"
        );

        gate_handle.release();
    }

    /// The tab's clients are told it is gone whatever the process does about
    /// it: the close push is bounded work on the screen's own lock and stays
    /// where it always was, while only the kill leaves.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_close_after_a_wedged_kill_still_reaches_its_clients() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let (gate, gate_handle) = OffLockGate::new();
        let key = TabKey {
            root: root.clone(),
            tab_id: "term-1".to_string(),
        };
        state.lock().unwrap().tabs.insert(
            key.clone(),
            gated_tab(
                &root,
                TabRole::Shell,
                GatedHarness::new().refusing_to_die_until(gate),
            ),
        );
        let (sender, mut pushes, session_key) = SessionSender::observable("watching");
        let attached = handler.call(sender, req("term.attach", json!({ "term_id": "term-1" })));
        assert_eq!(attached["ok"], true, "{attached:?}");

        let closed = frame_on_a_thread(
            &state,
            "s-close",
            "term.close",
            json!({ "term_id": "term-1" }),
        );
        gate_handle.wait_for_arrival();
        let closed = closed
            .recv_timeout(Duration::from_secs(5))
            .expect("the close answers without waiting for the reap");
        assert_eq!(closed["ok"], true, "{closed:?}");

        let seen = wait_for_push(&mut pushes, &session_key, |push| {
            push["type"] == "term.closed" && push["term_id"] == "term-1"
        })
        .await;
        assert!(!seen.is_empty(), "{seen:?}");

        gate_handle.release();
    }

    /// A closed screen means nobody is watching and nothing is painting. The
    /// kill is asynchronous, so between the close reply and the child's death
    /// the PTY can keep producing — for a harness wedged in uninterruptible
    /// I/O, without end. The pump used to stop the instant its tab left the
    /// registry; now that it never consults the registry, the screen's own
    /// closed state is what stops it, or it would parse and push `term.output`
    /// forever to the clients it just told `term.closed`.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_closed_tab_stops_painting_before_its_harness_dies() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let (gate, gate_handle) = OffLockGate::new();
        let key = TabKey {
            root: root.clone(),
            tab_id: "term-1".to_string(),
        };
        let harness = GatedHarness::new().refusing_to_die_until(gate);
        let pty = harness.output.clone();
        state
            .lock()
            .unwrap()
            .tabs
            .insert(key.clone(), gated_tab(&root, TabRole::Shell, harness));
        spawn_tab_pumps(
            &state,
            key.clone(),
            SessionOutput::painting(pty.subscribe()),
        );
        let (sender, mut pushes, session_key) = SessionSender::observable("watching");
        let attached = handler.call(sender, req("term.attach", json!({ "term_id": "term-1" })));
        assert_eq!(attached["ok"], true, "{attached:?}");

        let closed = frame_on_a_thread(
            &state,
            "s-close",
            "term.close",
            json!({ "term_id": "term-1" }),
        );
        gate_handle.wait_for_arrival();
        let closed = closed
            .recv_timeout(Duration::from_secs(5))
            .expect("the close answers without waiting for the reap");
        assert_eq!(closed["ok"], true, "{closed:?}");
        wait_for_push(&mut pushes, &session_key, |push| {
            push["type"] == "term.closed" && push["term_id"] == "term-1"
        })
        .await;

        // The child, still alive, keeps painting into a tab nothing addresses.
        let _ = pty.send(b"AFTER-CLOSE".to_vec());
        wait_for(Duration::from_secs(5), || {
            (pty.receiver_count() == 0).then_some(())
        })
        .await
        .expect("the pump ends the moment its tab is retired, not when the child dies");
        tokio::time::sleep(Duration::from_millis(TERM_FLUSH_MS * 5)).await;
        let after_close = wait_for_pushes(&mut pushes, &session_key, |_| true).await;
        assert!(
            after_close.iter().all(|push| push["type"] != "term.output"),
            "a client told its terminal closed was painted to afterwards: {after_close:?}"
        );

        gate_handle.release();
    }

    /// With the kill asynchronous, a replaced session's EOF can arrive after
    /// its replacement is already in the registry. The pump ends the tab it was
    /// started for and no other: it carries the session it pumps, and a tab
    /// holding a different one is somebody else's.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_replaced_sessions_late_eof_leaves_the_replacement_tab_alone() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let key = derived_agent_key(&root, "run-replaced");
        let agent_id = crate::agent::derived_agent_id("run-replaced");

        let spawn_one = || {
            Tab::spawn(
                TabRole::Agent {
                    owner: "run-replaced".to_string(),
                    agent_id: agent_id.clone(),
                    provider: AgentProvider::default(),
                },
                &HarnessSpec::new("cat"),
                key.tab_id.clone(),
                root.clone(),
                80,
                24,
                None,
            )
            .expect("the agent tab spawns")
        };

        let (replaced, output) = spawn_one();
        let dying = Arc::clone(&replaced.session);
        let pumps = replaced.pumps(output);
        state.lock().unwrap().tabs.insert(key.clone(), replaced);
        super::spawn_tab_pumps(&state, key.clone(), pumps);

        // The replacement takes the tab over while the first session is still
        // being reaped, which is what an asynchronous kill allows.
        let (replacement, output) = spawn_one();
        let living = Arc::clone(&replacement.session);
        let pumps = replacement.pumps(output);
        state.lock().unwrap().tabs.insert(key.clone(), replacement);
        super::spawn_tab_pumps(&state, key.clone(), pumps);

        dying.end();
        wait_for(Duration::from_secs(10), || {
            matches!(dying.status(), AgentStatus::Ended { .. }).then_some(())
        })
        .await
        .expect("the replaced session dies");
        tokio::time::sleep(Duration::from_millis(200)).await;

        assert!(
            state.lock().unwrap().tabs[&key].live,
            "a dead session's EOF closed the tab that replaced it"
        );
        living.end();
    }

    /// The rites of a dying session take the app mutex twice, with a
    /// filesystem walk between them, so the tab can turn over mid-rite: a post
    /// arrives, the dead tab is replaced, and the replacement is already
    /// working. What the dead session then reports is its own — writing it down
    /// against the live agent closes the turn in flight and records the wrong
    /// conversation to resume.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_late_self_report_never_lands_on_the_session_that_replaced_it() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let run_id = adopted_run(
            &mut state.lock().unwrap(),
            &repo,
            dir.path(),
            "feature-late-report",
        );
        let agent_id = primary_agent_id(&state.lock().unwrap(), &run_id);
        let role = TabRole::Agent {
            owner: run_id.clone(),
            agent_id: agent_id.clone(),
            provider: AgentProvider::default(),
        };
        let key = TabKey::agent(&root, &agent_id);
        let (gate, gate_handle) = OffLockGate::new();
        let dying = gated_tab(
            &root,
            role.clone(),
            GatedHarness::new().naming_its_conversation_through(gate, "the-dead-conversation"),
        );
        let session = Arc::clone(&dying.session);
        let screen = screen_of(&dying).clone();
        state.lock().unwrap().tabs.insert(key.clone(), dying);

        let rites = {
            let state = Arc::clone(&state);
            let key = key.clone();
            let session = Arc::clone(&session);
            let (done, finished) = std::sync::mpsc::channel();
            std::thread::spawn(move || {
                end_of_session(&state, &key, &session, &screen);
                let _ = done.send(());
            });
            finished
        };
        gate_handle.wait_for_arrival();

        // A post lands in the window: the dead tab is replaced, the replacement
        // names its own conversation, and it is holding a turn.
        {
            let mut s = state.lock().unwrap();
            s.tabs
                .insert(key.clone(), gated_tab(&root, role, GatedHarness::new()));
            s.record_agent_resume_id(
                &run_id,
                &agent_id,
                Some("the-live-conversation".to_string()),
            );
        }
        open_a_turn(&state, &run_id);

        gate_handle.release();
        rites
            .recv_timeout(Duration::from_secs(5))
            .expect("the dying session finishes its rites");

        let s = state.lock().unwrap();
        assert!(
            s.tabs[&key].live,
            "the dead session's rites marked its replacement dead"
        );
        assert_eq!(
            s.recorded_resume_id(&run_id, &agent_id).as_deref(),
            Some("the-live-conversation"),
            "the dead session's name was written over the live one's"
        );
        assert!(
            primary_thread(&s.runs[&run_id].agents)
                .working_since()
                .is_some(),
            "the dead session's rites closed the turn its replacement is holding"
        );
    }
    /// The close a dying session owes its clients and the `live = false` that
    /// makes its tab replaceable are ONE acquisition.
    ///
    /// A tab reads as replaceable the moment `live` goes false, and
    /// [`ensure_agent_tab`] replaces it by taking its screen — clients and all
    /// — over to the new session without a word. So a close pushed after that
    /// acquisition released would reach browsers that are watching the LIVE
    /// replacement, interleaved with its opening reset; and the post that
    /// triggers the replacement is the ordinary case, a human answering an
    /// agent that just exited. The close is bounded — the screen's own lock
    /// and one send per client — so it belongs inside the acquisition that
    /// marks the tab, where nothing can come between them.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_replacement_cannot_slip_between_a_session_ending_and_its_close() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let run_id = adopted_run(
            &mut state.lock().unwrap(),
            &repo,
            dir.path(),
            "feature-atomic-close",
        );
        let agent_id = primary_agent_id(&state.lock().unwrap(), &run_id);
        let key = TabKey::agent(&root, &agent_id);
        let dying = gated_tab(
            &root,
            TabRole::Agent {
                owner: run_id.clone(),
                agent_id: agent_id.clone(),
                provider: AgentProvider::default(),
            },
            GatedHarness::new(),
        );
        let session = Arc::clone(&dying.session);
        let screen = screen_of(&dying).clone();
        let (sender, mut pushes, session_key) = SessionSender::observable("watching");
        screen.attach(&sender, None);
        state.lock().unwrap().tabs.insert(key.clone(), dying);

        // The screen is busy the way a flooding pump makes it busy, so the
        // rites park inside the close they owe.
        let held = screen.hold();
        let rites = {
            let state = Arc::clone(&state);
            let key = key.clone();
            let session = Arc::clone(&session);
            let screen = screen.clone();
            let (done, finished) = std::sync::mpsc::channel();
            std::thread::spawn(move || {
                end_of_session(&state, &key, &session, &screen);
                let _ = done.send(());
            });
            finished
        };

        let deadline = std::time::Instant::now() + Duration::from_secs(1);
        let mut replaceable = false;
        while !replaceable && std::time::Instant::now() < deadline {
            if let Ok(s) = state.try_lock() {
                replaceable = !s.tabs[&key].live;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        assert!(
            !replaceable,
            "a spawn could have read this tab as dead and carried its screen \
             onto a new session before the old one's clients heard it end"
        );

        drop(held);
        rites
            .recv_timeout(Duration::from_secs(5))
            .expect("the rites finish once the screen frees up");
        let seen = wait_for_pushes(&mut pushes, &session_key, |seen| {
            seen.iter().any(|push| push["type"] == "term.closed")
        })
        .await;
        let closed: Vec<&Value> = seen
            .iter()
            .filter(|push| push["type"] == "term.closed")
            .collect();
        assert_eq!(closed.len(), 1, "told once, and once only: {seen:?}");
        assert_eq!(closed[0]["reason"], "agent_session_ended", "{closed:?}");
        assert_eq!(
            screen.attached(),
            1,
            "and the client stays on the retained grid, for the session that \
             paints here next"
        );
    }

    /// The same rite, on the carrier with no bytes. Its stream closing ends a
    /// session too — not live, open tool calls harvested as unanswered, the
    /// turn closed — and none of that belongs to the session that took the tab
    /// over while it was reading.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_replaced_sessions_late_activity_close_leaves_the_replacement_alone() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let run_id = adopted_run(
            &mut state.lock().unwrap(),
            &repo,
            dir.path(),
            "feature-late-activity",
        );
        let agent_id = primary_agent_id(&state.lock().unwrap(), &run_id);
        let role = TabRole::Agent {
            owner: run_id.clone(),
            agent_id: agent_id.clone(),
            provider: AgentProvider::default(),
        };
        let key = TabKey::agent(&root, &agent_id);
        let (gate, gate_handle) = OffLockGate::new();
        let reporting = gated_tab(
            &root,
            role.clone(),
            GatedHarness::new().naming_its_conversation_through(gate, "the-dead-conversation"),
        );
        let session = Arc::clone(&reporting.session);
        state.lock().unwrap().tabs.insert(key.clone(), reporting);
        let (activity, subscribed) = broadcast::channel(4);
        super::spawn_activity_pump(&state, key.clone(), session, Some(subscribed), None);
        // The stream closes: the session behind this tab is over.
        drop(activity);
        gate_handle.wait_for_arrival();

        {
            let mut s = state.lock().unwrap();
            s.tabs
                .insert(key.clone(), gated_tab(&root, role, GatedHarness::new()));
            s.record_agent_resume_id(
                &run_id,
                &agent_id,
                Some("the-live-conversation".to_string()),
            );
        }
        open_a_turn(&state, &run_id);

        gate_handle.release();
        tokio::time::sleep(Duration::from_millis(200)).await;

        let s = state.lock().unwrap();
        assert!(
            s.tabs[&key].live,
            "a closed stream marked the tab that replaced it dead"
        );
        assert_eq!(
            s.recorded_resume_id(&run_id, &agent_id).as_deref(),
            Some("the-live-conversation"),
            "the dead session's name was written over the live one's"
        );
        assert!(
            primary_thread(&s.runs[&run_id].agents)
                .working_since()
                .is_some(),
            "the dead session's close ended the turn its replacement is holding"
        );
    }

    /// An attach clones the tab's handle under the app mutex and registers with
    /// it released, so a close can take the tab out in between. The screen's own
    /// lock decides which happened first, because the app mutex no longer can:
    /// the late client hears `term.closed` rather than sitting on a live-looking
    /// grid nothing will ever paint or close.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_client_attaching_to_a_tab_that_just_closed_is_told_so() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let key = TabKey {
            root: root.clone(),
            tab_id: "term-1".to_string(),
        };
        state.lock().unwrap().tabs.insert(
            key.clone(),
            gated_tab(&root, TabRole::Shell, GatedHarness::new()),
        );
        // What an attach already in flight is holding.
        let screen = screen_of(&state.lock().unwrap().tabs[&key]).clone();

        let closed = handler.call(
            SessionSender::detached("s-close"),
            req("term.close", json!({ "term_id": "term-1" })),
        );
        assert_eq!(closed["ok"], true, "{closed:?}");

        let (sender, mut pushes, session_key) = SessionSender::observable("late");
        screen.attach(&sender, Some((80, 24)));

        let seen = wait_for_push(&mut pushes, &session_key, |push| {
            push["type"] == "term.closed" && push["term_id"] == "term-1"
        })
        .await;
        assert!(!seen.is_empty(), "{seen:?}");
        assert_eq!(
            screen.attached(),
            0,
            "a screen nothing will close again took a client anyway"
        );
    }

    /// A spawn that inherits waiting clients owes their child a window-change
    /// ioctl, and an ioctl goes to a process that may not answer. The clients
    /// move under the app mutex, beside the insert that publishes the tab,
    /// because that half is bounded; the child is told with the lock down, so a
    /// harness that will not take the resize wedges one worker rather than the
    /// daemon.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn telling_an_inherited_child_its_size_never_holds_the_app_mutex() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let agent_id = "agent-inheriting";
        let key = TabKey::agent(&root, agent_id);
        let (gate, gate_handle) = OffLockGate::new();
        let born = gated_tab(
            &root,
            gated_agent_role(agent_id),
            GatedHarness::new().refusing_resize_until(gate),
        );

        // A client mounted the Agent tab before this worktree had an agent.
        let (sender, _pushes, _session_key) = SessionSender::observable("waiting-client");
        let waiting = ScreenHandle::new(&agent_tab_id(agent_id), 90, 25);
        waiting.attach(&sender, Some((90, 25)));
        state
            .lock()
            .unwrap()
            .agent_screens_awaiting_spawn
            .insert(key.clone(), waiting);

        let told = {
            let state = Arc::clone(&state);
            let key = key.clone();
            let (done, finished) = std::sync::mpsc::channel();
            std::thread::spawn(move || {
                let inherited = {
                    let mut s = state.lock().unwrap();
                    let inherited = inherit_waiting_clients(&mut s, &key, &born);
                    s.tabs.insert(key, born);
                    inherited
                };
                inherited
                    .expect("the waiting clients are carried onto the new screen")
                    .fit_child_to_screen();
                let _ = done.send(());
            });
            finished
        };
        gate_handle.wait_for_arrival();

        assert!(
            state.try_lock().is_ok(),
            "the window-change ioctl is holding the app mutex"
        );
        let read = frame_on_a_thread(&state, "s-read", "project.list", json!({}));
        assert_eq!(
            read.recv_timeout(Duration::from_secs(5))
                .expect("an unrelated read is answered while a child will not resize")["ok"],
            true
        );
        assert_eq!(
            screen_of(&state.lock().unwrap().tabs[&key]).attached_sessions(),
            vec!["waiting-client".to_string()],
            "the client that was waiting is on the new screen the moment the tab is published"
        );

        gate_handle.release();
        told.recv_timeout(Duration::from_secs(5))
            .expect("the ioctl returns once the child takes it");
    }

    /// A terminal names its conversation by listing the harness's transcript
    /// tree — a filesystem walk that grows with every conversation the human
    /// has ever had. The sweep already took the session out of the registry to
    /// ask, and then asked a SECOND time through the registry to write the
    /// answer down, under the lock. There is one reading now, and it is off the
    /// lock.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn an_agent_tabs_last_reading_leaves_the_app_mutex_free() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let run_id = adopted_run(
            &mut state.lock().unwrap(),
            &repo,
            dir.path(),
            "feature-named",
        );
        let agent_id = primary_agent_id(&state.lock().unwrap(), &run_id);
        let (gate, gate_handle) = OffLockGate::new();
        let key = TabKey::agent(&root, &agent_id);
        state.lock().unwrap().tabs.insert(
            key.clone(),
            gated_tab(
                &root,
                TabRole::Agent {
                    owner: run_id.clone(),
                    agent_id: agent_id.clone(),
                    provider: AgentProvider::default(),
                },
                GatedHarness::new().naming_its_conversation_through(gate, "conversation-7"),
            ),
        );

        let captured = {
            let capturing = Arc::clone(&state);
            let (done, finished) = std::sync::mpsc::channel();
            std::thread::spawn(move || {
                capture_conversation_names(&capturing);
                let _ = done.send(());
            });
            finished
        };
        gate_handle.wait_for_arrival();

        assert!(
            state.try_lock().is_ok(),
            "the reading is holding the app mutex"
        );
        let read = frame_on_a_thread(&state, "s-read", "project.list", json!({}));
        assert_eq!(
            read.recv_timeout(Duration::from_secs(5))
                .expect("an unrelated read is answered while a session is being read")["ok"],
            true
        );

        gate_handle.release();
        captured
            .recv_timeout(Duration::from_secs(5))
            .expect("the sweep reads a session once, not twice");
        assert_eq!(
            state
                .lock()
                .unwrap()
                .recorded_resume_id(&run_id, &agent_id)
                .as_deref(),
            Some("conversation-7"),
            "and writes down what it read"
        );
    }

    /// Poll an observable sender's captured pushes until the decrypted history
    /// satisfies `pred` (returning everything seen), or panic after 10 s.
    async fn wait_for_pushes(
        rx: &mut tokio::sync::mpsc::UnboundedReceiver<tokio_tungstenite::tungstenite::Message>,
        session_key: &str,
        pred: impl Fn(&[Value]) -> bool,
    ) -> Vec<Value> {
        let mut seen = Vec::new();
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        loop {
            while let Ok(message) = rx.try_recv() {
                seen.push(SessionSender::decrypt_push(session_key, &message));
            }
            if pred(&seen) {
                return seen;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "timed out waiting for a matching push; saw: {seen:?}"
            );
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
    }

    /// Wait until one push matches `pred`.
    async fn wait_for_push(
        rx: &mut tokio::sync::mpsc::UnboundedReceiver<tokio_tungstenite::tungstenite::Message>,
        session_key: &str,
        pred: impl Fn(&Value) -> bool,
    ) -> Vec<Value> {
        wait_for_pushes(rx, session_key, |seen| seen.iter().any(&pred)).await
    }

    /// The concatenated bytes of every `term.output` push for `term_id`.
    fn output_text(pushes: &[Value], term_id: &str) -> String {
        let mut bytes = Vec::new();
        for p in pushes {
            if p["type"] == "term.output" && p["term_id"] == term_id {
                bytes.extend_from_slice(&b64decode(p["data"].as_str().unwrap()).unwrap());
            }
        }
        String::from_utf8_lossy(&bytes).into_owned()
    }

    /// The OS pid behind a tab, addressed the way a client addresses it.
    fn tab_pid(state: &Arc<Mutex<AppState>>, wire_id: &str) -> Option<u32> {
        let s = state.lock().unwrap();
        let key = s.tab_key_of_wire_id(wire_id).ok()?;
        agent_pid(&s.tabs[&key])
    }

    /// True once `pid` is fully gone from the process table (killed AND reaped —
    /// a zombie still shows up in `ps` with state Z).
    ///
    /// Waited out rather than asked once: the kill and the reap run on a
    /// [`Retirement`]'s own thread, so a verb answers before its harness is
    /// gone. What the assertion means is unchanged — the process IS reaped —
    /// only when it can first be observed.
    fn process_reaped(pid: u32) -> bool {
        settles(|| {
            let out = Command::new("ps")
                .args(["-o", "stat=", "-p", &pid.to_string()])
                .output()
                .unwrap();
            !out.status.success() || String::from_utf8_lossy(&out.stdout).trim().is_empty()
        })
    }

    /// Poll `settled` until it answers true, or give up after 10 s. For the
    /// facts a background thread makes true shortly after the frame answers.
    fn settles(settled: impl Fn() -> bool) -> bool {
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        while std::time::Instant::now() < deadline {
            if settled() {
                return true;
            }
            std::thread::sleep(Duration::from_millis(20));
        }
        false
    }

    #[tokio::test]
    async fn keyed_terminal_create_attach_io_close_roundtrip() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let project_id = state.lock().unwrap().projects[0].id.clone();

        // Create in the primary scope: bash starts in the repo root and the
        // pump runs before any attach.
        let created = handler.call(
            SessionSender::detached("s1"),
            req(
                "term.create",
                json!({ "project_id": project_id, "cols": 80, "rows": 24 }),
            ),
        );
        assert_eq!(created["ok"], true, "{created:?}");
        assert_eq!(created["result"]["term_id"], "term-1");
        assert_eq!(created["result"]["cols"], 80);
        assert_eq!(created["result"]["rows"], 24);

        // Listed under its scope, with metadata.
        let listed = handler.call(
            SessionSender::detached("s1"),
            req("term.list", json!({ "project_id": project_id })),
        );
        let terminals = listed["result"]["terminals"].as_array().unwrap();
        assert_eq!(terminals.len(), 1);
        assert_eq!(terminals[0]["term_id"], "term-1");
        assert!(terminals[0]["created_at"]
            .as_str()
            .is_some_and(|s| !s.is_empty()));

        // Attach with an observable sender, then type a command: the echo comes
        // back as keyed term.output pushes.
        let (sender, mut pushes, key) = SessionSender::observable("s1");
        let attached = handler.call(
            sender,
            req(
                "term.attach",
                json!({ "term_id": "term-1", "cols": 80, "rows": 24 }),
            ),
        );
        assert_eq!(attached["ok"], true, "{attached:?}");
        assert_eq!(attached["result"]["term_id"], "term-1");
        assert!(attached["result"]["snapshot"].is_string());
        assert!(attached["result"]["cursor"].is_u64());

        let input = b64encode(b"echo keyed-term-ok\r");
        let wrote = handler.call(
            SessionSender::detached("s1"),
            req("term.input", json!({ "term_id": "term-1", "data": input })),
        );
        assert_eq!(wrote["ok"], true, "{wrote:?}");
        wait_for_pushes(&mut pushes, &key, |seen| {
            output_text(seen, "term-1").contains("keyed-term-ok")
        })
        .await;

        // Close: the PTY is killed AND reaped, the entry is gone, and every
        // attached client hears term.closed{reason:"closed"}.
        let pid = tab_pid(&state, "term-1").expect("the shell is registered");
        let closed = handler.call(
            SessionSender::detached("s1"),
            req("term.close", json!({ "term_id": "term-1" })),
        );
        assert_eq!(closed["ok"], true, "{closed:?}");
        let seen = wait_for_push(&mut pushes, &key, |p| {
            p["type"] == "term.closed" && p["term_id"] == "term-1" && p["reason"] == "closed"
        })
        .await;
        assert!(!seen.is_empty());
        assert_eq!(state.lock().unwrap().shell_tab_count(), 0);
        assert!(process_reaped(pid), "the shell must be killed and reaped");

        let relisted = handler.call(
            SessionSender::detached("s1"),
            req("term.list", json!({ "project_id": project_id })),
        );
        assert_eq!(relisted["result"]["terminals"].as_array().unwrap().len(), 0);
    }

    /// `term.ack` is the client's half of flow control: it reports the cursor it
    /// has actually applied, on the same id space every other `term.*` verb
    /// takes. A stale client acking a terminal that is gone gets the same
    /// "unknown term_id" as any other verb, so it drops the tab instead of
    /// acking into the void forever.
    #[tokio::test]
    async fn term_ack_reports_a_cursor_and_rejects_an_unknown_term_id() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let project_id = state.lock().unwrap().projects[0].id.clone();

        handler.call(
            SessionSender::detached("s1"),
            req("term.create", json!({ "project_id": project_id })),
        );
        let (sender, _pushes, _key) = SessionSender::observable("s1");
        let attached = handler.call(sender, req("term.attach", json!({ "term_id": "term-1" })));
        assert_eq!(attached["ok"], true, "{attached:?}");
        let cursor = attached["result"]["cursor"].as_u64().unwrap();

        let acked = handler.call(
            SessionSender::detached("s1"),
            req("term.ack", json!({ "term_id": "term-1", "cursor": cursor })),
        );
        assert_eq!(acked["ok"], true, "{acked:?}");
        assert_eq!(acked["result"]["ok"], true, "{acked:?}");

        let unknown = handler.call(
            SessionSender::detached("s1"),
            req("term.ack", json!({ "term_id": "term-404", "cursor": 1 })),
        );
        assert_eq!(unknown["ok"], false, "{unknown:?}");
        assert_eq!(unknown["error"], "unknown term_id", "{unknown:?}");
    }

    #[tokio::test]
    async fn keyed_terminal_snapshot_reflects_input_across_reattach() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let project_id = state.lock().unwrap().projects[0].id.clone();

        let created = handler.call(
            SessionSender::detached("s1"),
            req("term.create", json!({ "project_id": project_id })),
        );
        let term_id = created["result"]["term_id"].as_str().unwrap().to_string();
        let a = handler.call(
            SessionSender::detached("s1"),
            req(
                "term.attach",
                json!({ "term_id": term_id, "cols": 80, "rows": 24 }),
            ),
        );
        assert_eq!(a["ok"], true);
        tokio::time::sleep(Duration::from_millis(500)).await;

        // Send a command (the PTY echoes it and runs it).
        let input = b64encode(b"echo build-terminal-ok\n");
        handler.call(
            SessionSender::detached("s1"),
            req("term.input", json!({ "term_id": term_id, "data": input })),
        );
        tokio::time::sleep(Duration::from_millis(700)).await;

        // Reconnect = a fresh attach. The screen snapshot (vt100 model) must reflect
        // the prior output — that's snapshot-based resync, not byte replay.
        let b = handler.call(
            SessionSender::detached("s2"),
            req(
                "term.attach",
                json!({ "term_id": term_id, "cols": 80, "rows": 24 }),
            ),
        );
        let snap =
            String::from_utf8_lossy(&b64decode(b["result"]["snapshot"].as_str().unwrap()).unwrap())
                .into_owned();
        assert!(
            snap.contains("build-terminal-ok"),
            "reattach snapshot should reflect prior output; got: {snap:?}"
        );
        assert!(b["result"]["cursor"].as_u64().unwrap() > 0);
    }

    /// A terminal belongs to the WORKTREE it was opened in, not to whichever
    /// entity happened to name that worktree when it was created.
    ///
    /// The client addresses an unadopted worktree as `{project_id,
    /// worktree_id}` and an adopted one as `{run_id}` — two scope shapes over
    /// one directory. Keying the registry by the canonical root is what makes
    /// adoption invisible to an open shell; keying it by scope made the shell
    /// vanish from the tab row while its process kept running.
    #[tokio::test]
    async fn term_list_follows_a_worktree_across_adoption() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let project_id = state.lock().unwrap().projects[0].id.clone();
        add_external_worktree(&repo, dir.path(), "feature-x", "feature-x");
        let worktree_id = state
            .lock()
            .unwrap()
            .scan_external_worktrees_now(&project_id)
            .unwrap()
            .into_iter()
            .find(|w| w.branch.as_deref() == Some("feature-x"))
            .expect("the external worktree is discoverable")
            .id;

        let created = handler.call(
            SessionSender::detached("s1"),
            req(
                "term.create",
                json!({ "project_id": project_id, "worktree_id": worktree_id }),
            ),
        );
        assert_eq!(created["ok"], true, "{created:?}");
        let term_id = created["result"]["term_id"].as_str().unwrap().to_string();
        let shell_pid = tab_pid(&state, &term_id).expect("the shell is registered");

        let adopted = handler.call(
            SessionSender::detached("s1"),
            req(
                "run.adopt",
                json!({ "project_id": project_id, "worktree_id": worktree_id }),
            ),
        );
        assert_eq!(adopted["ok"], true, "{adopted:?}");
        let run_id = run_id_of(&adopted);

        let listed = handler.call(
            SessionSender::detached("s1"),
            req("term.list", json!({ "run_id": run_id })),
        );
        let terminals = listed["result"]["terminals"].as_array().unwrap();
        assert_eq!(
            terminals.len(),
            1,
            "the shell survives adoption on the run scope: {listed:?}"
        );
        assert_eq!(terminals[0]["term_id"], json!(term_id));
        // The SAME shell, not a fresh one: adoption is a record change, and the
        // process the human was typing into never noticed it.
        assert_eq!(
            tab_pid(&state, &term_id),
            Some(shell_pid),
            "adoption must not restart the human's shell"
        );
    }

    /// One directory, two spellings, ONE tab registry.
    ///
    /// The same worktree reaches the daemon under literally different paths: a
    /// run's is `worktrees_root/<name>` while the scanner canonicalizes, and on
    /// macOS `/tmp` IS `/private/tmp`. Every scope funnels through the canonical
    /// form for exactly this reason — keyed by the spelling it was asked with, a
    /// shell opened through one path is invisible through the other while its
    /// process keeps running, which is the orphan tab this design dissolves.
    #[tokio::test]
    async fn a_worktree_spelled_two_ways_holds_one_set_of_tabs() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_qa_state_and_handler(&repo, dir.path());
        let canonical_root = {
            let mut s = state.lock().unwrap();
            let root = insert_run(
                &mut s,
                &repo,
                dir.path(),
                "run-canonical",
                RunState::Building,
            );
            insert_run(&mut s, &repo, dir.path(), "run-aliased", RunState::Building);
            // The second run addresses that SAME directory under another name.
            let alias = dir.path().join("alias-to-worktree");
            std::os::unix::fs::symlink(&root, &alias).unwrap();
            s.runs.get_mut("run-aliased").unwrap().worktree.path = alias;
            root
        };

        let created = call(&handler, "term.create", json!({ "run_id": "run-aliased" }));
        assert_eq!(created["ok"], true, "{created:?}");
        let term_id = created["result"]["term_id"].as_str().unwrap().to_string();

        // Asked about through the OTHER spelling, the same directory holds the
        // same shell.
        let listed = call(&handler, "term.list", json!({ "run_id": "run-canonical" }));
        let listed_ids: Vec<&str> = listed["result"]["terminals"]
            .as_array()
            .unwrap()
            .iter()
            .map(|t| t["term_id"].as_str().unwrap())
            .collect();
        assert_eq!(
            listed_ids,
            vec![term_id.as_str()],
            "both spellings name one worktree, so both see its shell: {listed:?}"
        );

        let s = state.lock().unwrap();
        let keys: Vec<&TabKey> = s.tabs.keys().collect();
        assert!(
            keys.iter().all(|key| key.root == canonical_root),
            "every tab is keyed by the canonical root ({canonical_root:?}): {keys:?}"
        );
    }

    /// A worktree's tab row is its own. The registry is one map over every
    /// worktree the daemon holds, so the only thing keeping one directory's
    /// shells out of another's row is the filter on the resolved root.
    #[tokio::test]
    async fn term_list_shows_only_the_shells_of_the_worktree_asked_about() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_qa_state_and_handler(&repo, dir.path());
        {
            let mut s = state.lock().unwrap();
            insert_run(&mut s, &repo, dir.path(), "run-here", RunState::Building);
            insert_run(&mut s, &repo, dir.path(), "run-there", RunState::Building);
        }
        let shell_in = |run_id: &str| {
            let created = call(&handler, "term.create", json!({ "run_id": run_id }));
            assert_eq!(created["ok"], true, "{created:?}");
            created["result"]["term_id"].as_str().unwrap().to_string()
        };
        let here = shell_in("run-here");
        let there = shell_in("run-there");
        assert_ne!(here, there, "two worktrees, two shells");

        for (run_id, own, other) in [("run-here", &here, &there), ("run-there", &there, &here)] {
            let listed = call(&handler, "term.list", json!({ "run_id": run_id }));
            let ids: Vec<&str> = listed["result"]["terminals"]
                .as_array()
                .unwrap()
                .iter()
                .map(|t| t["term_id"].as_str().unwrap())
                .collect();
            assert_eq!(
                ids,
                vec![own.as_str()],
                "{run_id} must show its own shell and not {other}: {listed:?}"
            );
        }
    }

    /// One attach verb over one id space. A client holds a row of tabs — some
    /// shells, one agent — and must not need to know which RPC each one
    /// answers to; the id says everything.
    #[tokio::test]
    async fn one_attach_verb_serves_shells_and_the_agent() {
        let (dir, repo) = init_repo();
        let (state, handler, root) = agent_tab_fixture(&repo, dir.path(), "run-attach");
        let (agent_wire_id, _) = ensure_agent_tab(
            &state,
            &root,
            "run-attach",
            &crate::agent::derived_agent_id("run-attach"),
            &ModelChoice::default(),
        )
        .unwrap();

        let attached = handler.call(
            SessionSender::detached("s1"),
            req(
                "term.attach",
                json!({ "term_id": agent_wire_id, "cols": 120, "rows": 40 }),
            ),
        );
        assert_eq!(
            attached["ok"], true,
            "term.attach serves an agent id too: {attached:?}"
        );
        assert_eq!(attached["result"]["term_id"], json!(agent_wire_id));
        assert_eq!(attached["result"]["live"], true);
        assert!(attached["result"]["snapshot"].is_string());
        assert!(attached["result"]["cursor"].is_u64());

        // A well-formed agent id for a worktree with no tab is still "unknown
        // term_id", so a stale client drops the tab instead of hanging on one
        // that swallows every keystroke.
        let stale = handler.call(
            SessionSender::detached("s1"),
            req("term.attach", json!({ "term_id": "agent:nope" })),
        );
        assert_eq!(stale["ok"], false, "{stale:?}");
        assert_eq!(stale["error"], "unknown term_id");
    }

    /// The agent tab is not one of the human's tabs to close.
    ///
    /// `term.close` serves one id space, so the agent's wire id resolves there
    /// like any other — and closing it would kill the one PTY every human→agent
    /// path lands in, from a surface that renders it as a `×`-less fixture. The
    /// refusal is what makes "always reachable" survive a stale or hand-rolled
    /// client; the tab's life belongs to the worktree.
    #[tokio::test]
    async fn term_close_refuses_the_agent_tab() {
        let (dir, repo) = init_repo();
        let (state, handler, root) = agent_tab_fixture(&repo, dir.path(), "run-unclosable");
        let (agent_wire_id, _) = ensure_agent_tab(
            &state,
            &root,
            "run-unclosable",
            &crate::agent::derived_agent_id("run-unclosable"),
            &ModelChoice::default(),
        )
        .unwrap();

        let refused = handler.call(
            SessionSender::detached("s1"),
            req("term.close", json!({ "term_id": agent_wire_id })),
        );
        assert_eq!(refused["ok"], false, "{refused:?}");
        assert_eq!(refused["error"], "cannot close an agent terminal");

        let s = state.lock().unwrap();
        let key = derived_agent_key(&AppState::canonical_root(&root), "run-unclosable");
        let tab = s.tabs.get(&key).expect("the agent tab is still registered");
        assert!(tab.live, "and its session was never killed");
        assert!(tab.session_is_live());
    }

    /// A user terminal is the user's own login shell and nothing else. The
    /// daemon owns the argv, so a client naming a kind can never turn a tab
    /// into an arbitrary command line.
    #[test]
    fn a_user_terminal_only_ever_launches_the_login_shell() {
        let shell = shell_harness_spec("/bin/zsh");
        assert_eq!(shell.binary, "/bin/zsh");
        assert_eq!(shell.args, ["-i", "-l"]);
    }

    /// The `+` menu no longer offers to start an agent, and the daemon refuses
    /// to if asked.
    ///
    /// A `claude`/`codex` tab carried the provider's approvals bypass and NO
    /// `done` MCP server: an agent in a worktree that Build could not talk to
    /// and could not route a report from. A branch may carry as many agents as
    /// the human adds, but every one of them arrives through `agent.add` and is
    /// therefore Build-owned — which is what this refusal keeps true. An old
    /// client asking must fail loudly and be told where an agent comes from —
    /// never fall back to a shell, which would silently run a different program
    /// than was asked for.
    #[test]
    fn a_terminal_kind_naming_an_agent_is_refused_and_points_at_agent_add() {
        assert!(require_shell_kind(&json!({})).is_ok());
        assert!(require_shell_kind(&json!({ "kind": "" })).is_ok());
        assert!(require_shell_kind(&json!({ "kind": "shell" })).is_ok());

        for named_agent in AgentProvider::ALL.map(AgentProvider::wire_id) {
            let refused = require_shell_kind(&json!({ "kind": named_agent })).unwrap_err();
            assert!(
                refused.contains("agent.add"),
                "{named_agent}: {refused:?} must name where an agent comes from"
            );
        }
        assert_eq!(
            require_shell_kind(&json!({ "kind": "sh -c curl evil" })).unwrap_err(),
            "unknown terminal kind \"sh -c curl evil\" — a user terminal is always the shell"
        );
    }

    /// The kind rides the wire both ways: `term.create` echoes it and
    /// `term.list` carries it, so a reloaded client labels the tab by what is
    /// actually running in it. There is only one answer now — `shell` — and it
    /// stays on the wire because the SPA reads it.
    #[tokio::test]
    async fn term_create_carries_its_kind_onto_the_tab_list() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let project_id = state.lock().unwrap().projects[0].id.clone();

        let created = handler.call(
            SessionSender::detached("s1"),
            req(
                "term.create",
                json!({ "project_id": project_id, "kind": "shell" }),
            ),
        );
        assert_eq!(created["ok"], true, "{created:?}");
        assert_eq!(created["result"]["kind"], "shell");

        let listed = handler.call(
            SessionSender::detached("s1"),
            req("term.list", json!({ "project_id": project_id })),
        );
        let terminals = listed["result"]["terminals"].as_array().unwrap();
        assert_eq!(terminals.len(), 1);
        assert_eq!(terminals[0]["kind"], "shell");

        // An unknown kind is refused BEFORE anything is spawned.
        let bogus = handler.call(
            SessionSender::detached("s1"),
            req(
                "term.create",
                json!({ "project_id": project_id, "kind": "bash -c evil" }),
            ),
        );
        assert_eq!(bogus["ok"], false, "{bogus:?}");
        assert!(
            bogus["error"]
                .as_str()
                .unwrap()
                .contains("unknown terminal kind"),
            "{bogus:?}"
        );
        assert_eq!(state.lock().unwrap().shell_tab_count(), 1);
    }

    #[tokio::test]
    async fn term_create_enforces_the_daemon_wide_cap() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let project_id = state.lock().unwrap().projects[0].id.clone();

        for _ in 0..MAX_USER_TERMINALS {
            let created = handler.call(
                SessionSender::detached("s1"),
                req("term.create", json!({ "project_id": project_id })),
            );
            assert_eq!(created["ok"], true, "{created:?}");
        }
        let over = handler.call(
            SessionSender::detached("s1"),
            req("term.create", json!({ "project_id": project_id })),
        );
        assert_eq!(over["ok"], false);
        assert_eq!(
            over["error"],
            "terminal limit reached (16 open terminals) — close one first"
        );
    }

    #[tokio::test]
    async fn pump_eof_reaps_the_terminal_and_pushes_exited() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let project_id = state.lock().unwrap().projects[0].id.clone();

        handler.call(
            SessionSender::detached("s1"),
            req("term.create", json!({ "project_id": project_id })),
        );
        let (sender, mut pushes, key) = SessionSender::observable("s1");
        handler.call(sender, req("term.attach", json!({ "term_id": "term-1" })));
        let pid = tab_pid(&state, "term-1").expect("the shell is registered");

        // The user types `exit`: the shell ends on its own (PTY EOF).
        handler.call(
            SessionSender::detached("s1"),
            req(
                "term.input",
                json!({ "term_id": "term-1", "data": b64encode(b"exit\r") }),
            ),
        );
        wait_for_push(&mut pushes, &key, |p| {
            p["type"] == "term.closed" && p["term_id"] == "term-1" && p["reason"] == "exited"
        })
        .await;
        assert_eq!(state.lock().unwrap().shell_tab_count(), 0);
        assert!(process_reaped(pid), "an exited shell must still be reaped");
    }

    // ---- the agent tab primitive: a path-keyed, tab-backed PTY --------------

    /// A shared QA state, a worktree-like root to run an agent in, and an owner
    /// id bound to the state's project — the three things an agent tab needs
    /// (the owner resolves the project whose orchestrator builds the harness).
    fn agent_tab_fixture(
        repo: &std::path::Path,
        dir: &std::path::Path,
        owner: &str,
    ) -> (Arc<Mutex<AppState>>, FrameHandler, PathBuf) {
        let (state, handler) = shared_state_and_handler(repo, dir);
        let root = dir.join("agent-root");
        std::fs::create_dir_all(&root).unwrap();
        {
            let mut s = state.lock().unwrap();
            let project_id = s.projects[0].id.clone();
            s.entity_project.insert(owner.to_string(), project_id);
        }
        (state, handler, root)
    }

    /// The agent tab's screen, rendered — what an attaching client would see.
    fn agent_screen_text(state: &Arc<Mutex<AppState>>, root: &std::path::Path) -> String {
        let root = AppState::canonical_root(root);
        let s = state.lock().unwrap();
        let Some(tab) = s
            .tabs
            .values()
            .find(|tab| tab.root == root && matches!(tab.role, TabRole::Agent { .. }))
        else {
            return String::new();
        };
        String::from_utf8_lossy(&b64decode(&screen_of(tab).snapshot().snapshot).unwrap())
            .into_owned()
    }

    /// Poll the agent tab's screen until it shows `needle` (the pump feeds it),
    /// returning what was on screen at the end either way.
    async fn wait_for_agent_screen(
        state: &Arc<Mutex<AppState>>,
        root: &std::path::Path,
        needle: &str,
    ) -> String {
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        loop {
            let text = agent_screen_text(state, root);
            if text.contains(needle) || std::time::Instant::now() >= deadline {
                return text;
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
    }

    /// One worktree, one agent: find-or-create keyed by the canonical root, so
    /// a second call hands back the SAME tab (warm) rather than a second
    /// harness in the same directory.
    #[tokio::test]
    async fn ensure_agent_tab_is_idempotent_for_one_root() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-one-agent");
        let choice = ModelChoice::default();

        let (first_id, first) = ensure_agent_tab(
            &state,
            &root,
            "run-one-agent",
            &crate::agent::derived_agent_id("run-one-agent"),
            &choice,
        )
        .expect("the agent spawns");
        let (second_id, second) = ensure_agent_tab(
            &state,
            &root,
            "run-one-agent",
            &crate::agent::derived_agent_id("run-one-agent"),
            &choice,
        )
        .expect("the agent is found");

        assert_eq!(first, Spawned::Fresh, "the first call creates the tab");
        assert_eq!(second, Spawned::Warm, "the second call finds it");
        assert_eq!(first_id, second_id, "both calls address one tab");
        assert_eq!(
            first_id,
            agent_tab_id(&crate::agent::derived_agent_id("run-one-agent")),
            "an agent tab is addressed by the agent, not by the entity that owns it"
        );

        let s = state.lock().unwrap();
        assert_eq!(s.tabs.len(), 1, "exactly one tab in the registry");
        assert!(
            s.agent_spawns_in_flight.is_empty(),
            "the spawn reservation is released"
        );
        // Under --strict-mcp-config a missing config kills the harness before it
        // reads a byte of the prompt, so the scaffold is part of the spawn.
        assert!(root
            .join(crate::orchestrator::mcp_config_path(
                &crate::agent::derived_agent_id("run-one-agent")
            ))
            .exists());
    }

    /// Two deliveries racing on one worktree must produce ONE harness: the find
    /// and the in-flight reservation are taken under the same lock, so the
    /// loser waits for the winner's tab instead of spawning a second agent
    /// (two agents in one worktree both report `done` for the same owner, and
    /// the second report lands as a bogus failure on the thread).
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn concurrent_ensure_agent_tab_spawns_one_agent() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-race");

        let mut racers = Vec::new();
        for _ in 0..4 {
            let state = Arc::clone(&state);
            let root = root.clone();
            racers.push(tokio::task::spawn_blocking(move || {
                ensure_agent_tab(
                    &state,
                    &root,
                    "run-race",
                    &crate::agent::derived_agent_id("run-race"),
                    &ModelChoice::default(),
                )
            }));
        }
        let mut outcomes = Vec::new();
        for racer in racers {
            outcomes.push(racer.await.unwrap().expect("every racer gets the tab"));
        }

        let fresh = outcomes
            .iter()
            .filter(|(_, spawned)| *spawned == Spawned::Fresh)
            .count();
        assert_eq!(fresh, 1, "exactly one caller spawned: {outcomes:?}");
        assert!(
            outcomes.iter().all(|(id, _)| id == &outcomes[0].0),
            "every caller addresses the same tab: {outcomes:?}"
        );
        let s = state.lock().unwrap();
        assert_eq!(
            s.tabs.len(),
            1,
            "one worktree, one agent {:?}",
            s.tabs.keys().collect::<Vec<_>>()
        );
        assert!(s.agent_spawns_in_flight.is_empty());
    }

    /// The cold/warm rule: a tab that had to be spawned gets the full prompt (a
    /// cold agent has no context to read messages into), and a tab that was
    /// already alive gets the short nudge — the messages are already durable in
    /// the thread. The PTY echoes what is written to it, so the tab's screen is
    /// the proof of which one travelled.
    #[tokio::test]
    async fn deliver_sends_the_cold_prompt_on_a_fresh_tab_and_the_nudge_on_a_warm_one() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-deliver");
        let choice = ModelChoice::default();

        let (cold_id, cold_spawned) = deliver(
            &state,
            &root,
            "run-deliver",
            &crate::agent::derived_agent_id("run-deliver"),
            &choice,
            "COLD-CONTEXT-PROMPT",
            "WARM-NUDGE-PROMPT",
        )
        .expect("a cold delivery spawns and submits");
        assert_eq!(cold_spawned, Spawned::Fresh);
        let cold_screen = wait_for_agent_screen(&state, &root, "COLD-CONTEXT-PROMPT").await;
        assert!(
            cold_screen.contains("COLD-CONTEXT-PROMPT"),
            "a fresh tab hears the cold prompt: {cold_screen:?}"
        );
        assert!(
            !cold_screen.contains("WARM-NUDGE-PROMPT"),
            "a fresh tab must NOT hear the nudge: {cold_screen:?}"
        );

        let (warm_id, warm_spawned) = deliver(
            &state,
            &root,
            "run-deliver",
            &crate::agent::derived_agent_id("run-deliver"),
            &choice,
            "COLD-CONTEXT-PROMPT",
            "WARM-NUDGE-PROMPT",
        )
        .expect("a warm delivery reuses the tab");
        assert_eq!(warm_spawned, Spawned::Warm);
        assert_eq!(warm_id, cold_id, "both deliveries address one tab");
        let warm_screen = wait_for_agent_screen(&state, &root, "WARM-NUDGE-PROMPT").await;
        assert!(
            warm_screen.contains("WARM-NUDGE-PROMPT"),
            "a warm tab hears the nudge: {warm_screen:?}"
        );
        assert_eq!(state.lock().unwrap().tabs.len(), 1);
    }

    /// A session that answers what the app-wide state lock was doing at the
    /// moment its turn arrived.
    ///
    /// It cannot own the state — the state owns the tab that owns the session —
    /// so it holds a `Weak` and upgrades it for the one question it asks.
    struct LockProbingSession {
        state: std::sync::Weak<Mutex<AppState>>,
        state_was_free: Arc<std::sync::atomic::AtomicBool>,
    }

    impl AgentSession for LockProbingSession {
        fn send_turn(&self, _turn: &Turn) -> Result<(), HarnessError> {
            let state = self.state.upgrade().expect("the daemon outlives the turn");
            // `try_lock` on a std mutex fails for the thread that already holds
            // it, so this reads the DELIVERY's own lock, not a race with some
            // other caller's.
            self.state_was_free.store(
                state.try_lock().is_ok(),
                std::sync::atomic::Ordering::Relaxed,
            );
            Ok(())
        }
        fn status(&self) -> AgentStatus {
            AgentStatus::Waiting
        }
        fn quiet_for(&self) -> Duration {
            Duration::ZERO
        }
        fn exited_within(&self, _timeout: Duration) -> bool {
            false
        }
        fn end(&self) {}
        fn backdate_last_output(&self, _ago: Duration) {}
    }

    /// The turn travels with the app-wide state lock RELEASED.
    ///
    /// Every RPC, every terminal pump and the idle sweep wait on that lock, so
    /// a carrier that takes its time accepting a turn — a protocol write to a
    /// full pipe, an ack the harness answers late — would stall the whole
    /// daemon if the turn were handed over under it. `AgentSession::send_turn`
    /// promises callers they may take that time; this is where the promise is
    /// kept, and it is kept for the exit-race wait on the failure path too.
    #[test]
    fn a_turn_travels_with_the_state_lock_released() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-lock");
        let agent_id = crate::agent::derived_agent_id("run-lock");
        let canonical = AppState::canonical_root(&root);
        let state_was_free = Arc::new(std::sync::atomic::AtomicBool::new(false));
        {
            let mut tab = terminal_free_agent_tab(&canonical, "run-lock", &agent_id);
            tab.session = Arc::new(LockProbingSession {
                state: Arc::downgrade(&state),
                state_was_free: Arc::clone(&state_was_free),
            });
            let mut s = state.lock().unwrap();
            s.tabs.insert(TabKey::agent(&canonical, &agent_id), tab);
        }

        let (_, spawned) = deliver(
            &state,
            &root,
            "run-lock",
            &agent_id,
            &ModelChoice::default(),
            "COLD-CONTEXT-PROMPT",
            "WARM-NUDGE-PROMPT",
        )
        .expect("the live tab takes the turn");

        assert_eq!(spawned, Spawned::Warm, "the tab was already alive");
        assert!(
            state_was_free.load(std::sync::atomic::Ordering::Relaxed),
            "a delivery must not hold the app-wide state lock across send_turn"
        );
        let s = state.lock().unwrap();
        assert!(
            s.tabs[&TabKey::agent(&canonical, &agent_id)]
                .last_delivered_at
                .is_some(),
            "the quiescence clock still restarts on the delivered turn"
        );
    }

    /// The conversation's open session for `owner`, if it has one.
    fn open_session_count(state: &Arc<Mutex<AppState>>, owner: &str) -> usize {
        primary_thread(&state.lock().unwrap().runs[owner].agents)
            .sessions
            .iter()
            .filter(|session| session.ended_at.is_none())
            .count()
    }

    /// A session belongs to the agent PROCESS, not to a phase. `done` is the
    /// agent finishing a turn at its prompt — it is still there, still in the
    /// same session — so the thread must not record a session end, and the warm
    /// turn that follows must not read back as a turn taken outside any
    /// session.
    #[tokio::test]
    async fn done_then_a_warm_turn_stays_in_one_open_session() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-lineage");
        state.lock().unwrap().runs.insert(
            "run-lineage".into(),
            crate::orchestrator::ActiveRun::reattach(
                &fake_run_record("run-lineage"),
                ".build/plan.md".into(),
            ),
        );
        let queue_turn = || {
            state
                .lock()
                .unwrap()
                .pending_agent_turns
                .push(PendingAgentTurn {
                    root: AppState::canonical_root(&root),
                    owner: "run-lineage".into(),
                    agent_id: crate::agent::derived_agent_id("run-lineage"),
                    model_choice: ModelChoice::default(),
                    say: Some(TurnText {
                        cold: "COLD-TURN".into(),
                        warm: "WARM-TURN".into(),
                    }),
                    phase: "build",
                    wants_catch_up: false,
                    survives_refusal: false,
                });
        };

        queue_turn();
        deliver_pending_agent_turns(&state);
        assert_eq!(
            open_session_count(&state, "run-lineage"),
            1,
            "a cold delivery opens the session"
        );

        state.lock().unwrap().on_agent_done(
            "run-lineage",
            DoneReport {
                phase: DonePhase::Build,
                status: DoneStatus::Completed,
                summary: "built".into(),
                outputs: DoneOutputs::default(),
            },
        );
        queue_turn();
        deliver_pending_agent_turns(&state);

        let s = state.lock().unwrap();
        let thread = primary_thread(&s.runs["run-lineage"].agents);
        assert_eq!(
            thread.sessions.len(),
            1,
            "a warm turn continues the one session: {:?}",
            thread.sessions
        );
        assert!(
            thread.sessions[0].ended_at.is_none(),
            "the agent is still at its prompt: {:?}",
            thread.sessions
        );
        assert!(
            !thread.items.iter().any(|item| matches!(
                item,
                crate::thread::ThreadItem::Event(event)
                    if event.event == crate::thread::ThreadEventKind::SessionEnded
            )),
            "no session ended, so the thread must not say one did: {:?}",
            thread.items
        );
    }

    /// A session ends where it really ends: when the agent's process does. The
    /// pump's EOF is the only place that knows, so that is where the thread
    /// learns it — otherwise a run whose agent died reads back as forever in
    /// session.
    #[tokio::test]
    async fn the_session_closes_when_the_agent_process_exits() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let (tab_key, _wire_id) =
            insert_live_run(&state, &repo, dir.path().join("side"), "run-eof");
        state
            .lock()
            .unwrap()
            .record_agent_session_start(&PendingAgentTurn {
                root: tab_key.root.clone(),
                owner: "run-eof".into(),
                agent_id: crate::agent::derived_agent_id("run-eof"),
                model_choice: ModelChoice::default(),
                say: None,
                phase: "build",
                wants_catch_up: false,
                survives_refusal: false,
            });
        assert_eq!(open_session_count(&state, "run-eof"), 1);

        state.lock().unwrap().tabs[&tab_key].session.end();

        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        while open_session_count(&state, "run-eof") > 0 {
            assert!(
                std::time::Instant::now() < deadline,
                "the agent's process ended and the session never closed"
            );
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        let s = state.lock().unwrap();
        assert_eq!(
            primary_thread(&s.runs["run-eof"].agents).sessions.len(),
            1,
            "the dead session is closed, not replaced"
        );
    }

    /// The feed row for a run, off `board.list` — the one place `working` is
    /// actually read from, so a test about a stuck working state asks there.
    fn feed_row_for_run(handler: &FrameHandler, run_id: &str) -> Value {
        let board = call(handler, "board.list", json!({}));
        board["result"]["items"]
            .as_array()
            .expect("the feed is a list of rows")
            .iter()
            .find(|row| row["run_id"] == json!(run_id))
            .unwrap_or_else(|| panic!("no feed row for {run_id}: {board:?}"))
            .clone()
    }

    /// The conversation an entity's primary agent owns — what a test that
    /// predates the agent rail means by "the entity's thread".
    fn primary_thread(roster: &crate::agent::AgentRoster) -> &crate::thread::Thread {
        &roster.primary().expect(THE_TEST_PUT_AN_AGENT_HERE).thread
    }

    /// The same conversation, to write on: a test that says what an agent
    /// heard or answered before the assertion it is really about.
    fn primary_thread_mut(roster: &mut crate::agent::AgentRoster) -> &mut crate::thread::Thread {
        &mut roster
            .primary_mut()
            .expect(THE_TEST_PUT_AN_AGENT_HERE)
            .thread
    }

    const THE_TEST_PUT_AN_AGENT_HERE: &str = "the entity holds the agent this test put there";

    /// The interruption a dead session leaves on a conversation, if it left
    /// one.
    fn interruption_in(thread: &crate::thread::Thread) -> Option<&crate::thread::ThreadEvent> {
        thread.items.iter().find_map(|item| match item {
            crate::thread::ThreadItem::Event(event)
                if event.event == crate::thread::ThreadEventKind::Interrupted =>
            {
                Some(event)
            }
            _ => None,
        })
    }

    /// Hand `run_id`'s first agent a turn: the human asks, the agent reads it,
    /// nothing comes back. That read is what starts the working clock.
    fn open_a_turn(state: &Arc<Mutex<AppState>>, run_id: &str) {
        let mut s = state.lock().unwrap();
        let run = s.runs.get_mut(run_id).expect("the run is on the board");
        primary_thread_mut(&mut run.agents).post_user("do the thing", None, "2026-08-15T10:00:00Z");
        primary_thread_mut(&mut run.agents).read_unread("2026-08-15T10:00:01Z");
        assert!(
            primary_thread(&run.agents).working_since().is_some(),
            "the agent read the message, so it holds the turn"
        );
    }

    /// A killed agent process must not leave its row working.
    ///
    /// The run sits at its review gate, so its STATE claims nothing — the row's
    /// working flag comes entirely from the open turn, which is the half the
    /// idle sweep cannot reach (it only demotes entities whose state is
    /// working). The pump's EOF is where the death is noticed, so that is where
    /// the turn closes.
    #[tokio::test]
    async fn a_killed_agent_process_leaves_its_row_inactive() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let (tab_key, _wire_id) =
            insert_live_run(&state, &repo, dir.path().join("side"), "run-killed");
        state
            .lock()
            .unwrap()
            .runs
            .get_mut("run-killed")
            .unwrap()
            .run
            .state = RunState::Review;
        open_a_turn(&state, "run-killed");
        assert_eq!(
            feed_row_for_run(&handler, "run-killed")["working"],
            json!(true),
            "a turn in flight is the row working"
        );

        state.lock().unwrap().tabs[&tab_key].session.end();

        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        let row = loop {
            let row = feed_row_for_run(&handler, "run-killed");
            if row["working"] == json!(false) {
                break row;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "the agent's process was killed and the row still claims it is working: {row:?}"
            );
            tokio::time::sleep(Duration::from_millis(20)).await;
        };
        assert_eq!(
            row["unread_reason"], "interrupted",
            "the row says why the work stopped: {row:?}"
        );

        let s = state.lock().unwrap();
        let thread = primary_thread(&s.runs["run-killed"].agents);
        assert_eq!(thread.working_since(), None, "the turn is closed");
        let interruption = interruption_in(thread).expect("the conversation records the death");
        assert!(
            interruption
                .summary
                .as_deref()
                .is_some_and(|said| said.contains("without reporting")),
            "the entry says the session ended without reporting: {interruption:?}"
        );
    }

    /// A second agent on a run, with its own PTY tab and its own conversation —
    /// the shape of a branch carrying more than one agent. Returns its id and
    /// the key of the tab it runs in.
    fn add_second_agent(state: &Arc<Mutex<AppState>>, run_id: &str) -> (String, TabKey) {
        let (agent_id, root) = {
            let mut s = state.lock().unwrap();
            let active = s.runs.get_mut(run_id).expect("the run is on the board");
            let agent_id = active
                .agents
                .add(run_id, ModelChoice::default(), "2026-08-15T10:00:00Z")
                .id
                .clone();
            let root = AppState::canonical_root(&active.worktree.path);
            (agent_id, root)
        };
        let (tab, rx) = Tab::spawn(
            TabRole::Agent {
                owner: run_id.to_string(),
                agent_id: agent_id.clone(),
                provider: AgentProvider::default(),
            },
            &warm_tui_spec(),
            agent_tab_id(&agent_id),
            root.clone(),
            120,
            40,
            None,
        )
        .expect("the second agent's tab spawns");
        let key = TabKey::agent(&root, &agent_id);
        state.lock().unwrap().tabs.insert(key.clone(), tab);
        spawn_tab_pumps(state, key.clone(), rx);
        (agent_id, key)
    }

    /// One agent dying is not every agent dying. The interruption lands on the
    /// conversation of the agent whose process ended, and the agent beside it
    /// — still running, still mid-turn — keeps its turn and hears nothing.
    #[tokio::test]
    async fn a_dead_agents_interruption_lands_on_its_own_conversation() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let (_first_key, _wire_id) =
            insert_live_run(&state, &repo, dir.path().join("side"), "run-two-agents");
        open_a_turn(&state, "run-two-agents");
        let (second_id, second_key) = add_second_agent(&state, "run-two-agents");
        {
            let mut s = state.lock().unwrap();
            let second = s.runs.get_mut("run-two-agents").unwrap();
            let second = second.agents.by_id_mut(&second_id).expect("just added");
            second
                .thread
                .post_user("and this one too", None, "2026-08-15T10:00:02Z");
            second.thread.read_unread("2026-08-15T10:00:03Z");
        }

        state.lock().unwrap().tabs[&second_key].session.end();

        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        loop {
            {
                let s = state.lock().unwrap();
                let roster = &s.runs["run-two-agents"].agents;
                let second = roster.by_id(&second_id).expect("still on the roster");
                if second.thread.working_since().is_none() {
                    assert!(
                        interruption_in(&second.thread).is_some(),
                        "the dead agent's own conversation records it: {:?}",
                        second.thread.items
                    );
                    assert!(
                        roster.primary().unwrap().thread.working_since().is_some(),
                        "the agent still running keeps its turn"
                    );
                    assert!(
                        interruption_in(&roster.primary().unwrap().thread).is_none(),
                        "and is told nothing: {:?}",
                        roster.primary().unwrap().thread.items
                    );
                    break;
                }
            }
            assert!(
                std::time::Instant::now() < deadline,
                "the second agent's process was killed and its turn never closed"
            );
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
    }

    /// A process that exits after the agent handed back is an ordinary ending,
    /// not an interruption. The marker exists to close a turn nobody else will
    /// ever close, so a conversation with no turn in flight gains nothing.
    #[tokio::test]
    async fn a_process_that_exits_after_handing_back_records_no_interruption() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let (tab_key, _wire_id) =
            insert_live_run(&state, &repo, dir.path().join("side"), "run-handback");
        state
            .lock()
            .unwrap()
            .runs
            .get_mut("run-handback")
            .unwrap()
            .run
            .state = RunState::Review;
        open_a_turn(&state, "run-handback");
        {
            let mut s = state.lock().unwrap();
            let run = s.runs.get_mut("run-handback").unwrap();
            primary_thread_mut(&mut run.agents).post_agent(
                "here is what I did",
                None,
                "2026-08-15T10:05:00Z",
            );
            assert_eq!(
                primary_thread(&run.agents).working_since(),
                None,
                "the reply hands back"
            );
        }

        state.lock().unwrap().tabs[&tab_key].session.end();

        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        while state.lock().unwrap().tabs[&tab_key].live {
            assert!(
                std::time::Instant::now() < deadline,
                "the pump never noticed the process end"
            );
            tokio::time::sleep(Duration::from_millis(20)).await;
        }

        let row = feed_row_for_run(&handler, "run-handback");
        assert_eq!(row["working"], json!(false), "{row:?}");
        let s = state.lock().unwrap();
        assert!(
            interruption_in(primary_thread(&s.runs["run-handback"].agents)).is_none(),
            "a handed-back turn is not interrupted: {:?}",
            primary_thread(&s.runs["run-handback"].agents).items
        );
    }

    /// A worktree deleted out-of-band (`rm -rf` by hand — nothing went through
    /// a Build verb) takes its agent tab through `reap_orphaned_terminals`,
    /// which removes the tab from the registry BEFORE killing the process. The
    /// pump's EOF handler looks the tab up and finds nothing, so the reaper is
    /// the only place left that knows this session ended — and the run stays on
    /// the board. If it forgot to close the turn, the row would read working
    /// forever: the exact bug the pump path already fixes, through a different
    /// exit.
    ///
    /// The run is Merged — a run kept with `cleanup=keep`, its directory later
    /// deleted by hand while a follow-up question had its agent mid-turn. That
    /// is the shape where nothing else ever cleans up: `board.list`'s archive
    /// sweep skips terminal runs, so this row is on the board for good, and the
    /// reaper's close is the only one it will ever get.
    #[tokio::test]
    async fn the_reaper_closes_the_turn_of_an_agent_whose_worktree_vanished() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let (tab_key, wire_id) =
            insert_live_run(&state, &repo, dir.path().join("side"), "run-vanished");
        state
            .lock()
            .unwrap()
            .runs
            .get_mut("run-vanished")
            .unwrap()
            .run
            .state = RunState::Merged;
        open_a_turn(&state, "run-vanished");
        assert_eq!(
            feed_row_for_run(&handler, "run-vanished")["working"],
            json!(true),
            "a turn in flight is the row working"
        );

        std::fs::remove_dir_all(&tab_key.root).expect("the user rm -rfs the checkout");
        let reaped = state.lock().unwrap().reap_orphaned_terminals();
        assert!(
            reaped.contains(&wire_id),
            "the reaper closes the vanished worktree's tab: {reaped:?}"
        );

        let row = feed_row_for_run(&handler, "run-vanished");
        assert_eq!(
            row["working"],
            json!(false),
            "the run stays on the board and its row leaves working: {row:?}"
        );
        assert_eq!(
            row["unread_reason"], "interrupted",
            "the row says why the work stopped: {row:?}"
        );
        let s = state.lock().unwrap();
        let thread = primary_thread(&s.runs["run-vanished"].agents);
        assert_eq!(thread.working_since(), None, "the turn is closed");
        let interruption = interruption_in(thread).expect("the conversation records the death");
        assert!(
            interruption
                .summary
                .as_deref()
                .is_some_and(|said| said.contains("without reporting")),
            "the entry says the session ended without reporting: {interruption:?}"
        );
    }

    /// Point a QA state's only project at a different agent — the seam every
    /// test that cares about what actually gets spawned goes through.
    fn use_agent(state: &Arc<Mutex<AppState>>, repo: &std::path::Path, wt: PathBuf, agent: Agent) {
        state.lock().unwrap().projects[0].orch =
            Orchestrator::new(repo.to_path_buf(), wt, agent, Templates::default());
    }

    /// The rendered turn is always multi-line (the conversation protocol block
    /// is appended), so through a real TUI it must arrive as ONE bracketed
    /// paste. The capture harness never paints, so this also proves the
    /// readiness grace expires into a write rather than a silently lost prompt.
    #[tokio::test]
    async fn a_delivered_turn_reaches_a_silent_harness_as_one_bracketed_paste() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-paste");
        let capture = dir.path().join("agent-stdin.txt");
        let capture_for_builder = capture.clone();
        use_agent(
            &state,
            &repo,
            dir.path().join("wt2"),
            Agent::WarmBuilder(std::sync::Arc::new(
                move |_prompt: &str, _choice: &ModelChoice, _options: &SpawnOptions| {
                    HarnessSpec::new("sh")
                        .arg("-c")
                        .arg("cat > \"$1\"")
                        .arg("build-agent-capture")
                        .arg(capture_for_builder.to_string_lossy())
                },
            )),
        );

        deliver(
            &state,
            &root,
            "run-paste",
            &crate::agent::derived_agent_id("run-paste"),
            &ModelChoice::default(),
            "Paste framing marker\nsecond line",
            "warm",
        )
        .expect("the delivery reaches a silent harness");

        let captured = tokio::time::timeout(Duration::from_secs(10), async {
            loop {
                if let Ok(contents) = std::fs::read_to_string(&capture) {
                    if contents.contains("\u{1b}[201~") {
                        return contents;
                    }
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("the framed turn should reach the harness despite its silence");

        assert!(
            captured.starts_with("\u{1b}[200~"),
            "the turn opens as a bracketed paste: {captured:?}"
        );
        assert!(
            captured.contains("Paste framing marker"),
            "the rendered turn rides inside the frame: {captured:?}"
        );
    }

    /// The prompt-write race, end to end: a harness that exits instantly closes
    /// its PTY (the write fails with EIO) *before* the OS makes its exit status
    /// reapable, so a single status poll says "running". That must not
    /// fail the delivery — the tab is still the agent's tab, and the crash is
    /// the idle monitor's to report, not the delivery's.
    #[tokio::test]
    async fn a_harness_that_exits_under_the_prompt_write_still_keeps_its_tab() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-exits");
        use_agent(&state, &repo, dir.path().join("wt2"), instant_exit_agent());

        let delivered = deliver(
            &state,
            &root,
            "run-exits",
            &crate::agent::derived_agent_id("run-exits"),
            &ModelChoice::default(),
            "cold",
            "warm",
        );

        assert!(
            delivered.is_ok(),
            "a write against an exiting harness is benign: {delivered:?}"
        );
        let s = state.lock().unwrap();
        assert!(
            s.tabs.contains_key(&derived_agent_key(
                &AppState::canonical_root(&root),
                "run-exits"
            )),
            "the tab is retained so the crash is legible"
        );
    }

    /// An agent that is gone before it reads a byte.
    fn instant_exit_agent() -> Agent {
        Agent::WarmBuilder(std::sync::Arc::new(
            |_prompt: &str, _choice: &ModelChoice, _options: &SpawnOptions| {
                HarnessSpec::new("sh").arg("-c").arg("exit 0")
            },
        ))
    }

    /// The daemon-wide terminal cap counts the human's own shells WHEREVER they
    /// are held — including the tab registry — and never counts an agent tab.
    ///
    /// Both halves have teeth. A shell that escapes the cap by living on the
    /// new registry is the cap quietly doubling; an agent that sixteen open
    /// shells could crowd out is not "always reachable", which is the
    /// invariant's direct negation. So the fixture holds one agent tab and one
    /// shell tab: exactly fifteen more shells must fit, and the sixteenth must
    /// not.
    #[tokio::test]
    async fn the_terminal_cap_counts_shell_tabs_and_never_the_agent() {
        let (dir, repo) = init_repo();
        let (state, handler, root) = agent_tab_fixture(&repo, dir.path(), "run-cap");
        let project_id = state.lock().unwrap().projects[0].id.clone();

        ensure_agent_tab(
            &state,
            &root,
            "run-cap",
            &crate::agent::derived_agent_id("run-cap"),
            &ModelChoice::default(),
        )
        .unwrap();
        // One of the human's own shells, held as a tab rather than in `terms`.
        let shell_root = AppState::canonical_root(&repo);
        let shell_key = TabKey {
            root: shell_root.clone(),
            tab_id: "term-99".to_string(),
        };
        let (shell_tab, _shell_rx) = Tab::spawn(
            TabRole::Shell,
            &shell_harness_spec("/bin/bash"),
            "term-99".to_string(),
            shell_root,
            80,
            24,
            None,
        )
        .expect("a shell tab spawns");
        state.lock().unwrap().tabs.insert(shell_key, shell_tab);

        // The agent takes none of the sixteen, so fifteen more shells fit
        // beside the one shell tab...
        for n in 1..MAX_USER_TERMINALS {
            let created = handler.call(
                SessionSender::detached("s1"),
                req("term.create", json!({ "project_id": project_id })),
            );
            assert_eq!(created["ok"], true, "shell {n} of the cap: {created:?}");
        }
        // ...and the sixteenth does not: the shell tab is one of them.
        let over = handler.call(
            SessionSender::detached("s1"),
            req("term.create", json!({ "project_id": project_id })),
        );
        assert_eq!(over["ok"], false, "the shell tab is one of the sixteen");
        assert!(
            over["error"]
                .as_str()
                .unwrap_or_default()
                .contains("terminal limit reached"),
            "{over:?}"
        );
    }

    #[test]
    fn mcp_control_frames_require_the_current_session_token() {
        let sessions = HashMap::from([("run-1".to_string(), "secret-current".to_string())]);
        let valid = json!({
            "task_id": "run-1",
            "session_token": "secret-current",
            "report": { "phase": "build", "status": "completed", "summary": "done", "outputs": {} }
        });
        assert_eq!(authenticated_mcp_owner(&valid, &sessions), Some("run-1"));
        assert_eq!(
            authenticated_mcp_owner(
                &json!({ "task_id": "run-1", "session_token": "stale" }),
                &sessions
            ),
            None
        );
        assert_eq!(
            authenticated_mcp_owner(&json!({ "task_id": "run-1" }), &sessions),
            None
        );
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn done_socket_is_explicitly_owner_only() {
        use std::os::unix::fs::PermissionsExt;

        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("mcp.sock");
        let _listener = bind_done_listener(&path).expect("bind private MCP socket");
        let mode = std::fs::metadata(&path).unwrap().permissions().mode() & 0o777;
        assert_eq!(mode, 0o600);
    }

    /// An agent tab is a MANAGED agent: the spec it spawns from carries Build's
    /// `done` MCP server and the owner id that routes reports back through the
    /// owner lookup. The socket lives inside the harness builder's closure, so
    /// `agent_harness_spec` is the only way the app layer can reach it — and a
    /// spec that dropped the config or the owner would open an agent Build
    /// cannot talk to, in a tab that looks entirely healthy.
    #[test]
    fn agent_harness_spec_carries_the_done_mcp_server_and_the_owner_id() {
        // claude's pre-trust writes a registry; keep it off the developer's own.
        let config_dir = tempfile::tempdir().unwrap();
        std::env::set_var("CLAUDE_CONFIG_DIR", config_dir.path());
        let orch = Orchestrator::new(
            "/repo",
            "/repo/.worktrees",
            build_agent(false, "/tmp/build mcp.sock".into()),
            Templates::default(),
        );
        let cwd = std::path::Path::new("/repo/.worktrees/wt-1");
        let claude = ModelChoice {
            provider: AgentProvider::Claude,
            model: None,
            effort: None,
        };
        let codex = ModelChoice {
            provider: AgentProvider::Codex,
            model: None,
            effort: None,
        };

        let spec = orch.agent_harness_spec("agent-42", cwd, &claude, false, None, "token-42");
        assert_eq!(spec.binary, "claude");
        let args = spec.args.join(" ");
        assert!(
            args.contains("--mcp-config .build/mcp-agent-42.json --strict-mcp-config"),
            "the harness reads the config written for THIS agent: {args}"
        );
        assert!(!args.contains("--continue"), "{args}");
        assert!(
            spec.env
                .iter()
                .any(|(key, value)| key == "BRIDGE_MCP_SOCKET" && value == "/tmp/build mcp.sock"),
            "{:?}",
            spec.env
        );
        // A replaced tab picks its own conversation back up.
        let resumed = orch.agent_harness_spec("run-42", cwd, &claude, true, None, "token-43");
        assert!(resumed.args.join(" ").contains("--continue"));

        let spec = orch.agent_harness_spec("run-42", cwd, &codex, false, None, "token-42");
        assert_eq!(spec.binary, "codex");
        let args = spec.args.join(" ");
        assert!(
            args.contains(r#"mcp_servers.build.args=["mcp","--task","run-42"]"#),
            "{args}"
        );
        assert!(
            args.contains(r#"mcp_servers.build.env.BRIDGE_MCP_SOCKET="/tmp/build mcp.sock""#),
            "{args}"
        );
        assert!(
            args.contains(r#"projects."/repo/.worktrees/wt-1".trust_level="trusted""#),
            "{args}"
        );
        assert!(!args.ends_with("resume --last"), "{args}");
        let resumed = orch.agent_harness_spec("run-42", cwd, &codex, true, None, "token-43");
        assert!(resumed.args.join(" ").ends_with("resume --last"));

        std::env::remove_var("CLAUDE_CONFIG_DIR");
    }

    /// The tab spawns the spec the orchestrator built FOR IT: the run as
    /// `owner_id`, the canonical worktree as cwd, and — for an owner holding no
    /// record of a conversation, the shape a router has — no resume of any
    /// kind, however much the checkout already holds. The empty prompt is the
    /// contract too: a turn never rides in argv, it travels through the PTY.
    #[tokio::test]
    async fn an_agent_tab_spawns_the_harness_the_orchestrator_built() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-wired");
        let specs_built: Arc<Mutex<Vec<SpawnOptions>>> = Arc::new(Mutex::new(Vec::new()));
        {
            let recorder = Arc::clone(&specs_built);
            let agent = Agent::WarmBuilder(Arc::new(
                move |prompt: &str, _choice: &ModelChoice, options: &SpawnOptions| {
                    assert!(prompt.is_empty(), "a turn never rides in argv: {prompt:?}");
                    recorder.lock().unwrap().push(options.clone());
                    HarnessSpec::new("sh").arg("-c").arg(
                        "printf 'SPEC-FROM-THE-ORCHESTRATOR'; printf '\\033[?2004h'; cat >/dev/null",
                    )
                },
            ));
            let mut s = state.lock().unwrap();
            let worktrees = s.worktrees_root.clone();
            s.transcript_probe = Arc::new(|_, _| true);
            s.projects[0].orch =
                Orchestrator::new(repo.clone(), worktrees, agent, Templates::default());
        }

        ensure_agent_tab(
            &state,
            &root,
            "run-wired",
            &crate::agent::derived_agent_id("run-wired"),
            &ModelChoice::default(),
        )
        .expect("the agent spawns");

        let built = specs_built.lock().unwrap().clone();
        assert_eq!(built.len(), 1, "one spawn, one spec: {built:?}");
        assert_eq!(
            built[0].owner_id,
            crate::agent::derived_agent_id("run-wired"),
            "`done` names the AGENT that sent it; the entity is a lookup away"
        );
        assert_eq!(
            built[0].cwd,
            AppState::canonical_root(&root),
            "the spec is built for the canonical root"
        );
        assert!(
            !built[0].continue_session,
            "an owner with no record of a conversation inherits nobody else's"
        );
        let screen = wait_for_agent_screen(&state, &root, "SPEC-FROM-THE-ORCHESTRATOR").await;
        assert!(
            screen.contains("SPEC-FROM-THE-ORCHESTRATOR"),
            "the tab runs the orchestrator's spec: {screen:?}"
        );
    }

    /// The registry key is the CANONICAL worktree path, so the same worktree
    /// reaching the daemon by a different spelling — a run scope hands back
    /// `worktrees_root/<name>` uncanonicalized while an external worktree is
    /// already canonical, and on macOS `/tmp` is `/private/tmp` — is one tab,
    /// not two agents in one directory.
    #[tokio::test]
    async fn the_agent_tab_key_survives_the_same_root_by_another_path() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-alias");
        let alias = dir.path().join("alias-root");
        std::os::unix::fs::symlink(&root, &alias).unwrap();

        let (direct_id, direct) = ensure_agent_tab(
            &state,
            &root,
            "run-alias",
            &crate::agent::derived_agent_id("run-alias"),
            &ModelChoice::default(),
        )
        .unwrap();
        let (aliased_id, aliased) = ensure_agent_tab(
            &state,
            &alias,
            "run-alias",
            &crate::agent::derived_agent_id("run-alias"),
            &ModelChoice::default(),
        )
        .unwrap();

        assert_eq!(direct, Spawned::Fresh);
        assert_eq!(aliased, Spawned::Warm, "the alias finds the same tab");
        assert_eq!(direct_id, aliased_id);
        assert_eq!(state.lock().unwrap().tabs.len(), 1);
    }

    /// One registry, one detach loop: a closed relay session must come off
    /// EVERY tab's screen — the agent's as much as a shell's. A pump still
    /// encrypting output into a session the relay has dropped fails silently
    /// and shows up only as CPU.
    #[tokio::test]
    async fn a_close_frame_detaches_the_sessions_terminal_sender() {
        let (dir, repo) = init_repo();
        let (state, handler, root) = agent_tab_fixture(&repo, dir.path(), "run-detach");
        let project_id = state.lock().unwrap().projects[0].id.clone();
        let (agent_wire_id, _) = ensure_agent_tab(
            &state,
            &root,
            "run-detach",
            &crate::agent::derived_agent_id("run-detach"),
            &ModelChoice::default(),
        )
        .unwrap();
        handler.call(
            SessionSender::detached("s-live"),
            req("term.create", json!({ "project_id": project_id })),
        );
        for session_id in ["s-live", "s-dead"] {
            handler.call(
                SessionSender::detached(session_id),
                req("term.attach", json!({ "term_id": "term-1" })),
            );
            handler.call(
                SessionSender::detached(session_id),
                req("term.attach", json!({ "term_id": agent_wire_id.clone() })),
            );
        }

        let close = Frame {
            session_id: "s-dead".into(),
            message_id: String::new(),
            frame_type: "close".into(),
            sender: "relay".into(),
            created_at: String::new(),
            payload: Value::Null,
        };
        let response = dispatch_frame(
            &state,
            SessionSender::detached("s-dead"),
            close,
            FrameClock::new().frame("close"),
        );
        assert_eq!(response["ok"], true);

        let s = state.lock().unwrap();
        let attached_to = |wire_id: &str| -> Vec<String> {
            s.tabs
                .values()
                .find(|tab| tab.wire_id() == wire_id)
                .map(screen_of)
                .expect("the tab is still registered")
                .attached_sessions()
        };
        assert_eq!(
            attached_to("term-1"),
            vec!["s-live".to_string()],
            "only the closed session's sender is dropped from a shell"
        );
        assert_eq!(
            attached_to(&agent_wire_id),
            vec!["s-live".to_string()],
            "…and from the agent tab too"
        );
    }

