    #[tokio::test]
    async fn agent_choose_writes_on_the_named_agent_when_it_runs_another_harness() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_qa_state_and_handler(&repo, dir.path());
        let run_id = {
            let mut held = state.lock().unwrap();
            adopted_run(&mut held, &repo, dir.path(), "feature-two-harnesses")
        };
        let claude_agent = {
            let held = state.lock().unwrap();
            primary_agent_id(&held, &run_id)
        };

        let added = call(
            &handler,
            "agent.add",
            json!({ "entity_id": run_id, "provider": "codex" }),
        );
        assert_eq!(added["ok"], true, "{added:?}");
        let codex_agent = added["result"]["agent"]["id"].as_str().unwrap().to_string();

        let chosen = call(
            &handler,
            "agent.choose",
            json!({ "entity_id": run_id, "agent_id": codex_agent, "model": "gpt-5.6-sol" }),
        );
        assert_eq!(chosen["ok"], true, "{chosen:?}");

        let digests = state
            .lock()
            .unwrap()
            .agent_digests(&run_id, DigestScope::List);
        let codex_digest = digests
            .iter()
            .find(|digest| digest["id"] == json!(codex_agent.clone()))
            .expect("the codex agent is on the roster");
        assert_eq!(codex_digest["model"], "gpt-5.6-sol");
        let claude_digest = digests
            .iter()
            .find(|digest| digest["id"] == json!(claude_agent.clone()))
            .expect("the claude agent is on the roster");
        assert_eq!(
            claude_digest["model"], "",
            "the other harness's agent keeps what it had"
        );
        assert_eq!(
            state.lock().unwrap().runs[&run_id]
                .model_choice
                .model
                .as_deref(),
            None,
            "the entity's own choice is not spent on another harness's agent"
        );
    }

    /// Switching provider under a running harness would leave that process
    /// running the old provider while the record claimed the new one — a
    /// stranded agent nobody owns. The switch is refused and the running
    /// session is left exactly as it was.
    #[tokio::test]
    async fn agent_start_refuses_a_provider_switch_while_the_agent_is_live() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let (key, _wire_id) = insert_live_run(&state, &repo, dir.path().join("side"), "run-mid");

        let refused = call(
            &handler,
            "agent.start",
            json!({ "id": "run-mid", "provider": "codex" }),
        );
        assert_eq!(refused["ok"], false, "{refused:?}");
        let error = refused["error"].as_str().unwrap();
        assert!(error.contains("stop the current session"), "{error}");
        assert!(
            !error.to_lowercase().contains("headless"),
            "the refusal prints provider labels, and no label names a carrier \
             the way the code does: {error}"
        );
        let s = state.lock().unwrap();
        assert_eq!(
            s.runs["run-mid"].model_choice.provider,
            AgentProvider::Claude,
            "a refused switch leaves the record alone"
        );
        assert!(
            s.tabs[&key].live,
            "and leaves the running harness where it was"
        );
    }

    /// Naming the provider the entity already runs on is not a switch: nothing
    /// is stranded, so the idempotent "give me the tab" start still works while
    /// a session is live.
    #[tokio::test]
    async fn agent_start_naming_the_live_agents_own_provider_is_idempotent() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let (key, wire_id) = insert_live_run(&state, &repo, dir.path().join("side"), "run-same");
        let live_pid = agent_pid(&state.lock().unwrap().tabs[&key]);
        // The live run is on the TUI carrier, which is what "claude" names.
        let again = call(
            &handler,
            "agent.start",
            json!({ "id": "run-same", "provider": "claude" }),
        );
        assert_eq!(again["ok"], true, "{again:?}");
        assert_eq!(again["result"]["term_id"], wire_id, "{again:?}");
        wait_for_deliveries(&state).await;
        assert_eq!(
            agent_pid(&state.lock().unwrap().tabs[&key]),
            live_pid,
            "the live session is the one the start hands back, not a replacement"
        );
    }

    /// Attaching to an entity's agent finds the tab of the WORKTREE it works
    /// in, streams it, and — when that agent's process ends — retains the last
    /// screen with `live: false` rather than erroring or going blank.
    #[tokio::test]
    async fn agent_attach_streams_a_live_run_and_retains_the_last_screen() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let (tab_key, wire_id) = insert_live_run(&state, &repo, dir.path().join("side"), "run-9");

        let (sender, mut pushes, key) = SessionSender::observable("s1");
        let res = handler.call(
            sender,
            req(
                "agent.attach",
                json!({ "id": "run-9", "cols": 100, "rows": 30 }),
            ),
        );
        assert_eq!(res["ok"], true, "{res:?}");
        assert_eq!(
            res["result"]["term_id"], wire_id,
            "an agent is addressed by its worktree, not by the run that owns it"
        );
        assert_eq!(res["result"]["live"], true);

        let seen = wait_for_pushes(&mut pushes, &key, |seen| {
            output_text(seen, &wire_id).contains("agent-beat")
        })
        .await;
        assert_eq!(seen[0]["type"], "term.reset", "{seen:?}");

        // The agent's process ends → clients hear agent_session_ended and the
        // tab keeps showing the last screen.
        state.lock().unwrap().tabs[&tab_key].session.end();
        wait_for_push(&mut pushes, &key, |p| {
            p["type"] == "term.closed"
                && p["term_id"] == wire_id
                && p["reason"] == "agent_session_ended"
        })
        .await;

        let again = handler.call(
            SessionSender::detached("s2"),
            req("agent.attach", json!({ "id": "run-9" })),
        );
        assert_eq!(again["result"]["live"], false, "{again:?}");
        assert!(
            !b64decode(again["result"]["snapshot"].as_str().unwrap())
                .unwrap()
                .is_empty(),
            "a dead agent still shows what it last painted"
        );
    }

    /// The Agent tab is a fixture on every worktree surface, and most of those
    /// surfaces have no entity to name: an unadopted external worktree and the
    /// project's primary checkout are directories, not runs. So `agent.attach`
    /// takes the same scope shapes `term.create`/`term.list` take, resolves
    /// them server-side, and answers for the tab rooted there — empty when no
    /// agent has run, the live tab once one has.
    #[tokio::test]
    async fn agent_attach_addresses_a_worktree_by_scope_before_any_run_owns_it() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let project_id = state.lock().unwrap().projects[0].id.clone();
        add_external_worktree(&repo, dir.path(), "feature-x", "feature-x");
        let external = state
            .lock()
            .unwrap()
            .scan_external_worktrees_now(&project_id)
            .unwrap()
            .into_iter()
            .find(|w| w.branch.as_deref() == Some("feature-x"))
            .expect("the external worktree is discoverable");

        // Nothing has ever run here: the tab exists as an empty screen, never
        // as an error — mounting it must not spawn anything.
        let empty = handler.call(
            SessionSender::detached("s1"),
            req(
                "agent.attach",
                json!({ "project_id": project_id, "worktree_id": external.id }),
            ),
        );
        assert_eq!(empty["ok"], true, "{empty:?}");
        assert_eq!(empty["result"]["live"], false);
        assert_eq!(
            empty["result"]["term_id"],
            json!(format!("agent:{}", external.id))
        );

        // The primary checkout answers to the project scope alone, the same way
        // its shells do.
        let primary = handler.call(
            SessionSender::detached("s1"),
            req("agent.attach", json!({ "project_id": project_id })),
        );
        assert_eq!(primary["ok"], true, "{primary:?}");
        assert_eq!(primary["result"]["live"], false);
        assert_eq!(
            primary["result"]["term_id"],
            json!(format!(
                "agent:{}",
                crate::worktree::external_worktree_id(&AppState::canonical_root(&repo))
            ))
        );

        // Once an agent runs in that worktree, the same scope reaches the tab
        // itself — one agent, one wire id, whichever shape asked for it.
        let root = AppState::canonical_root(&external.path);
        let (tab, rx) = Tab::spawn(
            TabRole::Agent {
                owner: "run-x".to_string(),
                agent_id: crate::agent::derived_agent_id("run-x"),
                provider: AgentProvider::default(),
            },
            &warm_tui_spec(),
            agent_tab_id(&crate::agent::derived_agent_id("run-x")),
            root.clone(),
            120,
            40,
            None,
        )
        .expect("the agent tab spawns");
        let wire_id = tab.wire_id();
        let key = derived_agent_key(&root, "run-x");
        state.lock().unwrap().tabs.insert(key.clone(), tab);
        spawn_tab_pumps(&state, key.clone(), rx);

        let live = handler.call(
            SessionSender::detached("s2"),
            req(
                "agent.attach",
                json!({ "project_id": project_id, "worktree_id": external.id }),
            ),
        );
        assert_eq!(live["ok"], true, "{live:?}");
        assert_eq!(live["result"]["live"], true);
        assert_eq!(live["result"]["term_id"], json!(wire_id));
    }

    /// An agent that exited leaves a screen and nothing else — and the offer to
    /// start one again leads with the harness that painted it. Only the tab
    /// knows which one that was (the entity's model choice can have moved since,
    /// and most agent-bearing worktrees have no entity at all), so the attach
    /// says it. A worktree nothing has run in names none: there is nothing to
    /// report, and the client leads with its own default instead.
    #[tokio::test]
    async fn agent_attach_names_the_provider_that_painted_the_screen() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let project_id = state.lock().unwrap().projects[0].id.clone();
        let root = AppState::canonical_root(&repo);

        // Nothing has run here yet: no harness to name.
        let empty = handler.call(
            SessionSender::detached("s1"),
            req("agent.attach", json!({ "project_id": project_id })),
        );
        assert_eq!(empty["ok"], true, "{empty:?}");
        assert!(
            empty["result"]["provider"].is_null(),
            "a worktree with no agent tab has no harness to report: {empty:?}"
        );

        // One ran, on codex, and died. The retained screen still answers for it.
        let (tab, rx) = Tab::spawn(
            TabRole::Agent {
                owner: "run-codex".to_string(),
                agent_id: crate::agent::derived_agent_id("run-codex"),
                provider: AgentProvider::Codex,
            },
            &HarnessSpec::new("true"),
            agent_tab_id(&crate::agent::derived_agent_id("run-codex")),
            root.clone(),
            120,
            40,
            None,
        )
        .expect("the agent tab spawns");
        let key = derived_agent_key(&root, "run-codex");
        state.lock().unwrap().tabs.insert(key.clone(), tab);
        spawn_tab_pumps(&state, key.clone(), rx);

        let ran = handler.call(
            SessionSender::detached("s2"),
            req("agent.attach", json!({ "project_id": project_id })),
        );
        assert_eq!(ran["ok"], true, "{ran:?}");
        assert_eq!(
            ran["result"]["provider"], "codex",
            "the retained screen names the harness that painted it: {ran:?}"
        );

        // A user's shell is not an agent, and reports no harness.
        let shell = handler.call(
            SessionSender::detached("s3"),
            req("term.create", json!({ "project_id": project_id })),
        );
        assert_eq!(shell["ok"], true, "{shell:?}");
        let attached = handler.call(
            SessionSender::detached("s3"),
            req(
                "term.attach",
                json!({ "term_id": shell["result"]["term_id"] }),
            ),
        );
        assert!(
            attached["result"]["provider"].is_null(),
            "a login shell runs no harness: {attached:?}"
        );
    }

    /// The Agent tab is a fixture on every worktree surface, so clients mount
    /// it long before anything has ever run there — the state EVERY worktree is
    /// in right after a daemon restart. Such a client is attached to a screen
    /// with no PTY, and when the agent finally starts it must go live WHERE IT
    /// STANDS: the session's first frames reach it without an unmount and
    /// remount. The viewport it attached at is the one the new PTY is sized to,
    /// the same rule a live attach follows.
    #[tokio::test]
    async fn a_client_attached_before_the_first_spawn_streams_the_session_it_waited_for() {
        let (dir, repo) = init_repo();
        let (state, handler, _) = agent_tab_fixture(&repo, dir.path(), "run-waited-for");
        let project_id = state.lock().unwrap().projects[0].id.clone();
        let wire_id = format!(
            "agent:{}",
            crate::worktree::external_worktree_id(&AppState::canonical_root(&repo))
        );

        // Nothing has ever run in the primary checkout: a blank, dead screen.
        let (sender, mut pushes, key) = SessionSender::observable("s1");
        let empty = handler.call(
            sender,
            req(
                "agent.attach",
                json!({ "project_id": project_id, "cols": 100, "rows": 30 }),
            ),
        );
        assert_eq!(empty["ok"], true, "{empty:?}");
        assert_eq!(empty["result"]["live"], false);
        assert_eq!(
            empty["result"]["term_id"],
            json!(wire_id),
            "a worktree with no agent yet answers for itself"
        );
        assert_eq!(
            empty["result"]["cursor"], 0,
            "a screen that has painted nothing starts the cursor at zero"
        );

        // The agent starts later, from a delivery. This client never re-attached.
        let (delivered_to, spawned) = deliver(
            &state,
            &repo,
            "run-waited-for",
            &crate::agent::derived_agent_id("run-waited-for"),
            &ModelChoice::default(),
            "COLD-PROMPT-FOR-A-WAITING-CLIENT",
            "WARM-NUDGE",
        )
        .expect("the delivery spawns the worktree's agent");
        assert_eq!(spawned, Spawned::Fresh);
        // The screen was addressed by the WORKTREE, because there was no agent
        // to name yet; the agent born onto it is addressed by itself, and the
        // opening reset is where the waiting client learns that id.
        assert_eq!(
            delivered_to,
            agent_tab_id(&crate::agent::derived_agent_id("run-waited-for"))
        );

        let seen = wait_for_pushes(&mut pushes, &key, |seen| {
            output_text(seen, &delivered_to).contains("COLD-PROMPT-FOR-A-WAITING-CLIENT")
        })
        .await;
        assert_eq!(
            seen[0]["type"], "term.reset",
            "the waiting client hears the session start: {seen:?}"
        );
        assert_eq!(
            seen[0]["cursor"], 0,
            "the opening reset lands at the cursor the attach handed out — \
             no gap, and the client applies it rather than deduping it away"
        );
        let mut cursor = 0;
        for push in &seen {
            let pushed = push["cursor"].as_u64().expect("every frame carries one");
            assert!(pushed >= cursor, "the cursor never rewinds: {seen:?}");
            cursor = pushed;
        }
        assert!(
            cursor > 0,
            "the session's output moved the cursor: {seen:?}"
        );

        let s = state.lock().unwrap();
        let screen = screen_of(
            &s.tabs[&derived_agent_key(&AppState::canonical_root(&repo), "run-waited-for")],
        );
        assert_eq!(
            screen.size(),
            (100, 30),
            "the spawned agent is sized to the viewport of the client already watching it"
        );
    }

    /// The window inside a respawn: the reservation has taken the dead tab out
    /// of the registry, so a client mounting the Agent tab right then lands on
    /// a waiting screen even though this worktree HAS a retained screen with a
    /// cursor. That client must be carried onto the replacement — but its
    /// screen must not be: the retained cursor is what reconnect dedupes on and
    /// it never rewinds, so the waiting screen contributes its clients and
    /// nothing else.
    #[tokio::test]
    async fn a_client_attaching_inside_a_respawn_is_carried_without_rewinding_the_cursor() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-respawn-race");
        let choice = ModelChoice::default();
        let canonical = AppState::canonical_root(&root);
        let key = derived_agent_key(&canonical, "run-respawn-race");

        // A first session paints, then dies: its screen and cursor are retained.
        deliver(
            &state,
            &root,
            "run-respawn-race",
            &crate::agent::derived_agent_id("run-respawn-race"),
            &choice,
            "FIRST-SESSION",
            "warm",
        )
        .expect("the first delivery spawns");
        wait_for_agent_screen(&state, &root, "FIRST-SESSION").await;
        state.lock().unwrap().tabs[&key].session.end();
        let retained_total = loop {
            {
                let s = state.lock().unwrap();
                let tab = &s.tabs[&key];
                if !tab.live {
                    break screen_of(tab).cursor();
                }
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        };
        assert!(retained_total > 0, "the dead session left a cursor behind");

        // The state a client that attached inside the spawn window is in.
        let (sender, mut pushes, session_key) = SessionSender::observable("late");
        {
            let mut s = state.lock().unwrap();
            let waiting = ScreenHandle::new(&key.tab_id, 90, 25);
            waiting.attach(&sender, None);
            s.agent_screens_awaiting_spawn.insert(key.clone(), waiting);
        }

        let (wire_id, spawned) = deliver(
            &state,
            &root,
            "run-respawn-race",
            &crate::agent::derived_agent_id("run-respawn-race"),
            &choice,
            "SECOND-SESSION",
            "warm",
        )
        .expect("a dead agent is replaced");
        assert_eq!(spawned, Spawned::Fresh, "a dead agent is not an agent");

        let seen = wait_for_pushes(&mut pushes, &session_key, |seen| {
            output_text(seen, &wire_id).contains("SECOND-SESSION")
        })
        .await;
        let opening = seen
            .iter()
            .find(|push| push["type"] == "term.reset")
            .expect("the waiting client hears the new session start");
        assert!(
            opening["cursor"].as_u64().unwrap() >= retained_total,
            "the retained cursor is carried forward, never rewound to the \
             waiting screen's zero: {seen:?}"
        );
    }

    /// Point a fixture's project at a provider running `spec`.
    ///
    /// The program and the carrier are two halves of one launch config — the
    /// provider on the caller's `ModelChoice` is what `Tab::spawn` asks which
    /// carrier to open — so a caller that swaps the spec swaps the choice
    /// beside it, or runs a stream-json child inside a PTY and proves nothing.
    fn a_provider_running(state: &Arc<Mutex<AppState>>, repo: &std::path::Path, spec: HarnessSpec) {
        let mut s = state.lock().unwrap();
        let worktrees = s.worktrees_root.clone();
        let agent = Agent::WarmBuilder(Arc::new(
            move |_prompt: &str, _choice: &ModelChoice, _options: &SpawnOptions| spec.clone(),
        ));
        s.projects[0].orch =
            Orchestrator::new(repo.to_path_buf(), worktrees, agent, Templates::default());
    }

    /// The same, for a carrier with no terminal, handing back the choice that
    /// opens it.
    fn a_headless_provider_running(
        state: &Arc<Mutex<AppState>>,
        repo: &std::path::Path,
        spec: HarnessSpec,
    ) -> ModelChoice {
        a_provider_running(state, repo, spec);
        ModelChoice {
            provider: AgentProvider::ClaudeAdk,
            ..ModelChoice::default()
        }
    }

    /// A spawn with no terminal closes the screens waiting on it.
    ///
    /// Clients that mount the Agent tab before a worktree has an agent are held
    /// on a screen with no PTY, and a spawn carries them onto the real one. A
    /// session with no terminal has no real screen to carry them to, so the
    /// carry would drop them silently and leave them attached to a grid nothing
    /// will ever paint. They are told instead — the way the reaper and
    /// `retire_agent` tell one — and the rail, which reads `has_terminal: false`
    /// off the digest, stops offering the basement they were waiting for.
    #[tokio::test]
    async fn a_headless_spawn_closes_the_screens_that_were_waiting_for_a_terminal() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-headless-wait");
        let choice = a_headless_provider_running(
            &state,
            &repo,
            crate::harness::adk::fake::stream_json_harness(&[crate::harness::adk::fake::RESULT]),
        );
        let agent_id = crate::agent::derived_agent_id("run-headless-wait");
        let key = derived_agent_key(&AppState::canonical_root(&root), "run-headless-wait");

        let (sender, mut pushes, session_key) = SessionSender::observable("waiting");
        {
            let mut s = state.lock().unwrap();
            let waiting = ScreenHandle::new(&key.tab_id, 90, 25);
            waiting.attach(&sender, None);
            s.agent_screens_awaiting_spawn.insert(key.clone(), waiting);
        }

        deliver(
            &state,
            &root,
            "run-headless-wait",
            &agent_id,
            &choice,
            "cold",
            "warm",
        )
        .expect("the headless agent spawns");

        let seen = wait_for_pushes(&mut pushes, &session_key, |seen| {
            seen.iter().any(|push| push["type"] == "term.closed")
        })
        .await;
        let closed = seen
            .iter()
            .find(|push| push["type"] == "term.closed")
            .expect("the waiting client is told, rather than left on a dead grid");
        assert_eq!(closed["term_id"], key.tab_id, "{closed:?}");

        let s = state.lock().unwrap();
        assert!(
            s.agent_screens_awaiting_spawn.is_empty(),
            "and the screen is not left behind for some later spawn to inherit"
        );
        let tab = &s.tabs[&key];
        assert!(
            tab.screen.is_none(),
            "a session with no terminal has no grid, so there is none to hand anyone"
        );
        assert!(
            tab.live,
            "the agent itself is running — it just has no basement"
        );
        s.tabs[&key].session.end();
    }

    /// The same rule for the other screen a spawn can be holding: the grid the
    /// session being replaced left behind.
    ///
    /// A retained screen is carried onto the replacement so the cursor never
    /// rewinds — but a replacement with no terminal has nothing to carry it to,
    /// and a human who changed this agent's provider between the two sessions
    /// would otherwise be left watching the dead one's last frame forever.
    #[tokio::test]
    async fn a_headless_respawn_closes_the_grid_the_terminal_left_behind() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-carrier-swap");
        let agent_id = crate::agent::derived_agent_id("run-carrier-swap");
        let key = derived_agent_key(&AppState::canonical_root(&root), "run-carrier-swap");

        // A terminal session, watched by a client, that then dies.
        deliver(
            &state,
            &root,
            "run-carrier-swap",
            &agent_id,
            &ModelChoice::default(),
            "FIRST-SESSION",
            "warm",
        )
        .expect("the first delivery spawns a PTY");
        wait_for_agent_screen(&state, &root, "FIRST-SESSION").await;
        let (sender, mut pushes, session_key) = SessionSender::observable("watching");
        {
            let s = state.lock().unwrap();
            screen_of(&s.tabs[&key]).attach(&sender, None);
        }
        state.lock().unwrap().tabs[&key].session.end();
        wait_for(Duration::from_secs(5), || {
            (!state.lock().unwrap().tabs[&key].live).then_some(())
        })
        .await
        .expect("the dead session leaves a retained screen behind");

        // The human changed this agent's provider while it was down, so its
        // replacement reports itself instead of painting.
        let choice = a_headless_provider_running(
            &state,
            &repo,
            crate::harness::adk::fake::stream_json_harness(&[crate::harness::adk::fake::RESULT]),
        );
        deliver(
            &state,
            &root,
            "run-carrier-swap",
            &agent_id,
            &choice,
            "SECOND-SESSION",
            "warm",
        )
        .expect("the headless replacement spawns");

        let seen = wait_for_pushes(&mut pushes, &session_key, |seen| {
            seen.iter()
                .any(|push| push["type"] == "term.closed" && push["reason"] == "no_terminal")
        })
        .await;
        assert!(
            seen.iter().any(|push| push["term_id"] == key.tab_id),
            "the client watching the old grid is told which tab closed: {seen:?}"
        );
        let s = state.lock().unwrap();
        assert!(
            s.tabs[&key].screen.is_none(),
            "and the retained grid is not hung on a session that cannot paint it"
        );
        s.tabs[&key].session.end();
    }

    /// A spawn that never opens closes the grid it took.
    ///
    /// The reservation takes the dead session's tab out of the registry and
    /// keeps its screen, deliberately telling the clients on it nothing: they
    /// are about to be handed to the replacement. A replacement that fails to
    /// open — the binary is gone, the harness was reconfigured wrongly — has
    /// nobody to hand them to, and the screen is in no registry for a reaper
    /// or a close to find. So the failure says the words itself, rather than
    /// leaving browsers on a grid nothing will paint and nothing will close.
    #[tokio::test]
    async fn a_spawn_that_fails_closes_the_grid_it_took_from_the_dead_session() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-spawn-fails");
        let agent_id = crate::agent::derived_agent_id("run-spawn-fails");
        let key = derived_agent_key(&AppState::canonical_root(&root), "run-spawn-fails");

        // A terminal session, watched by a client, that then dies.
        deliver(
            &state,
            &root,
            "run-spawn-fails",
            &agent_id,
            &ModelChoice::default(),
            "FIRST-SESSION",
            "warm",
        )
        .expect("the first delivery spawns a PTY");
        wait_for_agent_screen(&state, &root, "FIRST-SESSION").await;
        let (sender, mut pushes, session_key) = SessionSender::observable("watching");
        {
            let s = state.lock().unwrap();
            screen_of(&s.tabs[&key]).attach(&sender, None);
        }
        state.lock().unwrap().tabs[&key].session.end();
        wait_for(Duration::from_secs(5), || {
            (!state.lock().unwrap().tabs[&key].live).then_some(())
        })
        .await
        .expect("the dead session leaves a retained screen behind");

        // The harness this agent is locked to is no longer on the machine.
        a_provider_running(
            &state,
            &repo,
            HarnessSpec::new(dir.path().join("no-such-harness").display().to_string()),
        );
        let refused = deliver(
            &state,
            &root,
            "run-spawn-fails",
            &agent_id,
            &ModelChoice::default(),
            "SECOND-SESSION",
            "warm",
        )
        .expect_err("a harness that is not there cannot be opened");
        assert!(!refused.is_empty(), "and the delivery says why");

        let seen = wait_for_pushes(&mut pushes, &session_key, |seen| {
            seen.iter().any(|push| push["reason"] == SPAWN_NEVER_OPENED)
        })
        .await;
        let closed = seen
            .iter()
            .find(|push| push["reason"] == SPAWN_NEVER_OPENED)
            .expect("the client is told, rather than left on an orphaned grid");
        assert_eq!(closed["type"], "term.closed", "{closed:?}");
        assert_eq!(closed["term_id"], key.tab_id, "{closed:?}");
        assert!(
            !state.lock().unwrap().tabs.contains_key(&key),
            "the failed spawn leaves no tab behind either"
        );
    }

    /// A reservation that cannot be completed takes nothing out of the registry.
    ///
    /// Retiring the dead tab and registering the MCP token are the reservation
    /// giving things up on the registry's behalf, and a failure after either
    /// bypasses the one primitive that gives them back. So every read that can
    /// fail runs first, with the registry untouched: the dead tab keeps its
    /// retained grid and the clients on it, the token the last session held
    /// stands, and a later spawn can still replace both.
    #[tokio::test]
    async fn a_reservation_that_cannot_resolve_its_project_takes_nothing_from_the_registry() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-unresolvable");
        let agent_id = crate::agent::derived_agent_id("run-unresolvable");
        let key = derived_agent_key(&AppState::canonical_root(&root), "run-unresolvable");

        deliver(
            &state,
            &root,
            "run-unresolvable",
            &agent_id,
            &ModelChoice::default(),
            "FIRST-SESSION",
            "warm",
        )
        .expect("the first delivery spawns a PTY");
        wait_for_agent_screen(&state, &root, "FIRST-SESSION").await;
        state.lock().unwrap().tabs[&key].session.end();
        wait_for(Duration::from_secs(5), || {
            (!state.lock().unwrap().tabs[&key].live).then_some(())
        })
        .await
        .expect("the dead session leaves a retained screen behind");
        let (sender, mut pushes, session_key) = SessionSender::observable("watching");
        let token_before = {
            let s = state.lock().unwrap();
            screen_of(&s.tabs[&key]).attach(&sender, None);
            s.mcp_session_tokens[&agent_id].clone()
        };

        // The owner's project binding is gone, so the reservation cannot say
        // which orchestrator builds the harness.
        state
            .lock()
            .unwrap()
            .entity_project
            .remove("run-unresolvable");
        let refused = deliver(
            &state,
            &root,
            "run-unresolvable",
            &agent_id,
            &ModelChoice::default(),
            "SECOND-SESSION",
            "warm",
        )
        .expect_err("an owner with no project cannot be spawned for");
        assert!(refused.contains("unknown entity id"), "{refused}");

        let s = state.lock().unwrap();
        let dead = s
            .tabs
            .get(&key)
            .expect("the dead tab is still in the registry");
        assert!(
            dead.screen.is_some(),
            "and still holds the grid its clients are attached to"
        );
        assert_eq!(
            s.mcp_session_tokens[&agent_id], token_before,
            "no token was registered for a child that never existed"
        );
        assert!(
            s.agent_spawns_in_flight.is_empty(),
            "no claim was left behind"
        );
        drop(s);
        let mut seen = Vec::new();
        while let Ok(message) = pushes.try_recv() {
            seen.push(SessionSender::decrypt_push(&session_key, &message));
        }
        assert!(
            !seen.iter().any(|push| push["type"] == "term.closed"),
            "the attached client was told nothing, because nothing changed: {seen:?}"
        );
    }

    /// A client can be waiting on the Agent tab of a worktree that is then
    /// deleted out from under it. The reaper closes the tabs of a vanished
    /// worktree; the screen its agent was going to be born onto is the same
    /// thing one step earlier, so it goes the same way — the client hears
    /// `reaped` instead of waiting forever on a directory that is gone, and no
    /// future spawn inherits it.
    #[test]
    fn the_reaper_drops_an_agent_screen_whose_worktree_vanished_before_a_spawn() {
        let (dir, repo) = init_repo();
        let (state, _handler) = shared_state_and_handler(&repo, dir.path());
        let vanishing = dir.path().join("vanishing");
        std::fs::create_dir_all(&vanishing).unwrap();
        let root = AppState::canonical_root(&vanishing);
        let key = derived_agent_key(&root, "run-vanishing");
        let wire_id = key.tab_id.clone();

        let (sender, mut pushes, session_key) = SessionSender::observable("s1");
        {
            let mut s = state.lock().unwrap();
            let waiting = ScreenHandle::new(&key.tab_id, 80, 24);
            waiting.attach(&sender, None);
            s.agent_screens_awaiting_spawn.insert(key, waiting);
        }
        std::fs::remove_dir_all(&vanishing).unwrap();

        let reaped = state.lock().unwrap().reap_orphaned_terminals();
        assert_eq!(reaped, vec![wire_id.clone()]);
        assert!(
            state
                .lock()
                .unwrap()
                .agent_screens_awaiting_spawn
                .is_empty(),
            "a screen for a directory that is gone is never handed to a future spawn"
        );
        let closed = SessionSender::decrypt_push(
            &session_key,
            &pushes.try_recv().expect("the client hears its tab is gone"),
        );
        assert_eq!(closed["type"], "term.closed", "{closed:?}");
        assert_eq!(closed["term_id"], wire_id);
        assert_eq!(closed["reason"], "reaped");
    }

    /// A human can close the browser while waiting on the Agent tab of a
    /// worktree whose agent has not started yet. `drop_session` detaches an
    /// ended session from every tab so the pumps stop encrypting frames into a
    /// session the relay will only drop — and a screen waiting for its first
    /// spawn is a tab one step early, so it goes the same way. Otherwise the
    /// spawn that finally comes carries a dead client onto the real screen and
    /// pushes to it for the life of the tab, and sizes the new PTY to a
    /// viewport nobody is looking at.
    #[tokio::test]
    async fn a_session_that_ended_while_waiting_is_not_carried_onto_the_agent() {
        let (dir, repo) = init_repo();
        let (state, handler, _) = agent_tab_fixture(&repo, dir.path(), "run-closed-client");
        let project_id = state.lock().unwrap().projects[0].id.clone();

        let (sender, _pushes, _key) = SessionSender::observable("closing");
        let waiting = handler.call(
            sender,
            req(
                "agent.attach",
                json!({ "project_id": project_id, "cols": 90, "rows": 25 }),
            ),
        );
        assert_eq!(waiting["ok"], true, "{waiting:?}");
        assert_eq!(waiting["result"]["live"], false, "nothing runs here yet");

        state.lock().unwrap().drop_session("closing");
        assert!(
            state
                .lock()
                .unwrap()
                .agent_screens_awaiting_spawn
                .values()
                .all(|screen| screen.attached() == 0),
            "an ended session is detached from the screen it was waiting on"
        );

        deliver(
            &state,
            &repo,
            "run-closed-client",
            &crate::agent::derived_agent_id("run-closed-client"),
            &ModelChoice::default(),
            "COLD-PROMPT",
            "WARM-NUDGE",
        )
        .expect("the delivery spawns the worktree's agent");

        let s = state.lock().unwrap();
        let tab =
            &s.tabs[&derived_agent_key(&AppState::canonical_root(&repo), "run-closed-client")];
        assert!(
            screen_of(tab).attached() == 0,
            "a session that ended is never carried onto the agent it waited for"
        );
        assert_eq!(
            screen_of(tab).size(),
            (120, 40),
            "with nobody left waiting, the spawn keeps the size Build chose"
        );
    }

    /// An attach clones the waiting screen under the app mutex and registers
    /// on it with the mutex released, so the last client already on that
    /// screen can leave in between. The screen must still be the one the spawn
    /// carries from: dropped from the registry the moment it emptied, the
    /// client arriving on it would be on a screen nothing feeds and nothing
    /// closes, blank for the life of the tab.
    #[tokio::test]
    async fn a_client_attaching_as_the_last_waiting_client_leaves_is_carried_onto_the_agent() {
        let (dir, repo) = init_repo();
        let (state, handler, _) = agent_tab_fixture(&repo, dir.path(), "run-attach-race");
        let project_id = state.lock().unwrap().projects[0].id.clone();

        let (leaving, _pushes, _key) = SessionSender::observable("leaving");
        let waiting = handler.call(
            leaving,
            req(
                "agent.attach",
                json!({ "project_id": project_id, "cols": 90, "rows": 25 }),
            ),
        );
        assert_eq!(waiting["ok"], true, "{waiting:?}");

        // What a second attach, already past the app mutex, is holding.
        let in_flight = state
            .lock()
            .unwrap()
            .agent_screens_awaiting_spawn
            .values()
            .next()
            .expect("the first attach left a screen waiting for the spawn")
            .clone();
        state.lock().unwrap().drop_session("leaving");
        let (arriving, mut pushes, session_key) = SessionSender::observable("arriving");
        in_flight.attach(&arriving, Some((90, 25)));

        let (wire_id, _) = deliver(
            &state,
            &repo,
            "run-attach-race",
            &crate::agent::derived_agent_id("run-attach-race"),
            &ModelChoice::default(),
            "COLD-PROMPT",
            "WARM-NUDGE",
        )
        .expect("the delivery spawns the worktree's agent");

        let key = derived_agent_key(&AppState::canonical_root(&repo), "run-attach-race");
        {
            let s = state.lock().unwrap();
            let screen = screen_of(&s.tabs[&key]);
            assert_eq!(
                screen.attached_sessions(),
                vec!["arriving".to_string()],
                "the client that arrived as the last one left is on the agent's screen"
            );
            assert_eq!(
                screen.size(),
                (90, 25),
                "at the viewport it is rendering at"
            );
        }
        wait_for_push(&mut pushes, &session_key, |push| {
            push["type"] == "term.reset" && push["term_id"] == wire_id
        })
        .await;
        state.lock().unwrap().tabs[&key].session.end();
    }

    #[tokio::test]
    async fn keyed_run_terminal_roundtrips() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        insert_live_run(&state, &repo, dir.path().join("side"), "run-7");

        let created = handler.call(
            SessionSender::detached("s1"),
            req("term.create", json!({ "run_id": "run-7" })),
        );
        assert_eq!(created["ok"], true, "{created:?}");
        let term_id = created["result"]["term_id"].as_str().unwrap().to_string();

        let (sender, mut pushes, key) = SessionSender::observable("s1");
        let attached = handler.call(sender, req("term.attach", json!({ "term_id": term_id })));
        assert_eq!(attached["ok"], true, "{attached:?}");

        handler.call(
            SessionSender::detached("s1"),
            req(
                "term.input",
                json!({ "term_id": term_id, "data": b64encode(b"echo hi-there\n") }),
            ),
        );
        wait_for_push(&mut pushes, &key, |p| {
            p["type"] == "term.output"
                && output_text(std::slice::from_ref(p), &term_id).contains("hi-there")
        })
        .await;

        let listed = handler.call(
            SessionSender::detached("s1"),
            req("term.list", json!({ "run_id": "run-7" })),
        );
        assert!(!listed["result"]["terminals"].as_array().unwrap().is_empty());
    }

    #[test]
    fn term_scope_parses_run_project_and_external() {
        assert!(matches!(
            TermScope::parse(&json!({ "run_id": "run-1" })).unwrap(),
            TermScope::Run { .. }
        ));
        assert!(matches!(
            TermScope::parse(&json!({ "project_id": "proj-1" })).unwrap(),
            TermScope::Primary { .. }
        ));
        assert!(matches!(
            TermScope::parse(&json!({ "project_id": "proj-1", "worktree_id": "w" })).unwrap(),
            TermScope::ExternalWorktree { .. }
        ));
        assert!(TermScope::parse(&json!({})).is_err());
    }

    // ---- git scope keyed on a run --------------------------------------------

    #[test]
    fn git_status_and_commit_scope_to_a_run() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let (_, run_id) = planned_run_in_review(&mut state, "git me");
        // The run's build wrote result.txt (committed by QA merge path? no — it
        // is committed on review); git.status over the run scope succeeds.
        let status = state.handle(req("git.status", json!({ "run_id": run_id })));
        assert_eq!(status["ok"], true, "{status:?}");
        // Exactly-one-scope is enforced.
        let both = state.handle(req(
            "git.status",
            json!({ "run_id": run_id, "project_id": "proj-1" }),
        ));
        assert_eq!(both["ok"], false, "{both:?}");
    }

    // ---- git scope keyed on an external worktree ------------------------------

    /// Mint an unbound worktree and hand back (project_id, worktree_id, path).
    fn bare_worktree(state: &mut AppState, name: &str) -> (String, String, PathBuf) {
        let project_id = state.projects[0].id.clone();
        let created = state.handle(req(
            "worktree.create",
            json!({ "project_id": project_id, "name": name }),
        ));
        assert_eq!(created["ok"], true, "{created:?}");
        let result = &created["result"];
        (
            project_id,
            result["worktree_id"].as_str().unwrap().to_string(),
            PathBuf::from(result["path"].as_str().unwrap()),
        )
    }

    /// The whole git GUI — status, staging, commit, history — works on a
    /// worktree the same way it does on the primary checkout, and reads the
    /// worktree's own tree rather than the project's.
    #[test]
    fn the_git_gui_scopes_to_an_external_worktree() {
        let (dir, repo) = init_repo();
        let mut state = git_gui_state(&dir, &repo);
        let (project_id, worktree_id, path) = bare_worktree(&mut state, "scratch");
        let scope = json!({ "project_id": project_id, "worktree_id": worktree_id });
        std::fs::write(path.join("only-here.txt"), "in the worktree\n").unwrap();

        let status = state.handle(req("git.status", scope.clone()));
        assert_eq!(status["ok"], true, "{status:?}");
        assert!(has_file_entry(&status["result"], "only-here.txt"));
        assert_eq!(status["result"]["branch"], json!("build/scratch"));

        // The project's own checkout is untouched by any of it.
        let primary = state.handle(req("git.status", json!({ "project_id": project_id })));
        assert!(!has_file_entry(&primary["result"], "only-here.txt"));

        let staged = state.handle(req(
            "git.stage",
            json!({ "project_id": project_id, "worktree_id": worktree_id, "paths": ["only-here.txt"] }),
        ));
        assert_eq!(staged["ok"], true, "{staged:?}");
        let committed = state.handle(req(
            "git.commit",
            json!({ "project_id": project_id, "worktree_id": worktree_id, "message": "in the worktree" }),
        ));
        assert_eq!(committed["ok"], true, "{committed:?}");

        // History is the worktree's, and the new commit is marked ahead of the
        // base branch — the same affordance a run's history carries.
        let log = state.handle(req("git.log", scope.clone()));
        let commits = log["result"]["commits"].as_array().unwrap();
        assert_eq!(commits[0]["subject"], json!("in the worktree"));
        assert_eq!(commits[0]["ahead_of_base"], json!(true));
        assert_eq!(commits[1]["ahead_of_base"], json!(false));

        // And the rail sees the commit without waiting out the scan cache.
        let listed = state.external_worktrees(&project_id).worktrees;
        let entry = listed.iter().find(|w| w.id == worktree_id).unwrap();
        assert_eq!(entry.unpushed, Some(1));
        assert_eq!(entry.uncommitted.files_changed, 0, "committed, so clean");
    }

    /// Branch operations name a checkout, and a worktree scope means THAT
    /// worktree — never the project's primary checkout standing in for it.
    #[test]
    fn branch_operations_switch_the_worktree_they_are_scoped_to() {
        let (dir, repo) = init_repo();
        let mut state = git_gui_state(&dir, &repo);
        let (project_id, worktree_id, path) = bare_worktree(&mut state, "scratch");

        let checked_out = state.handle(req(
            "git.checkout",
            json!({ "project_id": project_id, "worktree_id": worktree_id, "branch": "side-quest", "create": true }),
        ));
        assert_eq!(checked_out["ok"], true, "{checked_out:?}");
        assert_eq!(checked_out["result"]["branch"], json!("side-quest"));

        // The worktree moved; the project's checkout stayed on main.
        let head = std::process::Command::new("git")
            .args(["rev-parse", "--abbrev-ref", "HEAD"])
            .current_dir(&path)
            .output()
            .unwrap();
        assert_eq!(String::from_utf8_lossy(&head.stdout).trim(), "side-quest");
        let primary = state.handle(req("git.status", json!({ "project_id": project_id })));
        assert_eq!(primary["result"]["branch"], json!("main"));
    }

    /// The rail's worktree affordance (the FAB's smaller sibling): mint a
    /// worktree with NO run, no agent and no session — a directory the human
    /// then opens a terminal or an agent tab in. It is unbound, so the scan
    /// reports it exactly like a worktree made by hand, and the usual
    /// adopt-on-first-mutation path still applies.
    #[test]
    fn worktree_create_mints_an_unbound_worktree_the_scan_can_see() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let project_id = state.projects[0].id.clone();

        let created = state.handle(req(
            "worktree.create",
            json!({ "project_id": project_id, "name": "scratch" }),
        ));
        assert_eq!(created["ok"], true, "{created:?}");
        let result = &created["result"];
        let worktree_id = result["worktree_id"].as_str().unwrap().to_string();
        assert!(
            result["branch"].as_str().unwrap().starts_with("build/"),
            "{result:?}"
        );
        assert!(std::path::Path::new(result["path"].as_str().unwrap()).is_dir());
        assert_eq!(result["project_id"], json!(project_id));

        // Nothing was dispatched: no run, no session, no task lifecycle.
        assert!(state.runs.is_empty(), "a bare worktree is not a run");

        // The scan sees it under the id the create returned, so the client can
        // navigate straight to its surface.
        let listed = state.scan_external_worktrees_now(&project_id).unwrap();
        assert!(
            listed.iter().any(|w| w.id == worktree_id),
            "{worktree_id} missing from {listed:?}"
        );

        // A second one does not collide with the first.
        let second = state.handle(req(
            "worktree.create",
            json!({ "project_id": project_id, "name": "scratch" }),
        ));
        assert_eq!(second["ok"], true, "{second:?}");
        assert_ne!(second["result"]["branch"], result["branch"]);
        assert_ne!(second["result"]["worktree_id"], result["worktree_id"]);
    }

    /// The name the human typed decides the directory and the branch, through the
    /// same slugifier every other branch name goes through — it is UNTRUSTED text
    /// on its way to a path and a `git` argv.
    #[test]
    fn worktree_create_names_the_branch_after_the_name() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let project_id = state.projects[0].id.clone();

        let created = state.handle(req(
            "worktree.create",
            json!({ "project_id": project_id, "name": "Mascot Model Spike!" }),
        ));
        assert_eq!(created["ok"], true, "{created:?}");
        assert_eq!(created["result"]["branch"], "build/mascot-model-spike");
        assert!(created["result"]["path"]
            .as_str()
            .unwrap()
            .ends_with("mascot-model-spike"));

        // The same name twice cannot collide on disk or on a ref.
        let again = state.handle(req(
            "worktree.create",
            json!({ "project_id": project_id, "name": "Mascot Model Spike!" }),
        ));
        assert_eq!(again["ok"], true, "{again:?}");
        assert_ne!(again["result"]["branch"], created["result"]["branch"]);
    }

    /// A name that slugifies to nothing would silently become some fallback word,
    /// so it is refused instead — the human named it, and the name has to survive.
    #[test]
    fn worktree_create_requires_a_usable_name() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let project_id = state.projects[0].id.clone();

        for name in ["", "   ", "***", "!!!"] {
            let res = state.handle(req(
                "worktree.create",
                json!({ "project_id": project_id, "name": name }),
            ));
            assert_eq!(res["ok"], false, "{name:?} -> {res:?}");
        }
        assert!(
            state.handle(req("worktree.create", json!({ "project_id": project_id })))["ok"]
                == false
        );
    }

    #[test]
    fn worktree_create_rejects_an_unknown_project() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let res = state.handle(req(
            "worktree.create",
            json!({ "project_id": "proj-nope", "name": "scratch" }),
        ));
        assert_eq!(res["ok"], false, "{res:?}");
    }

    /// The rail shows a project's checkout as its branch plus its git status, so
    /// the summary has to carry the sync counts too — not only the working-tree
    /// diffstat. No upstream means no counts, which is a different thing from
    /// "level with upstream" and is reported as such.
    #[test]
    fn primary_changes_carries_ahead_behind_beside_the_diffstat() {
        let (dir, repo, origin) = init_repo_with_origin();
        let mut state = qa_state(&repo, dir.path());

        // A local commit that origin has not seen: ahead 1, behind 0.
        std::fs::write(repo.join("ahead.txt"), "local\n").unwrap();
        git_in_dir(&repo, &["add", "."]);
        git_in_dir(&repo, &["commit", "-m", "local only"]);
        // …and an uncommitted edit, so both halves are non-zero at once.
        std::fs::write(repo.join("dirty.txt"), "wip\n").unwrap();

        let board = state.handle(req("board.list", json!({})));
        let entry = board["result"]["primary_changes"]
            .as_array()
            .unwrap()
            .iter()
            .find(|e| e["branch"] == "main")
            .cloned()
            .unwrap_or_else(|| panic!("no primary entry: {board:?}"));
        assert_eq!(entry["ahead"], 1, "{entry:?}");
        assert_eq!(entry["behind"], 0, "{entry:?}");
        assert!(entry["files_changed"].as_u64().unwrap() >= 1, "{entry:?}");
        let _ = origin;
    }

    #[test]
    fn primary_changes_compares_an_untracked_branch_with_local_main() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        git_in_dir(&repo, &["checkout", "-b", "topic"]);
        std::fs::write(repo.join("topic.txt"), "topic\n").unwrap();
        git_in_dir(&repo, &["add", "."]);
        git_in_dir(&repo, &["commit", "-m", "topic"]);

        let board = state.handle(req("board.list", json!({})));
        let entry = board["result"]["primary_changes"]
            .as_array()
            .unwrap()
            .iter()
            .find(|entry| entry["branch"] == "topic")
            .unwrap_or_else(|| panic!("no topic entry: {board:?}"));
        assert!(entry["upstream"].is_null(), "{entry:?}");
        assert_eq!(entry["comparison_ref"], "main", "{entry:?}");
        assert_eq!(entry["ahead"], 1, "{entry:?}");
        assert_eq!(entry["behind"], 0, "{entry:?}");
    }

    // ---- attention: what the rail orders and colours itself by ---------------

    fn board_entry(state: &mut AppState, id: &str) -> Value {
        let board = state.handle(req("board.list", json!({})));
        for key in ["runs", "plans", "external_worktrees"] {
            if let Some(list) = board["result"][key].as_array() {
                for entry in list {
                    let entry_id = entry["run_id"]
                        .as_str()
                        .or_else(|| entry["plan_id"].as_str())
                        .or_else(|| entry["worktree_id"].as_str());
                    if entry_id == Some(id) {
                        return entry.clone();
                    }
                }
            }
        }
        panic!("{id} not on the board: {board:?}");
    }

    fn attention_of(state: &mut AppState, id: &str) -> Value {
        board_entry(state, id)["attention"].clone()
    }

    /// Append one item to the conversation an Issue and its implementation
    /// share, the way an agent or a lifecycle step would.
    fn push_to_issue_conversation(
        state: &mut AppState,
        issue_id: &str,
        write: impl FnOnce(&mut crate::thread::Thread),
    ) {
        let issue = state.plans.get_mut(issue_id).expect("the issue exists");
        write(issue.agents.sole_thread_mut());
    }

    /// The whole unread rule in one pass: an agent handing back makes the entry
    /// unread and says why, `entity.seen` reads the conversation through, and
    /// the work happening afterwards updates the entry silently.
    #[test]
    fn unread_follows_attention_events_and_entity_seen_clears_it() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let (issue_id, run_id) = planned_run_in_review(&mut state, "unread");

        // An agent that reported done has handed back, and nobody has looked.
        let entry = board_entry(&mut state, &run_id);
        assert_eq!(entry["unread"], true, "{entry:?}");
        assert_eq!(entry["needs_attention"], true, "{entry:?}");
        assert!(entry["unread_count"].as_u64().unwrap() >= 1, "{entry:?}");

        let seen = state.handle(req("entity.seen", json!({ "entity_id": run_id })));
        assert_eq!(seen["ok"], true, "{seen:?}");
        let entry = board_entry(&mut state, &run_id);
        assert_eq!(entry["unread"], false, "{entry:?}");
        assert_eq!(entry["unread_count"], 0, "{entry:?}");
        assert!(entry["unread_reason"].is_null(), "{entry:?}");
        assert_eq!(entry["needs_attention"], false, "{entry:?}");

        // The work carrying on is not news.
        push_to_issue_conversation(&mut state, &issue_id, |thread| {
            thread.push_event(
                crate::thread::ThreadEventKind::Committed,
                Some("Committed 3 files".to_string()),
                None,
                None,
                now_rfc3339(),
            );
            thread.push_event(
                crate::thread::ThreadEventKind::RevisionCreated,
                None,
                None,
                None,
                now_rfc3339(),
            );
        });
        let entry = board_entry(&mut state, &run_id);
        assert_eq!(
            entry["unread"], false,
            "status events stay quiet: {entry:?}"
        );

        // The agent handing back is, and the entry says which handoff it was.
        push_to_issue_conversation(&mut state, &issue_id, |thread| {
            thread.push_event(
                crate::thread::ThreadEventKind::Done,
                Some("Implemented the change".to_string()),
                None,
                None,
                now_rfc3339(),
            );
        });
        let entry = board_entry(&mut state, &run_id);
        assert_eq!(entry["unread"], true, "{entry:?}");
        assert_eq!(entry["unread_count"], 1, "{entry:?}");
        assert_eq!(entry["unread_reason"], "done", "{entry:?}");

        // The newest one is what it says, and they accumulate.
        push_to_issue_conversation(&mut state, &issue_id, |thread| {
            thread.post_agent("which name did you want?", None, now_rfc3339());
        });
        let entry = board_entry(&mut state, &run_id);
        assert_eq!(entry["unread_count"], 2, "{entry:?}");
        assert_eq!(entry["unread_reason"], "agent_message", "{entry:?}");
    }

    /// The reviewer's own messages are not news to the reviewer, and a progress
    /// note is the agent saying it is still going — neither pulls anyone in.
    #[test]
    fn a_reviewers_own_message_and_an_agents_progress_note_leave_the_entry_read() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let (issue_id, run_id) = planned_run_in_review(&mut state, "quiet posts");
        state.handle(req("entity.seen", json!({ "entity_id": run_id })));

        let posted = state.handle(req(
            "thread.post",
            json!({ "entity_id": run_id, "body": "please rename the helper" }),
        ));
        assert_eq!(posted["ok"], true, "{posted:?}");
        push_to_issue_conversation(&mut state, &issue_id, |thread| {
            thread.post_agent_progress("still digging", None, now_rfc3339());
        });

        let entry = board_entry(&mut state, &run_id);
        assert_eq!(entry["unread"], false, "{entry:?}");
        assert!(entry["unread_reason"].is_null(), "{entry:?}");
    }

    /// What reaches the Issue from its implementation: the outcomes, never the
    /// progress. The rule is the event class, over every kind there is — so a
    /// kind added later cannot quietly start (or stop) travelling.
    #[test]
    fn only_a_runs_attention_outcomes_reach_the_issue_that_owns_it() {
        for event in crate::thread::ThreadEventKind::ALL {
            assert_eq!(
                run_outcome_mirrors_to_issue(event),
                event.class() == crate::thread::EventClass::Attention,
                "{event:?}"
            );
        }
        for outcome in [
            crate::thread::ThreadEventKind::Done,
            crate::thread::ThreadEventKind::Blocked,
            crate::thread::ThreadEventKind::RunFailed,
            crate::thread::ThreadEventKind::Merged,
            crate::thread::ThreadEventKind::Abandoned,
        ] {
            assert!(run_outcome_mirrors_to_issue(outcome), "{outcome:?}");
        }
        for progress in [
            crate::thread::ThreadEventKind::RunStarted,
            crate::thread::ThreadEventKind::Committed,
            crate::thread::ThreadEventKind::Pushed,
            crate::thread::ThreadEventKind::RevisionCreated,
            crate::thread::ThreadEventKind::StageStarted,
        ] {
            assert!(!run_outcome_mirrors_to_issue(progress), "{progress:?}");
        }
    }

    /// The Issue is where a planned implementation's outcomes have always
    /// landed, and they still land there — as the agent's own message now,
    /// needing the human exactly once and saying which outcome it was.
    #[test]
    fn a_reported_outcome_is_news_on_the_issue_that_owns_the_implementation() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let (issue_id, run_id) = planned_run_in_review(&mut state, "outcome on the issue");
        let seen = state.handle(req("entity.seen", json!({ "entity_id": run_id })));
        assert_eq!(seen["ok"], true, "{seen:?}");

        state.on_agent_done(
            &run_id,
            DoneReport {
                phase: DonePhase::Build,
                status: DoneStatus::Blocked,
                summary: "Needs production credentials".into(),
                outputs: DoneOutputs::default(),
            },
        );

        let issue_thread = &state.plans[&issue_id].agents.sole_thread();
        let outcomes: Vec<&crate::thread::ThreadMessage> = issue_thread
            .items
            .iter()
            .filter_map(|item| match item {
                crate::thread::ThreadItem::Message(message) if message.outcome.is_some() => {
                    Some(message)
                }
                _ => None,
            })
            .collect();
        assert_eq!(
            outcomes.len(),
            1,
            "one report, one record: {:?}",
            issue_thread.items
        );
        assert_eq!(
            outcomes[0].outcome,
            Some(crate::thread::MessageOutcome::Blocked)
        );
        assert_eq!(outcomes[0].body, "Needs production credentials");
        let packet = issue_thread.catch_up_markdown(40);
        assert!(
            packet.contains("- agent [blocked]: Needs production credentials"),
            "the packet says why the predecessor stopped: {packet}"
        );

        let entry = board_entry(&mut state, &run_id);
        assert_eq!(entry["unread"], true, "{entry:?}");
        assert_eq!(entry["unread_reason"], "blocked", "{entry:?}");
    }

    /// An issue whose conversation is buried under a session's worth of
    /// activity, booted again: the tail the daemon reads holds nothing but
    /// tool calls, so the packet has to come from the store or the replacement
    /// agent is handed nothing at all.
    fn issue_buried_in_activity(state: &mut AppState, goal: &str, said: &str) -> String {
        let issue_id = plan_id_of(&state.handle(req(
            "issue.create",
            json!({ "goal": goal, "dispatch": false }),
        )));
        let agent_id = primary_agent_id(state, &issue_id);
        state
            .edit_agent_conversation(&issue_id, &agent_id, |thread, _| {
                thread.post_user(said, None, "2026-08-29T09:00:00Z");
                for index in 0..crate::store::RESIDENT_CONVERSATION_TAIL + 40 {
                    thread.push_event(
                        crate::thread::ThreadEventKind::ToolUse,
                        Some(format!("Read file-{index}.rs")),
                        None,
                        None,
                        "2026-08-29T09:01:00Z",
                    );
                }
                Ok(())
            })
            .expect("the conversation is written");
        issue_id
    }

    /// §6.3's first failure. A conversation is loaded as its newest 200 items,
    /// and one session emits hundreds of tool calls — so the agent that boots
    /// onto that tail is exactly the one whose messages-only packet finds no
    /// messages in it. The words come out of the store instead.
    #[test]
    fn a_starved_tail_hands_a_resumed_agent_the_words_from_the_store() {
        let (dir, repo) = init_repo();
        let issue_id = {
            let mut state = qa_state(&repo, dir.path());
            issue_buried_in_activity(
                &mut state,
                "fix the login redirect",
                "the redirect drops the query string",
            )
        };

        let state = qa_state(&repo, dir.path());
        let thread = state
            .agent_conversation(&issue_id, None)
            .expect("the issue's conversation");
        assert!(
            thread
                .items
                .iter()
                .all(|item| matches!(item, crate::thread::ThreadItem::Event(_))),
            "the fixture did not starve the tail: {:?}",
            thread.items.first()
        );
        assert_eq!(
            thread.catch_up_markdown(crate::orchestrator::CATCH_UP_MESSAGES),
            "",
            "the tail alone is the empty packet this fixes"
        );

        let packet = state.catch_up_packet(thread, crate::orchestrator::CATCH_UP_MESSAGES);
        assert_eq!(
            packet, "- user: fix the login redirect\n- user: the redirect drops the query string",
            "the packet reads the store when the tail holds no conversation"
        );
    }

    /// Where the packet is composed: at the door every cold prompt passes, not
    /// where the turn was built. A queued turn carries the prompt and the
    /// protocol; the conversation is added when it is handed over — which is
    /// also why a message posted while the turn waited for the lock is in it.
    #[test]
    fn the_catch_up_packet_is_composed_when_the_turn_is_delivered() {
        let (dir, repo) = init_repo();
        let issue_id = {
            let mut state = qa_state(&repo, dir.path());
            issue_buried_in_activity(&mut state, "fix the redirect", "keep the query string")
        };
        let mut state = qa_state(&repo, dir.path());

        let posted = state.handle(req(
            "thread.post",
            json!({ "entity_id": issue_id, "body": "start with the router" }),
        ));
        assert_eq!(posted["ok"], true, "{posted:?}");
        let queued = state
            .pending_agent_turns
            .last()
            .expect("the message queued a turn");
        assert!(
            queued.wants_catch_up,
            "a cold prompt wants the conversation"
        );
        assert!(
            !queued.said().cold.contains("Catch-up packet"),
            "the packet is not baked in at queue time: {}",
            queued.said().cold
        );

        let delivered =
            state.cold_prompt_with_catch_up(&queued.owner, &queued.agent_id, &queued.said().cold);
        assert!(
            delivered.contains("Catch-up packet from the durable conversation"),
            "{delivered}"
        );
        assert!(
            delivered.contains("- user: keep the query string"),
            "the words under the tail travel with the turn: {delivered}"
        );
        assert!(
            delivered.contains("- user: start with the router"),
            "so do the words posted while it waited: {delivered}"
        );
        assert!(
            delivered.contains("Build conversation protocol"),
            "the protocol block is still the prompt's own: {delivered}"
        );
    }

    /// §6.3's second failure, over the wire. A reviewer opening a conversation
    /// mid-session used to be handed sixty tool calls with the last thing
    /// anyone said somewhere below them. The page's limit buys conversation
    /// now — and `has_more` / `oldest_sequence` still mean exactly what a
    /// client walking back by sequence needs them to mean, across the seam
    /// between the resident tail and the history under it.
    #[test]
    fn a_page_over_an_activity_heavy_conversation_still_shows_what_was_said() {
        let (dir, repo) = init_repo();
        let issue_id = {
            let mut state = qa_state(&repo, dir.path());
            let issue_id = plan_id_of(&state.handle(req(
                "issue.create",
                json!({ "goal": "trim the retry loop", "dispatch": false }),
            )));
            let agent_id = primary_agent_id(&state, &issue_id);
            state
                .edit_agent_conversation(&issue_id, &agent_id, |thread, _| {
                    for turn in 0..40 {
                        thread.post_user(format!("ask {turn}"), None, "2026-08-29T09:00:00Z");
                        for index in 0..6 {
                            thread.push_event(
                                crate::thread::ThreadEventKind::ToolUse,
                                Some(format!("Read file-{turn}-{index}.rs")),
                                None,
                                None,
                                "2026-08-29T09:01:00Z",
                            );
                        }
                    }
                    Ok(())
                })
                .expect("the conversation is written");
            issue_id
        };
        let mut state = qa_state(&repo, dir.path());
        let held = state
            .agent_conversation(&issue_id, None)
            .expect("the conversation")
            .total_item_count();
        assert!(
            held > crate::store::RESIDENT_CONVERSATION_TAIL as u64,
            "the fixture has to reach under the tail: {held}"
        );

        let first = state.handle(req(
            "thread.page",
            json!({ "entity_id": issue_id, "limit": 5 }),
        ));
        let page = &first["result"];
        let said: Vec<&str> = page["items"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|item| item["type"] == "message")
            .map(|item| item["data"]["body"].as_str().unwrap())
            .collect();
        assert_eq!(
            said.len(),
            5,
            "the page a reviewer opens on is five turns of conversation: {said:?}"
        );
        assert_eq!(said.last(), Some(&"ask 39"), "{said:?}");

        // And the walk back is whole: every item exactly once, in order, over
        // the seam between the tail and the stored history under it.
        let mut walked: Vec<u64> = Vec::new();
        let mut before: Option<u64> = None;
        loop {
            let mut params = json!({ "entity_id": issue_id, "limit": 5 });
            if let Some(seek) = before {
                params["before_sequence"] = json!(seek);
            }
            let answer = state.handle(req("thread.page", params));
            let page = &answer["result"];
            let shipped: Vec<u64> = page["items"]
                .as_array()
                .unwrap()
                .iter()
                .map(|item| item["data"]["sequence"].as_u64().unwrap())
                .collect();
            assert!(
                !shipped.is_empty(),
                "an empty page below {before:?}: {page}"
            );
            assert_eq!(
                page["oldest_sequence"].as_u64(),
                shipped.first().copied(),
                "oldest_sequence is the oldest item shipped, rider or not"
            );
            assert_eq!(page["thread_total"], json!(held));
            walked.splice(0..0, shipped);
            if !page["has_more"].as_bool().unwrap() {
                break;
            }
            before = walked.first().copied();
        }
        assert_eq!(walked, (1..=held).collect::<Vec<u64>>());
    }

    /// The Issue's conversation is where the human follows the work they asked
    /// for, so its implementation being abandoned is news there — and the
    /// mirrored event says which implementation it came from.
    #[test]
    fn abandoning_an_implementation_is_news_on_its_issue() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let (issue_id, run_id) = planned_run_in_review(&mut state, "mirror the outcome");
        state.handle(req("entity.seen", json!({ "entity_id": issue_id })));

        // The dedup rule: while the implementation is live the Issue has no row
        // of its own, so nothing mirrored onto it can ask a second time.
        let live = work_item_rows(&mut state);
        assert!(
            !live
                .iter()
                .any(|row| row["kind"] == "issue" && row["issue_id"] == json!(issue_id)),
            "{live:?}"
        );

        let abandoned = state.handle(req("run.abandon", json!({ "run_id": run_id })));
        assert_eq!(abandoned["ok"], true, "{abandoned:?}");

        let issue_thread = &state.plans[&issue_id].agents.sole_thread();
        let mirrored = issue_thread
            .items
            .iter()
            .filter_map(|item| match item {
                crate::thread::ThreadItem::Event(event)
                    if event.event == crate::thread::ThreadEventKind::Abandoned =>
                {
                    Some(event)
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            mirrored.len(),
            1,
            "one abandon, one mirrored event: {:?}",
            issue_thread.items
        );
        assert!(
            mirrored[0]
                .links
                .contains(&crate::thread::ThreadLink::Implementation {
                    issue_id: issue_id.clone(),
                    implementation_id: run_id.clone(),
                }),
            "the mirror names the implementation it came from: {:?}",
            mirrored[0]
        );

        // The finished implementation stops speaking for the issue, whose own
        // row now says why it needs reading.
        let rows = work_item_rows(&mut state);
        let issue = rows
            .iter()
            .find(|row| row["kind"] == "issue" && row["issue_id"] == json!(issue_id))
            .unwrap_or_else(|| panic!("the issue has its row back: {rows:?}"));
        assert_eq!(issue["unread"], true, "{issue:?}");
        assert_eq!(issue["unread_reason"], "abandoned", "{issue:?}");
    }

    /// A branch nobody planned has no Issue to tell. Its own conversation still
    /// records the outcome.
    #[test]
    fn abandoning_a_run_with_no_issue_mirrors_nowhere() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let run_id = adopted_run(&mut state, &repo, dir.path(), "feature-planless");

        let abandoned = state.handle(req("run.abandon", json!({ "run_id": run_id })));
        assert_eq!(abandoned["ok"], true, "{abandoned:?}");
        assert!(state.plans.is_empty(), "adoption mints no issue");
        let own = primary_thread(&state.runs[&run_id].agents);
        assert!(
            own.items.iter().any(|item| matches!(
                item,
                crate::thread::ThreadItem::Event(event)
                    if event.event == crate::thread::ThreadEventKind::Abandoned
            )),
            "{:?}",
            own.items
        );
    }

    /// Reading a stage doc IS engaging with an issue — they are a queue you
    /// triage by reading — so it stamps. A run needs an action.
    #[test]
    fn opening_a_stage_counts_as_touching_an_issue_but_reading_a_run_does_not() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let (plan_id, run_id) = planned_run_in_review(&mut state, "attention");

        // A fresh run made by implementing: the implement stamped it.
        assert_eq!(attention_of(&mut state, &run_id)["interacted"], true);

        // Reading the run changes nothing about interaction.
        let before = attention_of(&mut state, &run_id);
        state.handle(req("run.get", json!({ "run_id": run_id })));
        state.handle(req("run.diff", json!({ "run_id": run_id })));
        assert_eq!(
            attention_of(&mut state, &run_id),
            before,
            "reading is not acting"
        );

        // Opening a stage doc stamps the issue.
        let mut fresh = qa_state(&repo, dir.path());
        let plan = fresh.handle(req("plan.create", json!({ "goal": "queue item" })));
        let queued = plan_id_of(&plan);
        assert_eq!(attention_of(&mut fresh, &queued)["interacted"], false);
        fresh.handle(req(
            "plan.stage_doc",
            json!({ "plan_id": queued, "stage_id": "first-half" }),
        ));
        assert_eq!(attention_of(&mut fresh, &queued)["interacted"], true);
        let _ = plan_id;
    }

    /// A rejected verb never happened, so it cannot count as touching anything.
    #[test]
    fn a_refused_action_does_not_stamp() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let plan = state.handle(req("plan.create", json!({ "goal": "never approved" })));
        let plan_id = plan_id_of(&plan);
        let refused = state.handle(req(
            "plan.stage_approve",
            json!({ "plan_id": plan_id, "stage_id": "no-such-stage" }),
        ));
        assert_eq!(refused["ok"], false, "{refused:?}");
        assert_eq!(attention_of(&mut state, &plan_id)["interacted"], false);
    }

    /// A worktree Build cut is something you asked for, so it arrives already
    /// touched and surfaces in the rail. One made outside Build waits in the
    /// Worktrees row until you act on it here.
    #[test]
    fn a_build_made_worktree_arrives_touched_and_a_hand_made_one_does_not() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let project_id = state.projects[0].id.clone();

        let created = state.handle(req(
            "worktree.create",
            json!({ "project_id": project_id, "name": "spike" }),
        ));
        let build_made = created["result"]["worktree_id"]
            .as_str()
            .unwrap()
            .to_string();

        add_external_worktree(&repo, dir.path(), "by-hand", "by-hand");
        state.scan_external_worktrees_now(&project_id).unwrap();
        let hand_made = state
            .scan_external_worktrees_now(&project_id)
            .unwrap()
            .into_iter()
            .find(|w| w.branch.as_deref() == Some("by-hand"))
            .expect("the hand-made worktree is discoverable")
            .id;

        assert_eq!(attention_of(&mut state, &build_made)["interacted"], true);
        assert_eq!(attention_of(&mut state, &hand_made)["interacted"], false);
    }

    /// Seen is versioned: looking at something does not make it seen forever.
    #[test]
    fn seeing_an_entity_lasts_only_until_it_moves() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let (_, run_id) = planned_run_in_review(&mut state, "seen versioning");

        assert_eq!(attention_of(&mut state, &run_id)["seen"], false);
        let seen = state.handle(req("entity.seen", json!({ "entity_id": run_id })));
        assert_eq!(seen["ok"], true, "{seen:?}");
        assert_eq!(attention_of(&mut state, &run_id)["seen"], true);

        // It moves on: unseen again, without anyone clearing a flag.
        std::thread::sleep(Duration::from_millis(1100));
        state.handle(req("run.abandon", json!({ "run_id": run_id })));
        assert_eq!(attention_of(&mut state, &run_id)["seen"], false);
    }

    /// The pulse means "an agent is working here", which is a different claim
    /// from "a tab is open". A shell is never an agent; an agent that has
    /// stopped painting is waiting for you, not working; and a dead agent's
    /// retained screen is not a heartbeat.
    ///
    /// The signal is read off the worktree's agent TAB now, not off a
    /// terminal's kind — a tab is the only place an agent can be, so there is
    /// nowhere else for the pulse to come from.
    #[tokio::test]
    async fn only_a_recently_painting_agent_counts_as_working() {
        let (dir, repo) = init_repo();
        let (state, _handler, root) = agent_tab_fixture(&repo, dir.path(), "run-pulse");
        ensure_agent_tab(
            &state,
            &root,
            "run-pulse",
            &crate::agent::derived_agent_id("run-pulse"),
            &ModelChoice::default(),
        )
        .unwrap();

        let key = derived_agent_key(&AppState::canonical_root(&root), "run-pulse");
        let mut s = state.lock().unwrap();
        let agent = s.tabs.get(&key).expect("the agent tab");
        assert!(
            agent_is_working(agent),
            "a freshly spawned agent has just painted"
        );

        // A dead agent's retained screen is not a heartbeat: the tab still holds
        // the last thing it painted, and that is a corpse, not progress.
        let dead = {
            let agent = s.tabs.get_mut(&key).unwrap();
            agent.live = false;
            let dead = agent_is_working(agent);
            agent.live = true; // restore: the next case is about a LIVE agent
            dead
        };
        assert!(!dead, "a dead agent's retained screen is not a heartbeat");

        // Left at its prompt overnight: the tab is live, the process is running,
        // and it has painted nothing since the window closed. That agent is
        // waiting for YOU — a pulse here teaches the human to ignore the pulse.
        let parked = {
            let agent = s.tabs.get_mut(&key).unwrap();
            assert!(
                agent_is_working(agent),
                "still working right up until it falls silent"
            );
            agent
                .session
                .backdate_last_output(AGENT_WORKING_WINDOW + Duration::from_secs(1));
            assert!(agent.live, "the tab is live");
            assert!(
                !matches!(agent.session.status(), AgentStatus::Ended { .. }),
                "and its process still running"
            );
            agent_is_working(agent)
        };
        assert!(
            !parked,
            "an agent parked at its prompt is waiting for you, not working"
        );

        // The human's own shell is never an agent, however busy it looks.
        let shell_root = AppState::canonical_root(&repo);
        let (shell, _rx) = Tab::spawn(
            TabRole::Shell,
            &shell_harness_spec("/bin/bash"),
            "term-77".to_string(),
            shell_root.clone(),
            80,
            24,
            None,
        )
        .expect("a shell tab spawns");
        assert!(!agent_is_working(&shell));
        shell.session.end();
    }

    /// What a dictated session was asked to do, still readable once the daemon
    /// owns the session itself — an `Arc<dyn AgentSession>` in a tab cannot be
    /// looked inside, so the record lives beside it.
    #[derive(Clone, Default)]
    struct SessionLog {
        turns: Arc<Mutex<Vec<String>>>,
        ended: Arc<std::sync::atomic::AtomicBool>,
    }

    impl SessionLog {
        /// Every turn the daemon has handed this session, in order.
        fn turns(&self) -> Vec<String> {
            self.turns.lock().unwrap().clone()
        }

        /// Whether the daemon has ended this session, waiting out the
        /// retirement thread that carries the kill.
        fn ended(&self) -> bool {
            settles(|| self.ended.load(std::sync::atomic::Ordering::Relaxed))
        }
    }

    /// A session that reports what it is told to, and remembers what was asked
    /// of it.
    ///
    /// It has no terminal and no process, so nothing about it can be inferred
    /// from paint or from a wait — a caller reading a PTY would find no answer
    /// here at all. Only a caller that asks the session gets one.
    struct DictatedSession {
        status: AgentStatus,
        quiet: Duration,
        log: SessionLog,
        surfaces: Option<AgentSurfaces>,
        watched_surface_revision: Option<tokio::sync::watch::Receiver<u64>>,
        active_model: Option<String>,
    }

    impl DictatedSession {
        /// A session reporting `status`, silent for no time at all.
        fn reporting(status: AgentStatus) -> DictatedSession {
            DictatedSession {
                status,
                quiet: Duration::ZERO,
                log: SessionLog::default(),
                surfaces: None,
                watched_surface_revision: None,
                active_model: None,
            }
        }

        fn showing_surfaces(mut self, surfaces: AgentSurfaces) -> DictatedSession {
            self.surfaces = Some(surfaces);
            self
        }

        fn moving_surfaces_on(self, revision: SurfaceRevision) -> DictatedSession {
            self.watching_a_revision_the_caller_can_close(revision.subscribe())
        }

        fn watching_a_revision_the_caller_can_close(
            mut self,
            watched: tokio::sync::watch::Receiver<u64>,
        ) -> DictatedSession {
            self.watched_surface_revision = Some(watched);
            self
        }

        /// The same session, with nothing heard from it for `quiet` — the
        /// anomaly clock the idle sweep demotes on.
        fn silent_for(mut self, quiet: Duration) -> DictatedSession {
            self.quiet = quiet;
            self
        }

        /// The same session, recording what it is asked into `log`.
        fn recording_into(mut self, log: &SessionLog) -> DictatedSession {
            self.log = log.clone();
            self
        }

        fn announcing_model(mut self, model: &str) -> DictatedSession {
            self.active_model = Some(model.to_string());
            self
        }
    }

    impl AgentSession for DictatedSession {
        fn send_turn(&self, turn: &Turn) -> Result<(), HarnessError> {
            self.log.turns.lock().unwrap().push(turn.text.clone());
            Ok(())
        }
        fn status(&self) -> AgentStatus {
            self.status
        }
        fn quiet_for(&self) -> Duration {
            self.quiet
        }
        fn active_model(&self) -> Option<String> {
            self.active_model.clone()
        }
        fn exited_within(&self, _timeout: Duration) -> bool {
            matches!(self.status, AgentStatus::Ended { .. })
        }
        fn end(&self) {
            self.log
                .ended
                .store(true, std::sync::atomic::Ordering::Relaxed);
        }
        fn backdate_last_output(&self, _ago: Duration) {}
        fn surfaces(&self) -> Option<AgentSurfaces> {
            self.surfaces.clone()
        }
        fn surfaces_changed(&self) -> Option<tokio::sync::watch::Receiver<u64>> {
            self.watched_surface_revision.clone()
        }
    }

    /// A live tab whose session reports `status`.
    fn tab_reporting(role: TabRole, status: AgentStatus) -> Tab {
        tab_running(role, DictatedSession::reporting(status))
    }

    /// A live tab carrying `session`, rooted nowhere in particular.
    fn tab_running(role: TabRole, session: DictatedSession) -> Tab {
        Tab {
            tab_id: "term-status".to_string(),
            root: PathBuf::from("/nowhere"),
            role,
            created_at: now_rfc3339(),
            session: Arc::new(session),
            // `DictatedSession` says nothing about terminals, so it has none —
            // and a tab with no terminal has no grid, because the two are made
            // together. A screen here would be the flag that disagrees with
            // reality.
            screen: None,
            live: true,
            call_sequences: HashMap::new(),
            last_delivered_at: None,
        }
    }

    /// An agent tab rooted at `root` whose session has no terminal — the shape
    /// a session protocol has.
    ///
    /// Built by hand so a test can put a session in a state it chooses. The
    /// headless provider produces the real thing —
    /// `the_terminal_verbs_refuse_the_headless_agent_the_daemon_spawned` walks
    /// the refusals against a child the daemon spawned — and this stays for the
    /// tests that need a session reporting a dictated status rather than
    /// whatever a real one happens to be doing.
    fn terminal_free_agent_tab(root: &std::path::Path, owner: &str, agent_id: &str) -> Tab {
        dictated_agent_tab(
            root,
            owner,
            agent_id,
            DictatedSession::reporting(AgentStatus::Working),
        )
    }

    fn a_run_with_a_reporting_tab(
        run_id: &str,
    ) -> (tempfile::TempDir, Arc<Mutex<AppState>>, TabKey) {
        a_run_with_a_dictated_tab(run_id, DictatedSession::reporting(AgentStatus::Working))
    }

    fn a_run_with_a_dictated_tab(
        run_id: &str,
        session: DictatedSession,
    ) -> (tempfile::TempDir, Arc<Mutex<AppState>>, TabKey) {
        let (dir, repo) = init_repo();
        let mut app = qa_state(&repo, dir.path());
        let root = insert_run(&mut app, &repo, dir.path(), run_id, RunState::Building);
        let key = insert_dictated_agent_tab(&mut app, &root, run_id, session);
        (dir, app.shared(), key)
    }

    /// A live agent tab at `root` carrying a session that reports exactly what
    /// it was told — the only way a test can put a turn-boundary carrier where
    /// the daemon expects one, since a PTY can only be asked about paint.
    fn dictated_agent_tab(
        root: &std::path::Path,
        owner: &str,
        agent_id: &str,
        session: DictatedSession,
    ) -> Tab {
        Tab {
            tab_id: agent_tab_id(agent_id),
            root: root.to_path_buf(),
            role: TabRole::Agent {
                owner: owner.to_string(),
                agent_id: agent_id.to_string(),
                provider: AgentProvider::default(),
            },
            created_at: now_rfc3339(),
            session: Arc::new(session),
            screen: None,
            live: true,
            call_sequences: HashMap::new(),
            last_delivered_at: None,
        }
    }

    /// Poll `look` until it answers, or give up after `budget`.
    ///
    /// A pump runs on its own task, so a test speaks about what it did by
    /// waiting for the thing itself — never by sleeping a guess and asserting
    /// on whatever had happened by then.
    async fn wait_for<T>(budget: Duration, mut look: impl FnMut() -> Option<T>) -> Option<T> {
        let deadline = std::time::Instant::now() + budget;
        loop {
            if let Some(found) = look() {
                return Some(found);
            }
            if std::time::Instant::now() >= deadline {
                return None;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
    }

    /// Wait for every turn the verbs just run queued to have been delivered.
    ///
    /// The queue is taken and its owners marked in flight under the acquisition
    /// the verb's own reply comes out of, so a caller that has its reply and
    /// finds neither is looking at a delivery that has finished.
    async fn wait_for_deliveries(state: &Arc<Mutex<AppState>>) {
        wait_for(Duration::from_secs(20), || {
            let s = state.lock().unwrap();
            (s.pending_agent_turns.is_empty() && s.turns_in_flight.is_empty()).then_some(())
        })
        .await
        .expect("every queued turn reached its agent");
    }

    /// Wait for the tab a queued turn's delivery opens.
    ///
    /// A verb answers as soon as its own state change is durable and the turn
    /// it queued is delivered on a thread of its own, so the reply is never the
    /// moment the agent tab arrives.
    async fn wait_for_agent_tab(state: &Arc<Mutex<AppState>>, key: &TabKey) {
        wait_for(Duration::from_secs(10), || {
            state.lock().unwrap().tabs.contains_key(key).then_some(())
        })
        .await
        .unwrap_or_else(|| panic!("the delivery never opened {key:?}"));
    }

    fn activity_rows(thread: &crate::thread::Thread) -> Vec<crate::thread::ThreadEvent> {
        thread
            .items
            .iter()
            .filter_map(|item| match item {
                crate::thread::ThreadItem::Event(event)
                    if event.event.class() == crate::thread::EventClass::Status
                        && matches!(
                            event.event,
                            crate::thread::ThreadEventKind::Reasoning
                                | crate::thread::ThreadEventKind::ToolUse
                                | crate::thread::ThreadEventKind::ToolResult
                                | crate::thread::ThreadEventKind::Narration
                                | crate::thread::ThreadEventKind::TaskUpdate
                        ) =>
                {
                    Some(event.clone())
                }
                _ => None,
            })
            .collect()
    }

    fn activity_of(
        thread: &crate::thread::Thread,
    ) -> Vec<(crate::thread::ThreadEventKind, String)> {
        activity_rows(thread)
            .into_iter()
            .map(|event| (event.event, event.summary.unwrap_or_default()))
            .collect()
    }

    /// What a session with no terminal has instead of a screen: its reasoning,
    /// tool calls, narration and background work, landing in the conversation
    /// the human already reads.
    ///
    /// The five kinds are `Status`, so an agent thinking out loud moves no
    /// unread count — that is the property that makes putting activity in the
    /// conversation safe, and it is asserted here rather than assumed.
    #[tokio::test]
    async fn a_reporting_session_pumps_its_work_into_the_conversation() {
        let (dir, repo) = init_repo();
        let mut app = qa_state(&repo, dir.path());
        let root = insert_run(
            &mut app,
            &repo,
            dir.path(),
            "run-activity",
            RunState::Building,
        );
        let agent_id = crate::agent::derived_agent_id("run-activity");
        let key = derived_agent_key(&root, "run-activity");
        app.tabs.insert(
            key.clone(),
            terminal_free_agent_tab(&root, "run-activity", &agent_id),
        );
        // Everything on the conversation so far has been read, so anything the
        // badge shows after this is the activity's doing.
        app.handle(req("entity.seen", json!({ "entity_id": "run-activity" })));
        let state = app.shared();

        let (activity, subscribed) = broadcast::channel(16);
        spawn_activity_pump(&state, key.clone(), Some(subscribed));
        for reported in [
            crate::harness::AgentActivity::Reasoning {
                summary: "the index is unused".into(),
            },
            crate::harness::AgentActivity::ToolUse {
                call_id: "toolu_1".into(),
                summary: "Read bridge/src/app.rs".into(),
            },
            crate::harness::AgentActivity::ToolResult {
                call_id: "toolu_1".into(),
                outcome: crate::harness::ToolOutcome::Ok,
                summary: "fn main() {}".into(),
            },
            crate::harness::AgentActivity::Narration {
                summary: "dropped the index".into(),
            },
            crate::harness::AgentActivity::TaskUpdate {
                summary: "reindex the archive — started".into(),
            },
        ] {
            activity
                .send(crate::harness::ActivityReport::own_work(reported))
                .expect("the pump is listening");
        }

        // Four rows for five reports: the answer completes the call's row
        // rather than minting one of its own.
        let reported = wait_for(Duration::from_secs(5), || {
            let s = state.lock().unwrap();
            let reported = activity_of(primary_thread(&s.runs["run-activity"].agents));
            (reported.len() == 4).then_some(reported)
        })
        .await
        .expect("the reported work reaches the conversation");
        assert_eq!(
            reported,
            vec![
                (
                    crate::thread::ThreadEventKind::Reasoning,
                    "the index is unused".to_string()
                ),
                (
                    crate::thread::ThreadEventKind::ToolUse,
                    "Read bridge/src/app.rs\n→ fn main() {}".to_string()
                ),
                (
                    crate::thread::ThreadEventKind::Narration,
                    "dropped the index".to_string()
                ),
                (
                    crate::thread::ThreadEventKind::TaskUpdate,
                    "reindex the archive — started".to_string()
                ),
            ],
            "in the order the agent did them"
        );

        let mut s = state.lock().unwrap();
        let view = s.handle(req("run.get", json!({ "run_id": "run-activity" })));
        assert_eq!(
            view["result"]["unread_count"], 0,
            "an agent working is not an agent addressing anyone: {view:?}"
        );
    }

    /// The death rites a no-terminal carrier would otherwise fall through.
    ///
    /// The byte pump performs them when the PTY closes — the tab stops being
    /// live, the conversation's session lineage ends. A session that paints
    /// nothing has no PTY to close, so its activity stream ending is the same
    /// moment, and the same two things have to happen: without them a dead
    /// agent's tab reads as live and its run stays in session until the idle
    /// sweep explains the exit as silence.
    #[tokio::test]
    async fn the_activity_stream_closing_ends_the_session_the_way_a_pty_eof_does() {
        let (dir, repo) = init_repo();
        let mut app = qa_state(&repo, dir.path());
        let root = insert_run(&mut app, &repo, dir.path(), "run-rites", RunState::Building);
        let agent_id = crate::agent::derived_agent_id("run-rites");
        let key = derived_agent_key(&root, "run-rites");
        app.tabs.insert(
            key.clone(),
            terminal_free_agent_tab(&root, "run-rites", &agent_id),
        );
        primary_thread_mut(&mut app.runs.get_mut("run-rites").unwrap().agents).start_session(
            "claude",
            None,
            None,
            "build",
            &now_rfc3339(),
        );
        let state = app.shared();
        assert_eq!(open_session_count(&state, "run-rites"), 1);

        let (activity, subscribed) = broadcast::channel(4);
        spawn_activity_pump(&state, key.clone(), Some(subscribed));
        drop(activity);

        wait_for(Duration::from_secs(5), || {
            (open_session_count(&state, "run-rites") == 0).then_some(())
        })
        .await
        .expect("the session lineage closes when the stream does");
        let s = state.lock().unwrap();
        assert!(
            !s.tabs[&key].live,
            "and the tab stops reading as live, so nothing else has to guess"
        );
        assert!(
            s.tabs.contains_key(&key),
            "the tab is RETAINED, exactly as an agent tab whose PTY ended is"
        );
    }

    /// Put `run_id` on the headless provider, running `spec`.
    ///
    /// Both the launch config a delivery reads (the entity's model choice) and
    /// the one the rail reads before there is a session (the agent's own) are
    /// set, because a real provider change sets both and a test that moved only
    /// one would prove the daemon agrees with itself when it does not.
    fn run_on_a_headless_provider(
        state: &Arc<Mutex<AppState>>,
        repo: &std::path::Path,
        run_id: &str,
        spec: HarnessSpec,
    ) -> ModelChoice {
        let choice = a_headless_provider_running(state, repo, spec);
        let mut s = state.lock().unwrap();
        let run = s.runs.get_mut(run_id).expect("the run");
        run.model_choice = choice.clone();
        run.agents.resolve_mut(None).expect("its agent").choice = choice.clone();
        choice
    }

    /// The whole path, end to end: a human says something to a run whose
    /// provider has no terminal, and what comes back is a conversation.
    ///
    /// Nothing here is hand-built — the daemon picks the carrier off the
    /// provider, opens a real child, hands it the turn as a value, and the
    /// activity pump posts what the child reported into the thread the human
    /// reads. The child is a fake stream-json harness replaying a recording of
    /// what claude says; no model turn is ever run.
    ///
    /// Then it leaves, the way a real one does when its work is over, and the
    /// death rites the byte pump owes a PTY are owed here too.
    #[tokio::test]
    async fn a_headless_agent_turns_a_message_into_activity_and_leaves() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let root = insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-headless");
        let key = derived_agent_key(&root, "run-headless");
        use crate::harness::adk::fake;
        run_on_a_headless_provider(
            &state,
            &repo,
            "run-headless",
            fake::stream_json_harness_that_leaves(&[
                fake::THINKING,
                fake::TOOL_USE,
                fake::TOOL_RESULT,
                fake::NARRATION,
                fake::RESULT,
            ]),
        );
        // Everything said so far has been read, so an unread entry after this
        // is the activity's doing.
        let posted = call(
            &handler,
            "thread.post",
            json!({ "entity_id": "run-headless", "body": "drop the index" }),
        );
        assert_eq!(posted["ok"], true, "{posted:?}");
        call(
            &handler,
            "entity.seen",
            json!({ "entity_id": "run-headless" }),
        );

        // Three rows for four protocol lines: the call and its answer are ONE
        // row, updated in place when the answer arrived.
        let reported = wait_for(Duration::from_secs(10), || {
            let s = state.lock().unwrap();
            let reported = activity_of(primary_thread(&s.runs["run-headless"].agents));
            (reported.len() == 3).then_some(reported)
        })
        .await
        .expect("the turn's work reaches the conversation");
        assert_eq!(
            reported,
            vec![
                (
                    crate::thread::ThreadEventKind::Reasoning,
                    "the index is unused".to_string()
                ),
                (
                    crate::thread::ThreadEventKind::ToolUse,
                    "Read bridge/src/app.rs\n→ fn main() {}".to_string()
                ),
                (
                    crate::thread::ThreadEventKind::Narration,
                    "dropped the index".to_string()
                ),
            ],
            "in the order the child reported them, and saying what it said"
        );
        {
            let s = state.lock().unwrap();
            let calls = tool_call_rows(primary_thread(&s.runs["run-headless"].agents));
            assert_eq!(calls.len(), 1, "{calls:?}");
            assert_eq!(calls[0].outcome, Some(crate::thread::ToolCallOutcome::Ok));
            assert!(
                calls[0].updated_sequence > calls[0].sequence,
                "the row was updated in place, so every cursor re-ships it: {:?}",
                calls[0]
            );
        }

        // The child answered its one turn and left. Both rites the byte pump
        // performs on PTY EOF are owed here, and nothing else in the daemon
        // learns a harness died on its own.
        wait_for(Duration::from_secs(10), || {
            let s = state.lock().unwrap();
            let lineage = &primary_thread(&s.runs["run-headless"].agents).sessions;
            // Opened by the cold delivery and closed by the pump — asserted as
            // one thing, because a lineage that was never opened would satisfy
            // "nothing is open" without a rite having been performed.
            (lineage.len() == 1 && lineage[0].ended_at.is_some()).then_some(())
        })
        .await
        .expect("the session Build opened is closed when the child's stream ends");
        assert_eq!(open_session_count(&state, "run-headless"), 0);
        let listed = call(
            &handler,
            "agent.list",
            json!({ "entity_id": "run-headless" }),
        );
        let bubble = &listed["result"]["agents"][0];
        assert_eq!(
            bubble["has_terminal"], false,
            "the rail never offers a basement this provider has none of: {bubble:?}"
        );
        assert_eq!(
            bubble["working"], false,
            "and an agent that has left is not working: {bubble:?}"
        );
        let view = call(&handler, "run.get", json!({ "run_id": "run-headless" }));
        assert_eq!(
            view["result"]["unread_count"], 0,
            "an agent working is not an agent addressing anyone: {view:?}"
        );

        let s = state.lock().unwrap();
        assert!(!s.tabs[&key].live, "the tab stops reading as live");
        assert!(
            s.tabs[&key].screen.is_none(),
            "and never had a grid to be retained"
        );
    }

    /// Put a headless agent on `run_id` running `spec`, deliver `body`, and
    /// wait until its tool-call rows read as `want`.
    ///
    /// The wait is for the rows themselves rather than for a clock: the pump
    /// runs on its own task, and an update lands on a row the conversation
    /// already holds — so a test that slept a guess could not tell an answer
    /// that had not arrived yet from one that never would.
    async fn tool_calls_after_a_turn(
        state: &Arc<Mutex<AppState>>,
        handler: &FrameHandler,
        repo: &std::path::Path,
        run_id: &str,
        spec: HarnessSpec,
        body: &str,
        want: &[(String, Option<crate::thread::ToolCallOutcome>)],
    ) {
        run_on_a_headless_provider(state, repo, run_id, spec);
        let posted = call(
            handler,
            "thread.post",
            json!({ "entity_id": run_id, "body": body }),
        );
        assert_eq!(posted["ok"], true, "{posted:?}");
        let rows = wait_for(Duration::from_secs(10), || {
            let s = state.lock().unwrap();
            let rows = tool_calls_of(primary_thread(&s.runs[run_id].agents));
            (rows == want).then_some(rows)
        })
        .await;
        assert!(
            rows.is_some(),
            "the conversation reads {:?}, wanted {want:?}",
            tool_calls_of(primary_thread(&state.lock().unwrap().runs[run_id].agents))
        );
    }

    /// A failed answer lands on the call it answers like any other, and the
    /// failure travels as the outcome — the row itself stays toneless, because
    /// a tool that failed is the agent's problem and not a call for the human.
    #[tokio::test]
    async fn a_failed_answer_closes_the_call_it_answers() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-failed-tool");
        use crate::harness::adk::fake;
        tool_calls_after_a_turn(
            &state,
            &handler,
            &repo,
            "run-failed-tool",
            fake::stream_json_harness(&[fake::TOOL_USE, fake::ERROR_TOOL_RESULT, fake::RESULT]),
            "read the file",
            &[(
                "Read bridge/src/app.rs\n→ File does not exist. Note: your current working \
                 directory is /work."
                    .to_string(),
                Some(crate::thread::ToolCallOutcome::Error),
            )],
        )
        .await;

        let view = call(&handler, "run.get", json!({ "run_id": "run-failed-tool" }));
        assert_eq!(
            view["result"]["unread_count"], 0,
            "a failed tool call still asks the human for nothing: {view:?}"
        );
    }

    /// The pairing is by id, and only by id: two calls answered in the reverse
    /// order each land on their own row. Adjacency would have crossed them.
    #[tokio::test]
    async fn two_calls_answered_out_of_order_land_on_their_own_rows() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-two-calls");
        use crate::harness::adk::fake;
        tool_calls_after_a_turn(
            &state,
            &handler,
            &repo,
            "run-two-calls",
            fake::stream_json_harness(&[
                fake::TOOL_USE,
                fake::SECOND_TOOL_USE,
                fake::SECOND_TOOL_RESULT,
                fake::TOOL_RESULT,
                fake::RESULT,
            ]),
            "read both",
            &[
                (
                    "Read bridge/src/app.rs\n→ fn main() {}".to_string(),
                    Some(crate::thread::ToolCallOutcome::Ok),
                ),
                (
                    "Read bridge/src/thread.rs\n→ pub struct Thread".to_string(),
                    Some(crate::thread::ToolCallOutcome::Ok),
                ),
            ],
        )
        .await;
    }

    /// The degraded path, kept alive: an answer to a call this session never
    /// announced has no row to land on, so it mints the standalone
    /// `tool_result` row every answer used to mint. Stored rows must render
    /// forever, and this is what still produces one.
    #[tokio::test]
    async fn an_answer_to_a_call_nobody_announced_mints_a_row_of_its_own() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-orphan");
        use crate::harness::adk::fake;
        run_on_a_headless_provider(
            &state,
            &repo,
            "run-orphan",
            fake::stream_json_harness(&[fake::ORPHAN_TOOL_RESULT, fake::NARRATION, fake::RESULT]),
        );
        let posted = call(
            &handler,
            "thread.post",
            json!({ "entity_id": "run-orphan", "body": "read the file" }),
        );
        assert_eq!(posted["ok"], true, "{posted:?}");

        let reported = wait_for(Duration::from_secs(10), || {
            let s = state.lock().unwrap();
            let reported = activity_of(primary_thread(&s.runs["run-orphan"].agents));
            (reported.len() == 2).then_some(reported)
        })
        .await
        .expect("the orphan answer reaches the conversation");
        assert_eq!(
            reported[0],
            (
                crate::thread::ThreadEventKind::ToolResult,
                "an answer to nothing".to_string()
            ),
            "exactly the row this kind always minted"
        );
        assert!(
            tool_call_rows(primary_thread(
                &state.lock().unwrap().runs["run-orphan"].agents
            ))
            .is_empty(),
            "and no call row was invented to hang it on"
        );
    }

    /// A call the interrupted turn left open closes honestly: no answer ever
    /// arrived, so the row says which boundary ended it rather than going on
    /// claiming to run.
    ///
    /// The second turn is the fence. Its call pairs into a fresh row, which
    /// proves the drain emptied both maps — the reader's and the pump's —
    /// rather than leaving the first turn's id behind to swallow it.
    #[tokio::test]
    async fn a_call_an_interrupted_turn_left_open_closes_as_unanswered() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-unanswered");
        use crate::harness::adk::fake;
        tool_calls_after_a_turn(
            &state,
            &handler,
            &repo,
            "run-unanswered",
            fake::stream_json_harness_turn_by_turn(&[
                &[fake::TOOL_USE, fake::FAILED_RESULT],
                &[
                    fake::SECOND_TOOL_USE,
                    fake::SECOND_TOOL_RESULT,
                    fake::RESULT,
                ],
            ]),
            "read the file",
            &[(
                "Read bridge/src/app.rs\n→ no answer — turn ended".to_string(),
                Some(crate::thread::ToolCallOutcome::Unanswered),
            )],
        )
        .await;

        let posted = call(
            &handler,
            "thread.post",
            json!({ "entity_id": "run-unanswered", "body": "try the other one" }),
        );
        assert_eq!(posted["ok"], true, "{posted:?}");
        let rows = wait_for(Duration::from_secs(10), || {
            let s = state.lock().unwrap();
            let rows = tool_calls_of(primary_thread(&s.runs["run-unanswered"].agents));
            (rows.len() == 2).then_some(rows)
        })
        .await
        .expect("the next turn's call pairs into a row of its own");
        assert_eq!(
            rows[1],
            (
                "Read bridge/src/thread.rs\n→ pub struct Thread".to_string(),
                Some(crate::thread::ToolCallOutcome::Ok)
            ),
        );
    }

    #[tokio::test]
    async fn a_subagents_rows_fold_under_the_call_that_spawned_them() {
        let (_dir, state, key) = a_run_with_a_reporting_tab("run-folded");

        let reported = crate::harness::adk::reports_minted_by(
            crate::harness::stream_fixtures::SUBAGENT_FIXTURE,
        );
        let (activity, subscribed) = broadcast::channel(reported.len());
        spawn_activity_pump(&state, key.clone(), Some(subscribed));
        for report in reported {
            activity.send(report).expect("the pump is listening");
        }

        let folded = wait_for(Duration::from_secs(5), || {
            let s = state.lock().unwrap();
            let rows = activity_rows(primary_thread(&s.runs["run-folded"].agents));
            let folded: Vec<crate::thread::ThreadEvent> = rows
                .iter()
                .filter(|row| row.parent_sequence.is_some())
                .cloned()
                .collect();
            (folded.len() == 4).then_some(folded)
        })
        .await
        .expect("the subagent's four rows reach the conversation");

        let spawning_call_row = {
            let s = state.lock().unwrap();
            let thread = primary_thread(&s.runs["run-folded"].agents);
            tool_call_rows(thread)
                .into_iter()
                .find(|row| {
                    row.summary
                        .as_deref()
                        .unwrap_or_default()
                        .starts_with("Agent")
                })
                .expect("the Agent call minted a row")
        };
        assert_eq!(
            folded
                .iter()
                .map(|row| (row.event, row.parent_sequence))
                .collect::<Vec<_>>(),
            vec![
                (
                    crate::thread::ThreadEventKind::Reasoning,
                    Some(spawning_call_row.sequence)
                ),
                (
                    crate::thread::ThreadEventKind::ToolUse,
                    Some(spawning_call_row.sequence)
                ),
                (
                    crate::thread::ThreadEventKind::Reasoning,
                    Some(spawning_call_row.sequence)
                ),
                (
                    crate::thread::ThreadEventKind::Narration,
                    Some(spawning_call_row.sequence)
                ),
            ],
            "every row the subagent minted names the call that spawned it"
        );
        assert_eq!(
            folded[1].outcome,
            Some(crate::thread::ToolCallOutcome::Ok),
            "and the subagent's own call is answered on its own folded row"
        );
        assert_eq!(
            spawning_call_row.outcome,
            Some(crate::thread::ToolCallOutcome::Ok),
            "the Agent call was answered on line 12: {spawning_call_row:?}"
        );

        drop(activity);
        wait_for(Duration::from_secs(5), || {
            (!state.lock().unwrap().tabs[&key].live).then_some(())
        })
        .await
        .expect("the stream closing ends the session");
        let s = state.lock().unwrap();
        let after_close = tool_call_rows(primary_thread(&s.runs["run-folded"].agents))
            .into_iter()
            .find(|row| row.sequence == spawning_call_row.sequence)
            .expect("the Agent call's row is still there");
        assert_eq!(
            after_close.outcome,
            Some(crate::thread::ToolCallOutcome::Ok),
            "a call answered while the session ran is not re-resolved when it ends: {after_close:?}"
        );
        assert!(
            s.tabs[&key].call_sequences.is_empty(),
            "and the session's pairing dies with it"
        );
    }

    #[tokio::test]
    async fn a_report_naming_a_call_with_no_row_lands_flat() {
        let (_dir, state, key) = a_run_with_a_reporting_tab("run-orphan");

        let (activity, subscribed) = broadcast::channel(4);
        spawn_activity_pump(&state, key.clone(), Some(subscribed));
        activity
            .send(crate::harness::ActivityReport {
                activity: crate::harness::AgentActivity::Reasoning {
                    summary: "counting the characters".into(),
                },
                parent_call_id: Some("toolu_done".into()),
            })
            .expect("the pump is listening");

        let rows = wait_for(Duration::from_secs(5), || {
            let s = state.lock().unwrap();
            let rows = activity_rows(primary_thread(&s.runs["run-orphan"].agents));
            (!rows.is_empty()).then_some(rows)
        })
        .await
        .expect("the row is minted rather than dropped");
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].summary.as_deref(), Some("counting the characters"));
        assert_eq!(
            rows[0].parent_sequence, None,
            "a call with no row of its own can never be a parent: {:?}",
            rows[0]
        );
    }

    /// The death rites close what the turn boundary never saw. A session that
    /// dies over an open call leaves a row claiming to run, and no later event
    /// would ever contradict it — so the pump closes it, and closes it BEFORE
    /// the session-ended row, so the timeline reads calls-closed-then-session-
    /// ended rather than a session ending over work that still claims to run.
    #[tokio::test]
    async fn the_death_rites_close_the_calls_the_session_died_over() {
        let (_dir, state, key) = a_run_with_a_reporting_tab("run-died");
        primary_thread_mut(
            &mut state
                .lock()
                .unwrap()
                .runs
                .get_mut("run-died")
                .unwrap()
                .agents,
        )
        .start_session("claude", None, None, "build", &now_rfc3339());

        let (activity, subscribed) = broadcast::channel(4);
        spawn_activity_pump(&state, key.clone(), Some(subscribed));
        activity
            .send(crate::harness::ActivityReport::own_work(
                crate::harness::AgentActivity::ToolUse {
                    call_id: "toolu_1".into(),
                    summary: "Bash npm test".into(),
                },
            ))
            .expect("the pump is listening");
        wait_for(Duration::from_secs(5), || {
            let s = state.lock().unwrap();
            (!tool_call_rows(primary_thread(&s.runs["run-died"].agents)).is_empty()).then_some(())
        })
        .await
        .expect("the call reaches the conversation");

        drop(activity);
        let closed = wait_for(Duration::from_secs(5), || {
            let s = state.lock().unwrap();
            let rows = tool_call_rows(primary_thread(&s.runs["run-died"].agents));
            rows.first().filter(|row| row.outcome.is_some()).cloned()
        })
        .await
        .expect("the call the session died over is closed");
        assert_eq!(
            closed.summary.as_deref(),
            Some("Bash npm test\n→ no answer — session ended")
        );
        assert_eq!(
            closed.outcome,
            Some(crate::thread::ToolCallOutcome::Unanswered)
        );

        wait_for(Duration::from_secs(5), || {
            (open_session_count(&state, "run-died") == 0).then_some(())
        })
        .await
        .expect("and the rites otherwise ran exactly as they do today");
        let s = state.lock().unwrap();
        let ended = primary_thread(&s.runs["run-died"].agents)
            .items
            .iter()
            .rev()
            .find_map(|item| match item {
                crate::thread::ThreadItem::Event(event)
                    if event.event == crate::thread::ThreadEventKind::SessionEnded =>
                {
                    Some(event.sequence)
                }
                _ => None,
            })
            .expect("the session lineage closed");
        assert!(
            closed.updated_sequence < ended,
            "the calls close before the session does: {closed:?} then {ended}"
        );
        assert!(
            s.tabs[&key].call_sequences.is_empty(),
            "and the pairing is cleared beside the tab going not live"
        );
    }

    fn a_branch_whose_agent_runs(
        branch: &str,
        session: DictatedSession,
    ) -> (tempfile::TempDir, AppState, String) {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let run_id = adopted_run(&mut state, &repo, dir.path(), branch);
        let agent_id = primary_agent_id(&state, &run_id);
        let root = state
            .entity_agent_root(&run_id)
            .expect("the branch has a checkout");
        insert_agent_tab(&mut state, &root, &run_id, &agent_id, session);
        (dir, state, run_id)
    }

    fn agent_digests_within(payload: &Value) -> Vec<Value> {
        match payload {
            Value::Object(fields) => fields
                .iter()
                .flat_map(|(name, value)| match name.as_str() {
                    "agents" => value.as_array().cloned().unwrap_or_default(),
                    "agent" if value.is_object() => vec![value.clone()],
                    _ => agent_digests_within(value),
                })
                .collect(),
            Value::Array(entries) => entries.iter().flat_map(agent_digests_within).collect(),
            _ => Vec::new(),
        }
    }

    fn assert_no_digest_carries_surfaces(verb: &str, payload: &Value) {
        let digests = agent_digests_within(payload);
        assert!(
            !digests.is_empty(),
            "{verb} answered with no agent digest at all, so it pins nothing: {payload:?}"
        );
        for digest in digests {
            assert!(
                digest.get("surfaces").is_none(),
                "{verb} carried surfaces on a list-shaped answer: {digest:?}"
            );
        }
    }

    #[test]
    fn branch_get_carries_the_open_agents_surfaces() {
        let (dir, mut state, run_id) = a_branch_whose_agent_runs(
            "feature-surfaced",
            DictatedSession::reporting(AgentStatus::Working)
                .showing_surfaces(recorded_workflow_surfaces()),
        );
        let agent_id = primary_agent_id(&state, &run_id);
        let project_id = state.projects[0].id.clone();

        let answered = state.handle(req(
            "branch.get",
            json!({
                "project_id": project_id,
                "branch": "feature-surfaced",
                "agent_id": agent_id,
                "thread_after_sequence": 0
            }),
        ));

        assert_eq!(answered["ok"], true, "{answered:?}");
        let row = &answered["result"];
        assert_eq!(
            row["run"]["agents"][0]["surfaces"]["workflows"][0]["name"], "readme-analysis",
            "{row:?}"
        );
        assert_eq!(
            row["agents"][0]["surfaces"]["subagents"][0]["id"], SUBAGENT_TASK_ID,
            "the rail reads a branch's agents off the row: {row:?}"
        );

        let repo_path = state.projects[0].repo_path.clone();
        add_external_worktree(&repo_path, dir.path(), "bare-checkout", "feature-bare");
        state
            .scan_external_worktrees_now(&project_id)
            .expect("the new checkout is discoverable");

        let bare = state.handle(req(
            "branch.get",
            json!({ "project_id": project_id, "branch": "feature-bare" }),
        ));
        assert_eq!(bare["ok"], true, "{bare:?}");
        let bare = &bare["result"];
        assert!(bare["run"].is_null(), "{bare:?}");
        assert_eq!(
            bare["agents"],
            json!([]),
            "a bare checkout has no run view to take agents from, so the rail still reads the candidate row's own array: {bare:?}"
        );
        drop(dir);
    }

    fn the_only_digest_carrying_surfaces(verb: &str, payload: &Value) -> Value {
        let surfaced: Vec<Value> = agent_digests_within(payload)
            .into_iter()
            .filter_map(|digest| digest.get("surfaces").cloned())
            .collect();
        assert_eq!(
            surfaced.len(),
            1,
            "{verb} answered with {} surfaced digests: {payload:?}",
            surfaced.len()
        );
        surfaced[0].clone()
    }

    #[test]
    fn every_detail_verb_carries_the_open_agents_surfaces() {
        let (dir, mut state, run_id) = a_branch_whose_agent_runs(
            "feature-detailed",
            DictatedSession::reporting(AgentStatus::Working)
                .showing_surfaces(recorded_workflow_surfaces()),
        );
        let issue_id = plan_id_of(&state.handle(req(
            "plan.create",
            json!({ "goal": "an issue with a surfaced agent" }),
        )));
        let started = state.handle(req(
            "thread.post",
            json!({ "entity_id": issue_id, "body": "start" }),
        ));
        assert_eq!(started["ok"], true, "{started:?}");
        let issue_agent = primary_agent_id(&state, &issue_id);
        let issue_root = state
            .entity_agent_root(&issue_id)
            .expect("the issue's agent works in the primary checkout");
        insert_agent_tab(
            &mut state,
            &issue_root,
            &issue_id,
            &issue_agent,
            DictatedSession::reporting(AgentStatus::Working)
                .showing_surfaces(recorded_workflow_surfaces()),
        );

        for (verb, params) in [
            ("run.get", json!({ "run_id": run_id })),
            ("issue.get", json!({ "issue_id": issue_id })),
            ("plan.get", json!({ "plan_id": issue_id })),
        ] {
            let answered = state.handle(req(verb, params));
            assert_eq!(answered["ok"], true, "{verb}: {answered:?}");
            let surfaces = the_only_digest_carrying_surfaces(verb, &answered["result"]);
            assert_eq!(
                surfaces["workflows"][0]["id"], WORKFLOW_TASK_ID,
                "{verb}: {surfaces:?}"
            );
        }
        drop(dir);
    }

