    #[tokio::test]
    async fn a_session_that_ends_keeps_the_model_it_last_ran() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let root = insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-outlives");
        let agent_id = crate::agent::derived_agent_id("run-outlives");
        run_on_a_headless_provider(
            &state,
            &repo,
            "run-outlives",
            HarnessSpec::new("sh").arg("-c").arg("exit 0"),
        );
        {
            let mut s = state.lock().unwrap();
            s.resume_id_probe = Arc::new(|_, _, _| true);
            let run = s.runs.get_mut("run-outlives").expect("the run");
            run.model_choice.model = Some("claude-opus-5".to_string());
            let agent = run.agents.resolve_mut(None).expect("its agent");
            agent.resume_session_id = Some("sess-gone".to_string());
        }

        let posted = call(
            &handler,
            "thread.post",
            json!({ "entity_id": "run-outlives", "body": "carry on" }),
        );
        assert_eq!(posted["ok"], true, "{posted:?}");
        let key = derived_agent_key(&root, "run-outlives");
        wait_for(Duration::from_secs(10), || {
            let s = state.lock().unwrap();
            (!s.tabs.get(&key)?.live).then_some(())
        })
        .await
        .expect("the child leaves on its own");
        wait_for(Duration::from_secs(10), || {
            let s = state.lock().unwrap();
            s.recorded_resume_id("run-outlives", &agent_id)
                .is_none()
                .then_some(())
        })
        .await
        .expect("a session that announced nothing sends the next spawn back to the probe");

        assert_eq!(
            state
                .lock()
                .unwrap()
                .recorded_active_model("run-outlives", &agent_id)
                .as_deref(),
            Some("claude-opus-5"),
            "what an agent last ran on outlives the session that ran it"
        );
    }

    /// The close arm RECORDS; it never clears.
    ///
    /// The headless pump clears on a session that ended having announced
    /// nothing, because for that carrier it means a dead `--resume` id. A
    /// terminal resumed in place legitimately writes no new transcript, so its
    /// locator finding nothing is the normal answer — and clearing on it would
    /// throw a good name away at every restart. The dead-name problem is
    /// answered at the reservation instead.
    #[tokio::test]
    async fn a_terminal_that_named_nothing_keeps_the_name_its_record_already_had() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let root = insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-quiet");
        let agent_id = crate::agent::derived_agent_id("run-quiet");
        every_terminal_names_its_conversation(&state, None);
        {
            let agent = Agent::WarmBuilder(Arc::new(
                |_prompt: &str, _choice: &ModelChoice, _options: &SpawnOptions| {
                    HarnessSpec::new("sh")
                        .arg("-c")
                        .arg("printf '\\033[?2004h'; exit 0")
                },
            ));
            let mut s = state.lock().unwrap();
            let worktrees = s.worktrees_root.clone();
            s.resume_id_probe = Arc::new(|_, _, _| true);
            s.projects[0].orch =
                Orchestrator::new(repo.clone(), worktrees, agent, Templates::default());
            s.runs
                .get_mut("run-quiet")
                .expect("the run")
                .agents
                .resolve_mut(None)
                .expect("its agent")
                .resume_session_id = Some("sess-resumed-in-place".to_string());
        }

        let posted = call(
            &handler,
            "thread.post",
            json!({ "entity_id": "run-quiet", "body": "carry on" }),
        );
        assert_eq!(posted["ok"], true, "{posted:?}");
        let key = derived_agent_key(&root, "run-quiet");
        wait_for(Duration::from_secs(10), || {
            let s = state.lock().unwrap();
            (!s.tabs.get(&key)?.live).then_some(())
        })
        .await
        .expect("the harness leaves on its own");

        capture_conversation_names(&state);
        assert_eq!(
            state
                .lock()
                .unwrap()
                .recorded_resume_id("run-quiet", &agent_id)
                .as_deref(),
            Some("sess-resumed-in-place"),
            "a terminal that wrote no new transcript keeps the conversation it resumed"
        );
    }

    /// Record every spawn this daemon's orchestrator builds, over a checkout
    /// that already holds somebody's transcript — the setup both adoption
    /// tests need to read what the spawn rule decided.
    fn spawns_over_an_old_transcript(
        state: &Arc<Mutex<AppState>>,
        repo: &std::path::Path,
    ) -> Arc<Mutex<Vec<SpawnOptions>>> {
        let specs_built: Arc<Mutex<Vec<SpawnOptions>>> = Arc::new(Mutex::new(Vec::new()));
        let recorder = Arc::clone(&specs_built);
        let agent = Agent::WarmBuilder(Arc::new(
            move |_prompt: &str, _choice: &ModelChoice, options: &SpawnOptions| {
                recorder.lock().unwrap().push(options.clone());
                warm_tui_spec()
            },
        ));
        let mut s = state.lock().unwrap();
        let worktrees = s.worktrees_root.clone();
        s.transcript_probe = Arc::new(|_, _| true);
        s.projects[0].orch =
            Orchestrator::new(repo.to_path_buf(), worktrees, agent, Templates::default());
        drop(s);
        specs_built
    }

    /// Adoption inherits nothing, walked end to end.
    ///
    /// The conversation the human was having in the checkout they adopted is one
    /// Build never heard: its conversation view for this agent starts at
    /// sequence 1, so a session resumed under it would show an agent answering
    /// messages that are nowhere on screen. A new agent is a new conversation,
    /// on an adopted branch like anywhere else.
    #[tokio::test]
    async fn an_adopted_entitys_first_spawn_starts_a_conversation_of_its_own() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let root = insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-adoptee");
        let specs_built = spawns_over_an_old_transcript(&state, &repo);
        // What both adoption mints write down.
        state
            .lock()
            .unwrap()
            .runs
            .get_mut("run-adoptee")
            .expect("the run")
            .adopted = true;

        let posted = call(
            &handler,
            "thread.post",
            json!({ "entity_id": "run-adoptee", "body": "have a look at this" }),
        );
        assert_eq!(posted["ok"], true, "{posted:?}");

        wait_for_deliveries(&state).await;
        let spawned = specs_built
            .lock()
            .unwrap()
            .first()
            .cloned()
            .expect("the message starts the agent");
        assert_eq!(spawned.cwd, AppState::canonical_root(&root));
        assert!(
            !spawned.continue_session,
            "the first agent on an adopted branch inherits no conversation: {spawned:?}"
        );
        assert_eq!(
            spawned.resume_session_id, None,
            "and names none either: {spawned:?}"
        );
    }

    /// The live incoherence this rule ends: an adopted branch whose agents were
    /// all removed and one added back inherited an entire prior session.
    ///
    /// Removing the roster took the session lineage with it, so the branch read
    /// as freshly adopted again and the pickup fired a second time. The agent
    /// the human then talked to answered out of a history no view of Build's
    /// holds. A record with no sessions of its own is a fresh conversation,
    /// whatever the entity has been through.
    #[tokio::test]
    async fn an_agent_added_back_to_an_old_adopted_branch_starts_fresh() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-readopted");
        let specs_built = spawns_over_an_old_transcript(&state, &repo);
        let removable = {
            let mut s = state.lock().unwrap();
            let run = s.runs.get_mut("run-readopted").expect("the run");
            run.adopted = true;
            // The branch has been worked in: a session of Build's own opened on
            // it after the adoption.
            primary_thread_mut(&mut run.agents).start_session(
                "claude",
                None,
                None,
                "implementation",
                "2026-08-30T00:00:00Z",
            );
            run.agents
                .agents()
                .iter()
                .map(|agent| agent.id.clone())
                .collect::<Vec<_>>()
        };
        for agent_id in removable {
            let removed = call(
                &handler,
                "agent.remove",
                json!({ "entity_id": "run-readopted", "agent_id": agent_id }),
            );
            assert_eq!(removed["ok"], true, "{removed:?}");
        }

        let posted = call(
            &handler,
            "thread.post",
            json!({ "entity_id": "run-readopted", "body": "start over" }),
        );
        assert_eq!(posted["ok"], true, "{posted:?}");

        wait_for_deliveries(&state).await;
        let spawned = specs_built
            .lock()
            .unwrap()
            .first()
            .cloned()
            .expect("the message creates the agent that hears it, and starts it");
        assert!(
            !spawned.continue_session,
            "the agent that replaced the roster has a conversation of its own to \
             have: {spawned:?}"
        );
        assert_eq!(
            spawned.resume_session_id, None,
            "and no name to spend: {spawned:?}"
        );
    }

    /// A dead name costs ZERO restarts, not one.
    ///
    /// The recorded id is checked against the provider's own tree before it is
    /// spent, so an id whose conversation is gone — deleted, or written by the
    /// other provider an agent was switched away from — is cleared where it is
    /// read and the spawn falls back to the rule below it, instead of burning a
    /// session finding out.
    #[tokio::test]
    async fn a_recorded_name_the_provider_no_longer_holds_is_cleared_before_it_is_spent() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-poisoned");
        let agent_id = crate::agent::derived_agent_id("run-poisoned");

        let specs_built: Arc<Mutex<Vec<SpawnOptions>>> = Arc::new(Mutex::new(Vec::new()));
        {
            let recorder = Arc::clone(&specs_built);
            let agent = Agent::WarmBuilder(Arc::new(
                move |_prompt: &str, _choice: &ModelChoice, options: &SpawnOptions| {
                    recorder.lock().unwrap().push(options.clone());
                    warm_tui_spec()
                },
            ));
            let mut s = state.lock().unwrap();
            let worktrees = s.worktrees_root.clone();
            s.resume_id_probe = Arc::new(|_, _, _| false);
            s.projects[0].orch =
                Orchestrator::new(repo.clone(), worktrees, agent, Templates::default());
            s.runs
                .get_mut("run-poisoned")
                .expect("the run")
                .agents
                .resolve_mut(None)
                .expect("its agent")
                .resume_session_id = Some("sess-gone".to_string());
        }

        let posted = call(
            &handler,
            "thread.post",
            json!({ "entity_id": "run-poisoned", "body": "are you still there" }),
        );
        assert_eq!(posted["ok"], true, "{posted:?}");

        wait_for_deliveries(&state).await;
        let spawned = specs_built
            .lock()
            .unwrap()
            .first()
            .cloned()
            .expect("the message starts the agent");
        assert_eq!(
            spawned.resume_session_id, None,
            "a name the provider does not hold is never spent: {spawned:?}"
        );
        assert_eq!(
            state
                .lock()
                .unwrap()
                .recorded_resume_id("run-poisoned", &agent_id),
            None,
            "and the apply phase forgets it, so no later spawn spends it either"
        );
    }

    /// Step 3's refusals, live in production for the first time.
    ///
    /// Until a provider answered `has_terminal` false, every terminal verb's
    /// refusal was walked only by tests that built the terminal-free session by
    /// hand. This drives the real one: a headless agent the daemon spawned, and
    /// every verb a client could reach its basement through.
    #[tokio::test]
    async fn the_terminal_verbs_refuse_the_headless_agent_the_daemon_spawned() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let root = insert_run_without_agent(&state, &repo, dir.path().join("side"), "run-refused");
        let key = derived_agent_key(&root, "run-refused");
        use crate::harness::adk::fake;
        run_on_a_headless_provider(
            &state,
            &repo,
            "run-refused",
            fake::stream_json_harness(&[fake::RESULT]),
        );
        let posted = call(
            &handler,
            "thread.post",
            json!({ "entity_id": "run-refused", "body": "have a look" }),
        );
        assert_eq!(posted["ok"], true, "{posted:?}");
        wait_for(Duration::from_secs(10), || {
            let s = state.lock().unwrap();
            s.tabs
                .get(&key)
                .filter(|tab| tab.session_is_live())
                .map(|_| ())
        })
        .await
        .expect("the headless agent is running");
        let term_id = key.tab_id.clone();

        let attached = call(&handler, "agent.attach", json!({ "id": "run-refused" }));
        assert_eq!(attached["ok"], false, "{attached:?}");
        let refusal = attached["error"].as_str().unwrap().to_string();
        assert!(
            refusal.contains(&term_id) && refusal.contains("conversation"),
            "the refusal names the agent and where its work is read: {refusal}"
        );
        for (method, params) in [
            ("term.attach", json!({ "term_id": term_id })),
            (
                "term.input",
                json!({ "term_id": term_id, "data": b64encode(b"ls\r") }),
            ),
            (
                "term.resize",
                json!({ "term_id": term_id, "cols": 100, "rows": 30 }),
            ),
            ("term.ack", json!({ "term_id": term_id, "cursor": 0 })),
        ] {
            let refused = call(&handler, method, params);
            assert_eq!(refused["error"], json!(refusal), "{method}: {refused:?}");
        }

        state.lock().unwrap().tabs[&key].session.end();
    }

    /// The terminal verbs refuse an agent whose session has no terminal, and
    /// say where that agent's work actually is.
    ///
    /// Following `require_shell_kind`: never fall back. Swallowing keystrokes
    /// no process will read, or answering `ok` to a resize of a grid that does
    /// not exist, is the same silent-wrong-program failure that refusal exists
    /// to prevent — and here it would leave a human typing into a void.
    #[test]
    fn the_terminal_verbs_refuse_an_agent_with_no_terminal() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let agent_id = "agent-protocol";
        state.lock().unwrap().tabs.insert(
            TabKey::agent(&root, agent_id),
            terminal_free_agent_tab(&root, "run-protocol", agent_id),
        );
        let term_id = agent_tab_id(agent_id);

        let typed = call(
            &handler,
            "term.input",
            json!({ "term_id": term_id, "data": b64encode(b"ls\r") }),
        );
        assert_eq!(typed["ok"], false, "{typed:?}");
        let refusal = typed["error"].as_str().unwrap().to_string();
        assert!(
            refusal.contains(&term_id) && refusal.contains("conversation"),
            "the refusal names the agent and where its work is read: {refusal}"
        );

        let resized = call(
            &handler,
            "term.resize",
            json!({ "term_id": term_id, "cols": 100, "rows": 30 }),
        );
        assert_eq!(
            resized["ok"], false,
            "a viewport means nothing to a session with no grid: {resized:?}"
        );
        assert_eq!(resized["error"], json!(refusal));
    }

    /// Attaching to a terminal-free agent refuses the same way, whichever verb
    /// asks — `agent.attach` by what a surface holds, `term.attach` by wire id.
    /// One capability, one question, one answer.
    #[tokio::test]
    async fn agent_attach_refuses_an_agent_with_no_terminal() {
        let (dir, repo) = init_repo();
        let (state, handler) = shared_qa_state_and_handler(&repo, dir.path());
        let root = AppState::canonical_root(&repo);
        let agent_id = "agent-protocol";
        let project_id = {
            let mut s = state.lock().unwrap();
            s.tabs.insert(
                TabKey::agent(&root, agent_id),
                terminal_free_agent_tab(&root, "run-protocol", agent_id),
            );
            s.projects[0].id.clone()
        };

        let attached = call(
            &handler,
            "agent.attach",
            json!({ "project_id": project_id }),
        );
        assert_eq!(attached["ok"], false, "{attached:?}");
        assert!(
            attached["error"].as_str().unwrap().contains("conversation"),
            "{attached:?}"
        );

        let by_wire = call(
            &handler,
            "term.attach",
            json!({ "term_id": agent_tab_id(agent_id) }),
        );
        assert_eq!(by_wire["error"], attached["error"], "{by_wire:?}");

        // A client that was never allowed to attach has nothing to acknowledge
        // either, and hears why rather than acking into a screen that does not
        // exist.
        let acked = call(
            &handler,
            "term.ack",
            json!({ "term_id": agent_tab_id(agent_id), "cursor": 0 }),
        );
        assert_eq!(acked["error"], attached["error"], "{acked:?}");
    }

    fn agent_role() -> TabRole {
        TabRole::Agent {
            owner: "run-status".to_string(),
            agent_id: "agent-status".to_string(),
            provider: AgentProvider::Claude,
        }
    }

    /// The pulse is whatever the session says it is doing, and the daemon does
    /// not second-guess it with the terminal's own signals. The age of the last
    /// paint is how a PTY — which has no better answer — synthesizes its
    /// status; a harness that knows its own turn boundaries has to be able to
    /// contradict it.
    #[test]
    fn the_pulse_reads_the_session_status_and_nothing_else() {
        let cases = [
            (AgentStatus::Working, true),
            (AgentStatus::Waiting, false),
            (AgentStatus::Starting, false),
            (AgentStatus::Ended { code: Some(0) }, false),
            (AgentStatus::Ended { code: None }, false),
        ];
        for (status, working) in cases {
            assert_eq!(
                agent_is_working(&tab_reporting(agent_role(), status)),
                working,
                "{status:?}"
            );
        }
    }

    /// The two conjuncts the session cannot see survive the move: a shell is
    /// the human's own hands however busy it looks, and a tab whose stream has
    /// ended is holding a corpse, not a heartbeat.
    #[test]
    fn a_working_status_still_needs_a_live_agent_tab() {
        assert!(!agent_is_working(&tab_reporting(
            TabRole::Shell,
            AgentStatus::Working
        )));
        let mut retained = tab_reporting(agent_role(), AgentStatus::Working);
        retained.live = false;
        assert!(!agent_is_working(&retained));
    }

    /// An agent tab whose session reports `status`, rooted where the daemon
    /// will look for it.
    fn insert_dictated_agent_tab(
        state: &mut AppState,
        root: &std::path::Path,
        owner: &str,
        session: DictatedSession,
    ) -> TabKey {
        let agent_id = crate::agent::derived_agent_id(owner);
        insert_agent_tab(state, root, owner, &agent_id, session)
    }

    fn insert_agent_tab(
        state: &mut AppState,
        root: &std::path::Path,
        owner: &str,
        agent_id: &str,
        session: DictatedSession,
    ) -> TabKey {
        let key = TabKey::agent(root, agent_id);
        state.tabs.insert(
            key.clone(),
            dictated_agent_tab(root, owner, agent_id, session),
        );
        key
    }

    /// Whether an agent is live is the same question the pulse asks, one state
    /// further out, and it is now asked the same way: a session that reports
    /// `Ended` is over, whatever a process table would have said about it.
    ///
    /// `has_exited` was how a terminal answered this. A carrier with no process
    /// behind it has no such question to poll, and it must still be able to say
    /// its session is over.
    #[test]
    fn liveness_is_read_off_the_reported_status() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        let root = insert_run(
            &mut state,
            &repo,
            dir.path(),
            "run-liveness",
            RunState::Building,
        );
        let agent_id = crate::agent::derived_agent_id("run-liveness");

        insert_dictated_agent_tab(
            &mut state,
            &root,
            "run-liveness",
            DictatedSession::reporting(AgentStatus::Waiting),
        );
        assert!(
            state.agent_is_live(&root, &agent_id),
            "a session waiting at its prompt is live"
        );
        assert_eq!(
            state.agent_digests("run-liveness", DigestScope::List)[0]["state"],
            "live"
        );

        insert_dictated_agent_tab(
            &mut state,
            &root,
            "run-liveness",
            DictatedSession::reporting(AgentStatus::Ended { code: Some(1) }),
        );
        assert!(
            !state.agent_is_live(&root, &agent_id),
            "a session that reports it is over is not live"
        );
        assert_ne!(
            state.agent_digests("run-liveness", DigestScope::List)[0]["state"],
            "live"
        );
    }

    #[test]
    fn an_agents_digest_carries_the_model_it_is_actually_running() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        insert_run(
            &mut state,
            &repo,
            dir.path(),
            "run-active-model",
            RunState::Building,
        );
        let agent_id = crate::agent::derived_agent_id("run-active-model");

        assert_eq!(
            state.agent_digests("run-active-model", DigestScope::List)[0]["active_model"],
            "",
            "an agent that has never run is running nothing Build knows of"
        );

        state.record_agent_active_model(
            "run-active-model",
            &agent_id,
            Some("claude-fable-5-1".to_string()),
        );
        assert_eq!(
            state.agent_digests("run-active-model", DigestScope::List)[0]["active_model"],
            "claude-fable-5-1"
        );

        state.record_agent_active_model(
            "run-active-model",
            &agent_id,
            Some("claude-opus-5".to_string()),
        );
        assert_eq!(
            state.agent_digests("run-active-model", DigestScope::List)[0]["active_model"],
            "claude-opus-5",
            "the newer announcement wins"
        );
    }

    #[test]
    fn an_agent_that_announced_nothing_reports_the_model_its_next_start_spends() {
        let (dir, repo) = init_repo();
        let mut state = qa_state(&repo, dir.path());
        insert_run(
            &mut state,
            &repo,
            dir.path(),
            "run-projected-model",
            RunState::Building,
        );
        let agent_id = crate::agent::derived_agent_id("run-projected-model");

        let digest = state.agent_digests("run-projected-model", DigestScope::List)[0].clone();
        assert_eq!(digest["model"], "");
        assert_eq!(digest["effort"], "");
        assert_eq!(digest["active_model"], "");

        state
            .set_entity_model_choice(
                "run-projected-model",
                ModelChoice {
                    provider: AgentProvider::default(),
                    model: Some("claude-opus-5".to_string()),
                    effort: None,
                },
            )
            .expect("the choice persists");
        let digest = state.agent_digests("run-projected-model", DigestScope::List)[0].clone();
        assert_eq!(digest["model"], "claude-opus-5");
        assert_eq!(digest["effort"], "");
        assert_eq!(
            digest["active_model"], "claude-opus-5",
            "with nothing announced, what the next start spends is what it runs"
        );

        state.record_agent_active_model(
            "run-projected-model",
            &agent_id,
            Some("claude-haiku-4-5".to_string()),
        );
        assert_eq!(
            state.agent_digests("run-projected-model", DigestScope::List)[0]["active_model"],
            "claude-haiku-4-5",
            "the session's own announcement outranks the projection"
        );
    }

